/**
 * 东财业务板块名索引（惰性构建）。
 * 语义搜索的「词 → 板块 → 成分股」全流程都基于它 + 数据中心报表，
 * 完全不经过 push2.eastmoney.com（该域名在浏览器侧会间歇性限流，是搜索为 0 的根因）。
 * @returns {Array<{name:string, code:string}>}
 */
let _eastBoardIndex = null;
function eastBoardIndex() {
  if (!_eastBoardIndex) {
    _eastBoardIndex = EAST_BOARD_LIST.map(s => {
      const i = s.lastIndexOf(':');
      return { name: s.slice(0, i), code: s.slice(i + 1) };
    });
  }
  return _eastBoardIndex;
}

/** 限制并发的 map（批量拉取板块成分股时避免触发限流） */
async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let i = 0;
  async function worker() {
    while (i < items.length) {
      const idx = i++;
      results[idx] = await fn(items[idx], idx);
    }
  }
  const n = Math.min(limit, items.length);
  const workers = [];
  for (let k = 0; k < n; k++) workers.push(worker());
  await Promise.all(workers);
  return results;
}

/** 板块名称与概念本体的相关度评分（用于排序：越相关越优先被纳入交叉匹配） */
function semanticNameScore(name, canon) {
  const n = String(name).toLowerCase();
  const c = String(canon).toLowerCase();
  if (n === c) return 100;
  if (n.startsWith(c)) return 80;
  if (n.includes(c)) return 60;
  return 10;
}

/** 由收盘价序列计算日收益率序列（不含股息，足够用于联动相关性分析） */
function _returns(closes) {
  const r = [];
  for (let i = 1; i < closes.length; i++) {
    const a = closes[i - 1], b = closes[i];
    if (a > 0 && isFinite(b)) r.push((b - a) / a);
  }
  return r;
}

/** 皮尔逊相关系数（衡量两个收益率序列的线性相关强度，范围 [-1,1]） */
function _pearson(a, b) {
  const n = Math.min(a.length, b.length);
  if (n < 2) return NaN;
  let sa = 0, sb = 0;
  for (let i = 0; i < n; i++) { sa += a[i]; sb += b[i]; }
  const ma = sa / n, mb = sb / n;
  let num = 0, da = 0, db = 0;
  for (let i = 0; i < n; i++) {
    const x = a[i] - ma, y = b[i] - mb;
    num += x * y; da += x * x; db += y * y;
  }
  if (da === 0 || db === 0) return NaN;
  return num / Math.sqrt(da * db);
}

/** 解析修饰词（核心/龙头、小市值） */
function parseSemanticModifiers(query) {
  const m = [];
  if (/(核心|龙头|主营|主营业务|业务|代表性|核心标的|正宗|纯正|核心公司)/.test(query)) m.push('核心');
  if (/(小市值|小盘|微小盘|次新)/.test(query)) m.push('小市值');
  return m;
}

// ============ 语义 → 主营构成匹配（营收占比相关度） ============
// 从自然语言查询抽取「业务/产品」匹配词，并聚合命中概念的主营段名匹配词，
// 用于把候选公司的「主营构成」段名与语义描述做子串匹配，命中段营收占比之和即相关度。

/** 停用词：从查询里剔除，避免「的/为/企业」等噪声成为段名匹配词 */
const SEMANTIC_STOPWORDS = new Set([
  '的', '为', '是', '了', '和', '与', '及', '或', '在', '有', '做', '找', '整理', '生产', '企业', '上市', '公司',
  '主营', '核心', '龙头', '我们', '请', '帮', '我', '等', '哪些', '什么', '列出', '给出', '筛选', '选出', '符合',
  '业务', '产品', '占', '营收', '比例', '收入', '主要', '从事', '关于', '相关', '一个', '一种', '进行', '提供',
  '服务', '技术', '方案', '系统', '平台', '分析', '研究', '推荐', '希望', '想', '需要', '如何', '怎么', '哪家',
  '正宗', '纯正', '标的', '概念', '板块', '股票', '股', '梳理', '罗列', '一共', '全部', '所有', '分别', '各自',
  '以及', '并且', '同时', '既', '又', '该', '这个', '这些', '那些', '一家', '一些'
]);

/**
 * 通用类别词：单独作为匹配词时无区分度，禁止独立成词。
 * 否则「发电设备」被拆成「设备」会误匹配所有设备股、「锂电池」被拆成「电池」误匹配所有电池股。
 */
const GENERIC_CATEGORY_NOUNS = new Set([
  '设备', '机器', '仪器', '仪表', '装置', '装备', '系统', '材料', '原料', '产品', '部件', '零件',
  '组件', '器件', '模组', '模块', '平台', '技术', '方案', '服务', '业务', '软件', '硬件', '芯片',
  '电池', '电机', '工具', '机构', '结构', '总成', '耗材', '用品',
  '复合', '新型', '高端', '智能', '数字', '绿色', // 泛化修饰语：单独作匹配词会命中大量无关段名（如「复合」→复合材料/复合肥）
  '电厂', '发电厂' // 宽泛环境词：单独作匹配词会误命中火电/水电运营商（其段名含「火电厂/发电厂」），但厂商段名为「电站设备/发电设备/锅炉」不含
]);

/**
 * 领域/发电方式修饰词：火电/水电/核电/风电/光伏… 单独出现只表示「发电方式」，不代表设备产品。
 * 语义搜索「火电发电设备」要的是「生产火电厂设备的厂家」，不是「火电运营商」——
 * 因此领域词不单独作为段名/板块独立匹配词（仅作领域加权），避免误匹配火电/水电运营上市公司。
 */
const DOMAIN_MODIFIERS = new Set([
  '火电', '火力', '水电', '核电', '风电', '光伏', '太阳能', '燃气', '生物质', '垃圾', '煤电',
  '燃机', '分布式', '抽水蓄能', '潮汐', '地热', '光热'
]);

/**
 * 弱产品动作词：发电/电力/生产… 单独作为匹配词无区分度（火电运营商主营也含「发电」），
 * 不单独作为段名核心命中词，仅保留 ≥3 字的产品短语（发电设备/电设备/锅炉/汽轮机）作核心匹配。
 */
const WEAK_PRODUCT_WORDS = new Set(['发电', '电力', '生产', '制造']);

/**
 * 运营商负向标志词：纯发电/供电/供热运营商的主营段名特征词。
 * 设备制造商的主营段名（发电设备/锅炉/汽轮机…）绝不含这些词；
 * 故段名含运营商标志且无任何「设备实体词」时，不计入相关度——从根本上区分「生产设备的厂商」与「运营商」。
 */
const OPERATOR_SIGNS = [
  '火力发电', '发电-电力', '发电—电力', '电力销售', '售电', '热电', '供热', '供电', '发电业务',
  '电力生产', '能源供应', '配售电', '购售电', '电力购销', '热力供应', '发电运营', '电力交易'
];
/** 设备实体词护栏：段名含这些词即视为真实设备制造业务，即便同时出现运营商标志也不排除 */
const PRODUCT_ENTITY = [
  '设备', '锅炉', '汽轮机', '发电机', '机组', '磨煤机', '给水泵', '电机', '变压器', '电缆',
  '阀门', '压缩机', '泵', '辅机', '超超临界', '循环流化床', '水轮', '开关', '电抗器', '电容器', '绝缘子'
];

/**
 * 去掉短语尾部的通用类别词（仅去一层），如「发电设备」→「发电」、「智能发电设备」→「智能发电」。
 * 头部词用于兼容「发电锅炉」「发电汽轮机」等具体品种写法。
 */
function stripCategorySuffix(run) {
  let s = run;
  for (const cat of GENERIC_CATEGORY_NOUNS) {
    if (s.length > cat.length && s.endsWith(cat)) {
      s = s.slice(0, s.length - cat.length);
      break;
    }
  }
  return s;
}

/**
 * 从自然语言查询抽取业务/产品匹配词（作为主营构成段名的子串）。
 * 关键约束：不要把「发电设备」拆成「发电」+「设备」分别匹配——
 *   - 完整短语保留为首要匹配词（整词优先，避免曲解本意）；
 *   - 中文 2~3 字滑动窗口仅作补充，但【剔除通用类别词碎片】（如「设备」会误命中所有设备股）；
 *   - 若短语以通用类别词结尾（如「发电设备」→头部「发电」），额外加入头部，使其能匹配「发电锅炉」等具体品种。
 * 例：「发电设备」→ ['发电设备','发电','电设','发电设','电设备']（不再含无意义的「设备」）
 */
/**
 * 抽取查询匹配词，区分「产品核心词(terms)」与「领域修饰词(domain)」。
 *  - 整词优先；2~3 字滑动窗口补充，剔除停用词、通用类别词碎片；
 *  - 领域修饰词（火电/水电/风电…）单独收集到 domain，不进入 terms（避免误匹配运营上市公司）；
 *  - 弱产品动作词（发电/电力…）不单独成词，只保留 ≥3 字产品短语作核心匹配。
 * 例：「火电发电设备」→ terms:[发电设备,火电发电设备,电设备,发电设,电设,火电发电,…]；domain:[火电]
 *     （不再含无意义的「火电」「发电」独立词）
 */
/** 判断拼接碎片是否以领域修饰词开头（如「火力发电」「火电发电」=领域词+产品词拼接，无区分度，会误命中运营上市公司） */
function termStartsWithDomain(g) {
  for (const d of DOMAIN_MODIFIERS) {
    if (g.length > d.length && g.startsWith(d)) return true;
  }
  return false;
}

/** 碎片是否含任一领域修饰词（子串，不限开头） */
function fragmentHasDomain(g) {
  for (const d of DOMAIN_MODIFIERS) {
    if (g.includes(d)) return true;
  }
  return false;
}

function extractQueryTerms(query) {
  const q = String(query || '').toLowerCase();
  const terms = new Set();
  const domain = new Set();
  const latin = q.match(/[a-z0-9]{2,}/g) || [];
  latin.forEach(t => terms.add(t));
  const cn = q.match(/[一-龥]+/g) || [];
  cn.forEach(run => {
    if (run.length <= 6) {
      if (DOMAIN_MODIFIERS.has(run)) domain.add(run);
      else terms.add(run); // 完整短语优先（整词）
    }
    for (let n = 2; n <= 3; n++) {
      for (let i = 0; i + n <= run.length; i++) {
        const g = run.slice(i, i + n);
        if (SEMANTIC_STOPWORDS.has(g)) continue;
        if (GENERIC_CATEGORY_NOUNS.has(g)) continue;
        if (DOMAIN_MODIFIERS.has(g)) { domain.add(g); continue; } // 领域词单列
        if (n === 2 && WEAK_PRODUCT_WORDS.has(g)) continue;       // 弱产品词不单独成词
        if (termStartsWithDomain(g)) continue;                    // 领域词+产品词拼接碎片（火力发电/火电发电）不单独成词，避免误命中运营商
        // 3字碎片若含「发电/电力/领域词」（力发电/电发电/火力发/发电设…），均为无独立产品意义的拼接碎片，剔除（精准匹配由「发电设备」等4字词与产品整词承担）
        if (n === 3 && (g.includes('发电') || g.includes('电力') || fragmentHasDomain(g))) continue;
        terms.add(g);
      }
    }
    const head = stripCategorySuffix(run);
    if (head && head.length >= 2 && head !== run && !termStartsWithDomain(head)) {
      if (!DOMAIN_MODIFIERS.has(head)) terms.add(head);
      for (let n = 2; n <= Math.min(3, head.length); n++) {
        for (let i = 0; i + n <= head.length; i++) {
          const g = head.slice(i, i + n);
          if (SEMANTIC_STOPWORDS.has(g) || GENERIC_CATEGORY_NOUNS.has(g) || DOMAIN_MODIFIERS.has(g)) continue;
          if (n === 2 && WEAK_PRODUCT_WORDS.has(g)) continue;
          if (termStartsWithDomain(g)) continue;
          if (n === 3 && (g.includes('发电') || g.includes('电力') || fragmentHasDomain(g))) continue;
          terms.add(g);
        }
      }
    }
  });
  return { terms: [...terms], domain: [...domain] };
}

/**
 * batch60：组词（整词短语）抽取 —— 用户填写的主业/主要产品词必须当成**一个整体**理解。
 * 例：「特种电缆」是"特种"+"电缆"组成的**一个**产品词。语义搜索 / 全市场深度扫描时
 *     必须整词匹配主营段名（段名含「特种电缆」才算命中），
 *     绝不能拆成「主营业务带特种」+「产品带电缆」两个独立条件分别命中。
 * 抽取规则：按中文连续段切分 → 剥离首尾停用词（如「主营为X的企业」→「X」）→
 *   剩余长度 ≥3 的短语视为组词；长度 2 的短语仅当它就是整个查询时才算（如「铜箔」「证券」）。
 *   纯类别词/领域词/弱产品词（设备/火电/发电…）不构成组词（无区分度，沿用原有碎片逻辑）。
 * @returns {string[]} 组词列表（整词优先，最多取 4 个）
 */
function extractCompoundPhrases(query) {
  const ql = String(query || '').toLowerCase().trim();
  if (!ql) return [];
  let runs = ql.match(/[一-龥]+/g) || [];
  const out = [];
  for (let run of runs) {
    // ① 先按单字停用词切分：「和/与/及/或/的/为…」是分隔符不是主体
    //    （注意不能把「种」「一」当分隔符，否则「特种电缆」会被拆坏）
    //    例：「特种电缆和风电叶片」→ [特种电缆, 风电叶片]
    const parts = run.split(/[的和与及或在是了为有请帮我找做等]/);
    for (let part of parts) {
      if (!part) continue;
      // ② 剥离首尾多字停用词（如「主营」「上市」「公司」），保留至少 2 字主体
      let changed = true;
      while (changed && part.length >= 2) {
        changed = false;
        for (const sw of SEMANTIC_STOPWORDS) {
          if (sw.length < 2) continue;
          if (part.length - sw.length >= 2) {
            if (part.startsWith(sw)) { part = part.slice(sw.length); changed = true; continue; }
            if (part.endsWith(sw)) { part = part.slice(0, -sw.length); changed = true; continue; }
          }
        }
      }
      if (part.length < 2 || part.length > 10) continue;
      // 2 字短语必须是「整个查询」才构成组词（如「铜箔」），否则只是碎片
      if (part.length === 2 && ql !== part) continue;
      if (SEMANTIC_STOPWORDS.has(part) || GENERIC_CATEGORY_NOUNS.has(part) ||
          DOMAIN_MODIFIERS.has(part) || WEAK_PRODUCT_WORDS.has(part)) continue;
      out.push(part);
      if (out.length >= 4) break;
    }
    if (out.length >= 4) break;
  }
  return [...new Set(out)];
}

/**
 * 把自然语言解析为语义匹配要素。
 *  - concepts：命中的概念本体（用于概念板块检索候选池 + 标签展示）
 *  - boardHints：从命中概念聚合的「板块名」匹配词（候选池发现）
 *  - segHints：从命中概念聚合的「主营构成段名」匹配词（相关度计算）
 *  - generic：从查询直接抽取的通用匹配词（同时用于板块名与段名）
 *  - compound（batch60）：组词整词短语（如「特种电缆」）。存在时 segHints **只含组词**（严格整词匹配，
 *    不再让「特种」「电缆」等碎片独立命中），原碎片词降级存入 broadSegHints 作 0 命中兜底。
 */
function buildMatchers(query) {
  const ql = String(query || '').toLowerCase();
  const concepts = [];
  const boardHints = new Set();
  const segHints = new Set();
  for (const c of SEMANTIC_CONCEPTS) {
    // 🔴 只允许「长度≥2」的别名参与子串匹配。
    // 否则单字别名会制造荒谬的误判：SEMANTIC_CONCEPTS['有色金属'] 的别名含 `铜`/`铝`，
    // 于是「复合铜箔」被判定成「有色金属」概念 → 段名匹配词变成 铜/铝/稀土/黄金 →
    // 搜出来全是铝型材、稀土永磁、黄金公司（batch45 实测复现）。
    if (c.aliases.some(a => a.length >= 2 && ql.includes(a.toLowerCase()))) {
      concepts.push(c.canonical);
      (c.hints || []).forEach(h => boardHints.add(h.toLowerCase()));
      (c.segHints || []).forEach(h => segHints.add(h.toLowerCase()));
    }
  }
  const g = extractQueryTerms(query);
  g.terms.forEach(t => { boardHints.add(t); segHints.add(t); });
  g.domain.forEach(t => { segHints.add(t); }); // 领域词只进段名（加权），不进 boardHints（不驱动运营板块）
  // batch60：组词抽取 —— 有组词时段名匹配词收严为「仅组词」，碎片词全部降级为兜底
  const compound = extractCompoundPhrases(query);
  if (compound.length) {
    compound.forEach(c => boardHints.add(c));
    return {
      concepts, boardHints: [...boardHints],
      segHints: compound.slice(),               // 严格：整词优先
      broadSegHints: [...segHints],             // 兜底：0 命中时才放宽到碎片
      generic: [...g.terms], domain: [...g.domain], compound
    };
  }
  return { concepts, boardHints: [...boardHints], segHints: [...segHints], generic: [...g.terms], domain: [...g.domain], compound: [], broadSegHints: null };
}

/** 主营构成段名是否命中任一匹配词（子串，忽略大小写） */
function segMatches(segName, matchersArr) {
  if (!segName) return false;
  const s = String(segName).toLowerCase();
  for (const m of matchersArr) if (s.includes(m)) return true;
  return false;
}

/**
 * 根据主营构成计算「营收占比相关度」。
 * 相关度 = 命中语义描述的主营业务/产品段之营收占比之和（%，0~100）。
 * 关键约束：段名【必须命中产品核心词(coreArr)之一】才计入——领域修饰词(domainArr)仅作加权，
 * 避免「火电发电设备」误命中火电运营商（其主营段仅含「火电」不含发电设备类段）。
 * @param {string[]} coreArr 产品核心匹配词（发电设备/锅炉/汽轮机…），段名必含其一
 * @param {string[]} domainArr 领域修饰词（火电/水电…），命中则相关度 ×1.15
 */
function revenueRelevance(mainBiz, coreArr, domainArr) {
  if (!mainBiz || !mainBiz.length) return { relevance: 0, raw: 0, matched: [] };
  if (!coreArr || !coreArr.length) return { relevance: 0, raw: 0, matched: [] };
  const domainSet = new Set(domainArr || []);
  let rel = 0;
  const matched = [];
  for (const seg of mainBiz) {
    const s = String(seg.name).toLowerCase();
    // 排除纯运营商段名：含运营商标志词且无任何设备实体词（火力发电及供热/发电-电力/售电/供热…），避免误匹配火电/水电运营商
    if (OPERATOR_SIGNS.some(sig => s.includes(sig)) && !PRODUCT_ENTITY.some(e => s.includes(e))) continue;
    if (!coreArr.some(m => s.includes(m))) continue; // 必含产品核心词
    const r = (seg.ratio || 0);
    let ratio = r;
    if (domainSet.size && domainArr.some(d => s.includes(d))) ratio = r * 1.15; // 领域命中加权
    rel += Math.min(ratio, 1);
    matched.push({ name: seg.name, ratio: Math.round(r * 1000) / 10 });
  }
  // relevance：展示值（封顶 100%，即「命中业务占营收比例」）
  // raw：未封顶的加权和，**专门用于排序**——避免多家都是 100% 时排序退化成都市值排序，
  //      让「命中占比更高」的公司真正排在前面（用户要求：按所占营收比例排序）。
  const capped = rel > 1 ? 1 : rel;
  return {
    relevance: Math.round(capped * 1000) / 10,
    raw: Math.round(rel * 1000) / 10,
    matched
  };
}

/** 产品级语义「相关度」评分（产品库兜底：东财未列明细分业务时按产业链角色保底） */
function scoreRoleRelevance(role) {
  const r = String(role || '');
  let s = 68;
  if (/代理|分销/.test(r)) s = 58; // 代理/分销环节：非主业自产，相关度最低
  else if (/绝对龙头|市占/.test(r)) s = 96;
  else if (/龙头/.test(r)) s = 92;
  else if (/唯一|IDM/.test(r)) s = 89;
  else if (/核心/.test(r)) s = 87;
  else if (/自研|量产|突破|送样/.test(r)) s = 78;
  else if (/验证|布局|小产线|切入|配套/.test(r)) s = 66;
  return s;
}

/**
 * 产品级语义匹配：把自然语言与 SEMANTIC_PRODUCTS 的产品/技术别名比对。
 * 命中后作为候选种子 + 段名匹配补充，最终仍由主营构成营收占比计算相关度。
 * @param {string} ql 已转小写的查询串
 * @returns {object|null}
 */
function matchProduct(ql) {
  for (const p of SEMANTIC_PRODUCTS) {
    for (const a of p.aliases) {
      if (ql.includes(a.toLowerCase())) return p;
    }
  }
  return null;
}

/**
 * 产品级语义的「段名匹配词」：只取**产品族本身**，不掺入所属概念的泛词。
 *
 * 为什么必须这样（batch45 实测）：查询「谐波减速器」会被 SEMANTIC_CONCEPTS['机器人'] 命中
 * （其别名含「减速器」），于是段名匹配词变成 机器人/电机/伺服/传感器/丝杠/具身 →
 * 结果被传感器（安培龙 100%）、微电机（晨光电机 98.8%）等「机器人泛产业链」公司占满，
 * 真正做减速器的公司反而被压到后面。用户要的是**相同业务/相同产品**，不是同属一个赛道。
 *
 * 取词规则：整词查询 + 产品库全部别名（整词）+ 查询与产品 key 的 2~3 字窗口
 * （剔除停用词 / 通用类别词（含「复合/智能/高端」等泛化修饰语）/ 领域修饰词）。
 * @param {string} query 用户原始查询
 * @param {object} product SEMANTIC_PRODUCTS 条目
 * @returns {string[]}
 */
function productCoreTerms(query, product) {
  const out = new Set();
  const add = (s) => {
    const t = String(s || '').trim().toLowerCase();
    if (t.length >= 2) out.add(t);
  };
  add(query);
  if (product) {
    add(product.key);
    (product.aliases || []).forEach(add);
  }
  // 只对「用户查询本身」切窗口。
  // 不能对 product.key 切窗口：如查询「谐波减速器」属于产品族 key「人形机器人减速器」，
  // 若对 key 切窗口会引入「机器人」「人形机」等**赛道泛词**，结果又会被机器人整机厂（瑞松科技、
  // 宇树科技）占满，真正做减速器的公司（绿的谐波、国茂股份）反被压后 —— 与「同产品」的诉求相悖。
  for (const src of [query]) {
    const q = String(src || '').toLowerCase();
    for (let n = 2; n <= 3; n++) {
      for (let i = 0; i + n <= q.length; i++) {
        const g = q.slice(i, i + n);
        if (SEMANTIC_STOPWORDS.has(g) || GENERIC_CATEGORY_NOUNS.has(g) || DOMAIN_MODIFIERS.has(g)) continue;
        out.add(g);
      }
    }
  }
  return [...out];
}

/** 行情类接口本地缓存 TTL（毫秒）—— 30 秒内同一请求直接复用，显著降低对外部接口的压力 */
const API_TTL = {
  QUOTE: 30 * 1000,        // 实时行情（腾讯 qt.gtimg.cn）
  KLINE: 5 * 60 * 1000,    // 日K线（历史数据当天不变）
  SECTOR: 60 * 1000,       // 板块列表/成分股/排行（分钟级够用）
  NEWS: 60 * 1000          // 热点/快讯
};

/** 腾讯行情单次请求的代码数上限（切片用）。
 *  实测：600 只（URL ≈5400 字符）仍正常；719 只（≈6500 字符）直接 Failed to fetch。
 *  取 200 留 3 倍余量，避免边界抖动；一个 719 只的板块只需 4 个分片（并发 4 → 1 轮）。 */
const QUOTE_CHUNK = 200;

const StockAPI = {

  // ============ 缓存与请求合并（性能层，不改动任何接口语义） ============
  //
  // 目的：同一浏览器内，多个组件/多次刷新常在同一时刻请求同一份数据（例如行情表同时
  // 拉 50 只股票、切页回来又拉一次）。这里统一做两件事：
  //   1) 结果缓存 —— key 命中且未过期则直接返回，不再打外部接口；
  //   2) 并发去重 —— 同一 key 的请求正在飞行中时，复用同一个 Promise，避免重复请求。
  // 所有对外方法签名、返回结构完全不变，调用方无需任何改动。
  _cache: new Map(),   // key -> { t, v }  已成功返回的结果
  _pending: new Map(), // key -> Promise   飞行中的请求

  /**
   * 带缓存 + 并发去重的执行包装。
   * @param {string} key 缓存键
   * @param {number} ttl 过期时间（毫秒）
   * @param {() => Promise<any>} loader 真正取数的函数
   * @param {(v:any)=>boolean} [ok] 结果有效性判定，默认「非空即有效」；无效不写缓存
   */
  _withCache(key, ttl, loader, ok) {
    const now = Date.now();
    const hit = this._cache.get(key);
    if (hit && now - hit.t < ttl) return Promise.resolve(hit.v);
    const flying = this._pending.get(key);
    if (flying) return flying;
    const p = Promise.resolve()
      .then(loader)
      .then(v => {
        const valid = ok ? !!ok(v) : (v != null);
        if (valid) this._cache.set(key, { t: Date.now(), v: v });
        this._pending.delete(key);
        return v;
      })
      .catch(e => {
        this._pending.delete(key);
        throw e;
      });
    this._pending.set(key, p);
    return p;
  },

  /** 清空缓存（仅供需要强制刷新的场景调用；正常调用方无需使用） */
  clearCache(prefix) {
    if (!prefix) { this._cache.clear(); this._pending.clear(); return; }
    for (const k of Array.from(this._cache.keys())) if (k.indexOf(prefix) === 0) this._cache.delete(k);
  },

  // ============ 代码解析 ============

  /** 根据纯数字代码推断市场前缀 */
  inferPrefix(code) {
    code = String(code).trim();
    // 已经带前缀
    if (/^(sh|sz|bj)/i.test(code)) return code.toLowerCase();
    const pure = code.replace(/\D/g, '');
    if (/^6[89]/.test(pure)) return 'sh' + pure;        // 科创板 688 / 主板 60x
    if (/^6/.test(pure)) return 'sh' + pure;             // 上海主板
    if (/^92/.test(pure)) return 'bj' + pure;            // 北交所新代码段 920xxx
    if (/^[45]/.test(pure)) return 'sh' + pure;          // 权证等
    if (/^9/.test(pure)) return 'sh' + pure;             // 沪 B 股 900xxx
    if (/^3/.test(pure)) return 'sz' + pure;             // 创业板
    if (/^0/.test(pure)) return 'sz' + pure;             // 深圳主板
    if (/^2/.test(pure)) return 'sz' + pure;
    if (/^8/.test(pure)) return 'bj' + pure;             // 北交所
    return 'sz' + pure;
  },

  /**
   * 解析用户输入的股票字符串
   * 支持：贵州茅台(600519)、600519、sh600519、贵州茅台
   * 返回 [{ code, name }]
   */
  parseStockInput(text) {
    if (!text) return [];
    const results = [];
    // 按 逗号/分号/换行 分割
    const parts = text.split(/[,;，；\n\r]+/).map(s => s.trim()).filter(Boolean);
    for (const part of parts) {
      const m = part.match(/^(.*?)\s*[（(]\s*(\d{4,8})\s*[）)]\s*$/);
      if (m) {
        results.push({ name: m[1].trim(), code: this.inferPrefix(m[2]) });
        continue;
      }
      // 纯代码
      if (/^\d{4,8}$/.test(part)) {
        results.push({ name: '', code: this.inferPrefix(part) });
        continue;
      }
      // 已带前缀
      if (/^(sh|sz|bj)\d{4,8}$/i.test(part)) {
        results.push({ name: '', code: part.toLowerCase() });
        continue;
      }
      // 纯名称（暂无代码，后续可查）
      results.push({ name: part, code: '' });
    }
    return results;
  },

  // ============ 股票搜索联想 ============

  _searchSeq: 0,
  /**
   * 联想请求必须串行：腾讯 smartbox 靠全局变量 window.v_hint 回传结果，
   * 并发发起时后返回的脚本会覆盖先返回的那份数据，表现为「多个名称只有一部分被识别」。
   * 这里用一条 Promise 尾巴把请求排队，彻底消除覆盖。
   */
  _searchTail: null,

  /**
   * 搜索股票（腾讯 smartbox 接口，通过 script 标签加载，绕过 CORS）
   * 输入名称或代码，返回联想结果
   * @returns {Array<{market, code, pureCode, name, pinyin}>}
   */
  searchStocks(keyword) {
    const kw = (keyword || '').trim();
    if (!kw) return Promise.resolve([]);
    const run = () => new Promise((resolve) => {
      const mySeq = ++this._searchSeq;
      let done = false;
      const finish = (val) => { if (done) return; done = true; clearTimeout(timer); resolve(val); };
      // 兜底：脚本既没有 onload 也没有 onerror 时，不能把整条队列永久堵死
      const timer = setTimeout(() => {
        try { if (script.parentNode) script.parentNode.removeChild(script); } catch (e) { /* 已卸载 */ }
        finish([]);
      }, 8000);
      const script = document.createElement('script');
      script.charset = 'utf-8';
      script.src = `https://smartbox.gtimg.cn/s3/?t=all&q=${encodeURIComponent(kw)}`;
      const cleanup = () => {
        if (script.parentNode) script.parentNode.removeChild(script);
        try { delete window.v_hint; } catch (e) { window.v_hint = undefined; }
      };
      script.onload = () => {
        // 只处理最新一次请求，避免快速输入时旧结果覆盖新结果
        if (mySeq !== this._searchSeq) { cleanup(); finish([]); return; }
        const raw = window.v_hint;
        cleanup();
        finish(this._parseHints(raw));
      };
      script.onerror = () => { cleanup(); finish([]); };
      document.body.appendChild(script);
    });
    const tail = this._searchTail || Promise.resolve();
    const queued = tail.then(run, run);
    this._searchTail = queued.then(() => { }, () => { });
    return queued;
  },

  _parseHints(raw) {
    if (!raw) return [];
    const items = raw.split('^');
    const results = [];
    for (const item of items) {
      const parts = item.split('~');
      if (parts.length >= 3 && parts[0] && parts[1] && parts[2]) {
        results.push({
          market: parts[0],
          code: parts[0] + parts[1],
          pureCode: parts[1],
          name: parts[2],
          pinyin: parts[3] || '',
          type: parts[4] || ''
        });
      }
    }
    return results;
  },

  // ============ 股票名称 → 代码 反查 ============
  //
  // 背景：parseStockInput 会把「宁德时代」这种纯名称解析成 { name:'宁德时代', code:'' }。
  // 没有 code，后面的行情 / K线 / 财务全都拉不到，表现就是「新建子版块后刷新不出数据」。
  // 这里补齐这一层，三级降级，前两级零请求：
  //   ① 本机已解析字典（localStorage） —— 用过的名称下次秒出，随用随积累
  //   ② 全 A 名单离线匹配              —— 复用 batch29 的名单（静态 JSON / 本机缓存）
  //   ③ 腾讯 smartbox 联网联想          —— 兜底，只有上面两级都没命中时才发请求

  NAME_MAP_LS_KEY: 'snt.name2code.v1',
  NAME_MAP_MAX: 4000,
  /** 本次会话已学会的名称表 { 归一化名称: 'sh600519' }，懒加载 */
  _nameMap: null,
  _nameMapDirty: false,
  _nameMapTimer: null,

  /** 名称归一化：全角转半角、去括号后缀、去空格、去星号、全大写 */
  _nameKey(name) {
    let s = String(name === undefined || name === null ? '' : name).trim();
    // 全角 → 半角，避免 "ＳＴ"、"１２３" 这类输入漏匹配
    s = s.replace(/[\uFF01-\uFF5E]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0xFEE0));
    s = s.replace(/[（(][^（()）]*[)）]/g, '');   // 去掉尾部的 (300750)
    s = s.replace(/\s+/g, '');
    s = s.replace(/[*＊]/g, '');                  // *ST → ST
    return s.toUpperCase();
  },

  /** 去掉风险警示前缀：ST / SST / *ST（星号已在 _nameKey 里去除） */
  _stripST(k) {
    return String(k || '').replace(/^S?ST/, '');
  },

  _loadNameMap() {
    const map = {};
    try {
      const raw = this._lsGetItem(this.NAME_MAP_LS_KEY);
      const j = raw ? JSON.parse(raw) : null;
      if (j && typeof j === 'object') {
        for (const k of Object.keys(j)) {
          if (typeof j[k] === 'string' && /^(sh|sz|bj)\d{6}$/i.test(j[k])) map[k] = String(j[k]).toLowerCase();
        }
      }
    } catch (e) { /* 数据损坏就当没有字典 */ }
    return map;
  },

  _nameMapEnsure() {
    if (!this._nameMap) this._nameMap = this._loadNameMap();
    return this._nameMap;
  },

  /** 记住一个 name→code。写盘做 1.5s 节流，避免行情刷新频繁触发 localStorage 写入 */
  _learnName(name, code) {
    const k = this._nameKey(name);
    const c = String(code || '').toLowerCase();
    if (!k || !/^(sh|sz|bj)\d{6}$/.test(c)) return;
    const map = this._nameMapEnsure();
    if (map[k] === c) return;
    map[k] = c;
    this._nameMapDirty = true;
    if (this._nameMapTimer) return;
    this._nameMapTimer = setTimeout(() => {
      this._nameMapTimer = null;
      if (!this._nameMapDirty) return;
      this._nameMapDirty = false;
      try {
        let keys = Object.keys(map);
        if (keys.length > this.NAME_MAP_MAX) {
          // 超出上限就丢掉最早学会的一批（对象对字符串键保持插入顺序）
          keys.slice(0, keys.length - this.NAME_MAP_MAX).forEach(kk => { delete map[kk]; });
        }
        this._lsSetItem(this.NAME_MAP_LS_KEY, JSON.stringify(map));
      } catch (e) { /* 配额满 / 隐私模式：忽略，不影响任何功能 */ }
    }, 1500);
  },

  /** 名称索引的会话级缓存（正负结果都缓存 60 秒，避免每次解析都去请求静态名单） */
  _nameDictCache: null,

  async _nameDict() {
    const c = this._nameDictCache;
    if (c && (Date.now() - c.t) < 60000) return c.dict;
    let dict = null;
    try { dict = await this._buildNameDict(); } catch (e) { dict = null; }
    this._nameDictCache = { t: Date.now(), dict: dict };
    return dict;
  },

  async _buildNameDict() {
    const list = await this._getAllANames();
    if (!list || !list.length) return null;
    const exact = new Map();
    for (const it of list) {
      if (!it || !it.name || !it.code) continue;
      const k = this._nameKey(it.name);
      if (!k) continue;
      if (!exact.has(k)) exact.set(k, it);
    }
    return exact.size ? { list: list, exact: exact } : null;
  },

  /** 在名单里匹配一个名称：精确 → 去ST → 唯一前缀 → 唯一包含；有歧义返回 null（交给联网兜底） */
  _nameDictHit(dict, name) {
    if (!dict) return null;
    const k = this._nameKey(name);
    if (!k) return null;

    const direct = dict.exact.get(k);
    if (direct) return direct;

    const q = this._stripST(k);
    if (q && q !== k) {
      const d2 = dict.exact.get(q);
      if (d2) return d2;
    }

    const key = q || k;
    if (key.length < 2) return null;   // 单字不猜，太容易错配

    const starts = [];
    const inc = [];
    for (const it of dict.list) {
      const nk = this._stripST(this._nameKey(it.name));
      if (!nk) continue;
      if (nk.indexOf(key) === 0) starts.push(it);
      else if (nk.indexOf(key) >= 0) inc.push(it);
    }
    if (starts.length === 1) return starts[0];
    if (starts.length > 1) return null;   // 多个前缀命中 → 歧义，不猜
    if (inc.length === 1) return inc[0];
    return null;
  },

  /** 联网兜底：腾讯 smartbox 联想，只接受 A 股 / 北交所结果（过滤指数、基金、港美股） */
  async _nameResolveOnline(name) {
    let hints = [];
    try { hints = await this.searchStocks(name); } catch (e) { return null; }
    if (!Array.isArray(hints) || !hints.length) return null;

    const isA = h => !!h && /^(sh|sz|bj)$/i.test(String(h.market || ''))
      && /^(sh|sz|bj)\d{6}$/i.test(String(h.code || ''));
    const k = this._nameKey(name);
    const q = this._stripST(k);

    let hit = hints.find(h => h && this._nameKey(h.name) === k)
      || hints.find(h => h && this._stripST(this._nameKey(h.name)) === q && q)
      || null;
    if (hit && !isA(hit)) hit = null;
    if (!hit) hit = hints.find(isA) || null;
    if (!hit) return null;
    return { name: hit.name || name, code: String(hit.code).toLowerCase() };
  },

  /**
   * 把「只有名称、没有代码」的条目补全代码（原地修改数组元素）。
   * 另外支持空格连写：整段没命中时按空格再切一次逐个试（要么全中，要么保留原样）。
   *
   * @param {Array<{name,code}>} list  parseStockInput 的输出，会被原地补全 code
   * @returns {Promise<Array<{name,code}>>} 仍未能识别的条目（空数组表示全部成功）
   */
  async resolveStockNames(list) {
    const arr = Array.isArray(list) ? list : [];
    let pend = arr.filter(s => s && s.name && !s.code);
    if (!pend.length) return [];

    // ① 本机字典，零请求
    const map = this._nameMapEnsure();
    pend = pend.filter(s => {
      const c = map[this._nameKey(s.name)];
      if (c) { s.code = c; return false; }
      return true;
    });
    if (!pend.length) return [];

    // ② 全 A 名单离线匹配，零请求
    const dict = await this._nameDict();
    if (dict) {
      // 倒序遍历：命中空格连写时会把 1 条原地替换成多条
      for (let i = arr.length - 1; i >= 0; i--) {
        const it = arr[i];
        if (!it || it.code || !it.name) continue;
        const hit = this._nameDictHit(dict, it.name);
        if (hit) {
          it.code = hit.code;
          it.name = hit.name || it.name;
          continue;
        }
        if (!/\s/.test(it.name)) continue;
        const tokens = it.name.split(/\s+/).filter(Boolean);
        if (tokens.length < 2) continue;
        const hits = [];
        let allHit = true;
        for (const t of tokens) {
          const h = this._nameDictHit(dict, t);
          if (h) hits.push(h); else { allHit = false; break; }
        }
        if (allHit) arr.splice(i, 1, ...tokens.map((t, n) => ({ name: hits[n].name || t, code: hits[n].code })));
      }
      pend = arr.filter(s => s && s.name && !s.code);
    }
    if (!pend.length) return [];

    // ③ 联网兜底：4 路并发，只有离线都没命中才会走到这里
    const CONC = 4;
    let cursor = 0;
    const runner = async () => {
      for (;;) {
        const it = pend[cursor++];
        if (!it) return;
        const hit = await this._nameResolveOnline(it.name);
        if (hit) {
          it.code = hit.code;
          it.name = hit.name || it.name;
          this._learnName(it.name, hit.code);
        }
      }
    };
    await Promise.all(Array.from({ length: Math.min(CONC, pend.length) }, runner));

    return arr.filter(s => s && s.name && !s.code);
  },

  /** 从 code 提取纯数字 */
  pureCode(code) {
    return String(code || '').replace(/^(sh|sz|bj)/i, '');
  },

  /** 东财 secid 格式：1.600519（沪）、0.000001（深） */
  toEastSecid(code) {
    const c = String(code);
    const pure = this.pureCode(c);
    if (/^sh/i.test(c) || /^bj/i.test(c)) return '1.' + pure;
    return '0.' + pure;
  },

  // ============ 实时行情 ============

  // ============ 边缘加速（batch29 第3项，可选） ============
  // 只有在「设置」里填了加速站点地址时才会生效；没填时下面的 _accelBases() 返回空数组，
  // 所有接口走的还是原来的直连路径，行为与启用前完全一致。
  ACCEL_LS_KEY: 'snt.accel.base',

  /** 取已配置的边缘加速站点列表（可能为空 → 未启用） */
  _accelBases() {
    const out = [];
    const push = (s) => {
      String(s || '').split(/[\s,;]+/).forEach(x => {
        const b = x.trim().replace(/\/+$/, '');
        if (b && out.indexOf(b) < 0) out.push(b);
      });
    };
    try {
      if (typeof localStorage !== 'undefined' && localStorage) push(localStorage.getItem(this.ACCEL_LS_KEY));
    } catch (e) { /* 隐私模式：忽略 */ }
    try {
      if (typeof window !== 'undefined' && window.__SNT_ACCEL__) push(window.__SNT_ACCEL__);
    } catch (e) { /* ignore */ }
    return out;
  },

  /** 取当前加速站点地址（空字符串表示未启用） */
  getAccelBase() {
    try {
      if (typeof localStorage !== 'undefined' && localStorage) return localStorage.getItem(this.ACCEL_LS_KEY) || '';
    } catch (e) { /* ignore */ }
    return '';
  },

  /** 设置/清除加速站点地址 */
  setAccelBase(url) {
    const v = String(url == null ? '' : url).trim().replace(/\/+$/, '');
    try {
      if (typeof localStorage !== 'undefined' && localStorage) {
        if (v) localStorage.setItem(this.ACCEL_LS_KEY, v);
        else localStorage.removeItem(this.ACCEL_LS_KEY);
      }
    } catch (e) { /* ignore */ }
    return v;
  },

  // ---- 边缘加速熔断（batch43） ----
  // 背景：加速站点域名（形如 *.workers.dev）在部分网络下是「连接被阻断」而不是快速拒绝，
  //       每次调用都要等满超时才失败。而「热门板块」一轮刷新会发起 10~20 次接口请求，
  //       若每次都白等 7 秒，整轮刷新必然超过限时 → 用户看到「刷新失败（网络/接口限流）」。
  //       实测线上配置的加速站点在国内即被拦截，这正是两个子版块长期失败的放大器。
  // 方案：连续失败达阈值即熔断一段时间，期间所有加速调用**立即返回**（零开销），
  //       冷却结束再放一次试探；一旦成功立刻恢复。失败路径从此不再拖慢直连主链路。
  _accelBreaker: { fails: 0, openUntil: 0 },
  ACCEL_FAIL_THRESHOLD: 2,          // 连续失败几次后熔断
  ACCEL_COOLDOWN: 2 * 60 * 1000,    // 熔断时长（2 分钟）
  ACCEL_TIMEOUT: 2500,              // 加速请求超时（原 6~7 秒：被墙时白等太久）

  /** 加速链路当前是否处于熔断（应直接跳过） */
  _accelOpen() {
    return Date.now() < (this._accelBreaker && this._accelBreaker.openUntil || 0);
  },
  /** 记录一次加速失败，达阈值则打开熔断 */
  _accelMarkFail() {
    const b = this._accelBreaker;
    b.fails = (b.fails || 0) + 1;
    if (b.fails >= this.ACCEL_FAIL_THRESHOLD) b.openUntil = Date.now() + this.ACCEL_COOLDOWN;
  },
  /** 加速链路恢复可用 */
  _accelMarkOk() {
    this._accelBreaker = { fails: 0, openUntil: 0 };
  },

  /**
   * 带并发上限的 map（结果顺序与输入一致；单条异常不影响其它条目）。
   * 外部接口对突发并发敏感（腾讯/新浪都会限流），统一在这里收敛并发度。
   */
  async _mapLimit(items, limit, fn) {
    const arr = Array.from(items || []);
    const out = new Array(arr.length);
    if (!arr.length) return out;
    let idx = 0;
    const n = Math.max(1, Math.min(limit || 4, arr.length));
    const worker = async () => {
      for (;;) {
        const i = idx++;
        if (i >= arr.length) return;
        try { out[i] = await fn(arr[i], i); } catch (e) { out[i] = null; }
      }
    };
    await Promise.all(Array.from({ length: n }, worker));
    return out;
  },

  /** 限时取 JSON（失败抛错，由调用方决定回退） */
  async _fetchJson(url, timeoutMs) {
    const buf = await this._fetchBytes(url, timeoutMs || 10000);
    return JSON.parse(new TextDecoder('utf-8').decode(buf));
  },

  /**
   * 竞速：并发执行多个任务，返回**最先拿到的非空结果**（对象场景，区别于 _raceFirstValid 的数组场景）。
   * 用于「同一份数据的多条取数路径同时开跑」，让最快可用的一条胜出，
   * 慢的/被墙的路径不再拖累整体耗时。全部失败则返回 null。
   */
  _raceFirstNonNull(tasks) {
    return new Promise(resolve => {
      const list = Array.isArray(tasks) ? tasks : [];
      if (!list.length) { resolve(null); return; }
      let pending = list.length, settled = false;
      for (const t of list) {
        // 同时接受「函数」与「已经在飞的 Promise」两种写法：
        // 若把 Promise 直接交给 .then()，它会被当作回调调用（Promise 不是函数）→ 静默失败。
        Promise.resolve().then(() => (typeof t === 'function' ? t() : t))
          .catch(() => null)
          .then(v => {
            if (settled) return;
            if (v) { settled = true; resolve(v); return; }
            if (--pending === 0) { settled = true; resolve(null); }
          });
      }
    });
  },

  /**
   * 限时抓取字节（失败抛错，由调用方决定回退）。
   * ⚠️ 这里刻意**不使用** cache:'no-store'：
   *   加速站点返回的响应带 `Cache-Control: public, max-age=<ttl>`，与本地 cached TTL 同的长度。
   *   用默认策略时，浏览器会在 max-age 内直接复用本地 HTTP 副本，**连 Worker 都不会请求** ——
   *   这才是「省 Cloudflare 免费额度（10 万次/天）」的关键。若改成 no-store，
   *   每次调用都会实打实算进 Worker 请求数，上万人刷新时很容易把额度打爆。
   */
  async _fetchBytes(url, timeoutMs) {
    let timer = null;
    let ctrl = null;
    let opts = {};
    // 有 AbortController 才用超时中断，没有就裸 fetch（老浏览器/受限环境也能跑）
    if (typeof AbortController !== 'undefined') {
      ctrl = new AbortController();
      timer = setTimeout(() => { try { ctrl.abort(); } catch (e) {} }, timeoutMs || 8000);
      opts.signal = ctrl.signal;
    }
    try {
      const resp = await fetch(url, opts);
      if (!resp || !resp.ok) throw new Error('HTTP ' + (resp && resp.status));
      return await resp.arrayBuffer();
    } finally {
      if (timer) clearTimeout(timer);
    }
  },

  /**
   * 经边缘站点取 GBK 文本（腾讯行情回包是 GBK）。
   * @returns {Promise<string|null>} 取到返回文本；任一站点失败返回 null
   */
  async _fetchQuoteTextViaAccel(pathSuffix) {
    const bases = this._accelBases();
    if (!bases.length) return null;
    if (this._accelOpen()) return null;          // 熔断中：立即跳过，不再白等超时
    let anyFail = false;
    for (const base of bases) {
      try {
        const buf = await this._fetchBytes(base + pathSuffix, this.ACCEL_TIMEOUT);
        const txt = new TextDecoder('gbk').decode(buf);
        if (txt && txt.indexOf('v_') >= 0) { this._accelMarkOk(); return txt; }
        anyFail = true;
      } catch (e) {
        anyFail = true;
        console.debug('[accel] 行情加速站点不可用，回退直连:', base, e && e.message);
      }
    }
    if (anyFail) this._accelMarkFail();
    return null;
  },

  /**
   * 批量获取实时行情（腾讯接口 / 边缘加速站点）
   *
   * ⚠️ 腾讯 `qt.gtimg.cn/q=` 对**单次 URL 长度**有硬上限：实测 600 只（约 5400 字符）仍 200，
   *    719 只（约 6500 字符）直接 `TypeError: Failed to fetch`（连 HTTP 状态都没有）。
   *    因此这里**必须在函数内部切片**（QUOTE_CHUNK=200，约为已验证安全值的 1/3），
   *    否则任何「一次拉整个板块」的调用（如新能源车 719 只）都会整版拿不到行情。
   *    切片 + 并发 4 + 每片独立缓存键，总请求数仍是常数级。
   * @param {string[]} codes  ['sh600519','sz000001']
   * @returns {Object} { 'sh600519': { name, code, price, ... } }
   */
  async getQuotes(codes) {
    if (!codes || !codes.length) return {};
    const valid = codes.filter(c => c);
    if (!valid.length) return {};
    // 排序 + 去重，让「同一批股票、不同书写顺序」共享同一份缓存
    const uniq = Array.from(new Set(valid)).sort();
    const out = {};
    const chunks = [];
    for (let i = 0; i < uniq.length; i += QUOTE_CHUNK) chunks.push(uniq.slice(i, i + QUOTE_CHUNK));
    const CONC = 4;
    for (let i = 0; i < chunks.length; i += CONC) {
      const wave = chunks.slice(i, i + CONC);
      const rs = await Promise.all(wave.map(c => this._getQuotesOnce(c).catch(() => ({}))));
      rs.forEach(o => { if (o) Object.assign(out, o); });
    }
    return out;
  },

  /** 单次行情请求（切片后的一个分片），带独立缓存；任何网络/解析异常都吞掉并返回 {} */
  async _getQuotesOnce(uniq) {
    const query = uniq.join(',');
    return this._withCache('q:' + query, API_TTL.QUOTE, async () => {
      // 与原实现一致：任何网络/解析异常都吞掉并返回 {}，绝不向上抛出
      try {
        // ① 边缘加速（已配置时）——Cloudflare 边缘节点在 TTL 内直接应答，回源次数与在线人数解耦
        const viaAccel = await this._fetchQuoteTextViaAccel('/q/' + query);
        if (viaAccel) {
          const parsed = this._parseQuotes(viaAccel);
          if (parsed && Object.keys(parsed).length) return parsed;
        }
        // ② 直连（原路径）
        const resp = await fetch(`https://qt.gtimg.cn/q=${query}`, { cache: 'no-store' });
        const buffer = await resp.arrayBuffer();
        const text = new TextDecoder('gbk').decode(buffer);
        return this._parseQuotes(text) || {};
      } catch (e) {
        console.error('获取行情失败', e);
        return {};
      }
    }, v => !!(v && Object.keys(v).length)); // 空对象不写缓存，避免把失败固化 30 秒
  },

  /** 获取单只股票行情 */
  async getQuote(code) {
    const r = await this.getQuotes([code]);
    return r[code] || null;
  },

  _parseQuotes(text) {
    const result = {};
    // 匹配 v_sh600519="..."; 多组
    const reg = /v_(\w+)\s*=\s*"([^"]*)"/g;
    let m;
    while ((m = reg.exec(text)) !== null) {
      const code = m[1];
      const fields = m[2].split('~');
      result[code] = this._buildQuote(code, fields);
      // 顺手沉淀 name→code：下次用户直接输名称就能匹配上，不用再查接口
      if (result[code] && result[code].name) this._learnName(result[code].name, code);
    }
    return result;
  },

  _buildQuote(code, f) {
    // 字段索引（腾讯行情标准定义）
    // 0:市场 1:名称 2:代码 3:当前价 4:昨收 5:今开
    // 6:成交量(手) 9-28:五档买卖 30:时间戳 31:涨跌额 32:涨跌幅
    // 33:最高 34:最低 38:换手率 39:市盈率 43:振幅 44:流通市值 45:总市值 46:市净率
    const current = parseFloat(f[3]) || 0;
    const yclose = parseFloat(f[4]) || 0;
    const high = parseFloat(f[33]) || 0;
    const low = parseFloat(f[34]) || 0;
    const changePct = parseFloat(f[32]);
    const amplitude = parseFloat(f[43]);
    // 兜底计算振幅
    const ampCalc = yclose > 0 ? +((high - low) / yclose * 100).toFixed(2) : 0;
    return {
      code: code,
      name: f[1] || '',
      price: current,
      yesterdayClose: yclose,
      open: parseFloat(f[5]) || 0,
      volume: parseFloat(f[6]) || 0,        // 手
      amount: parseFloat(f[37]) || 0,        // 成交额(万)
      changePercent: isNaN(changePct) ? 0 : changePct,
      high: high,
      low: low,
      amplitude: isNaN(amplitude) ? ampCalc : amplitude,   // %
      turnover: parseFloat(f[38]) || 0,      // 换手率 %
      pe: parseFloat(f[39]) || 0,            // 市盈率
      floatMarketCap: parseFloat(f[44]) || 0, // 流通市值(亿)
      totalMarketCap: parseFloat(f[45]) || 0, // 总市值(亿)
      pb: parseFloat(f[46]) || 0,            // 市净率
      timestamp: f[30] || ''
    };
  },

  // ============ 历史价格 ============

  /**
   * 获取某日期的收盘价（不复权真实价）
   * @param {string} code  sh600519
   * @param {string} date  2024-09-24
   * @returns {number|null}
   */
  async getHistoryClose(code, date) {
    const d = new Date(date);
    // 【关键修复】腾讯历史K线接口 param=...,day,,,n, 返回的是「最近 n 个交易日」，
    // 并非按 start/end 日期区间截取。旧实现只用「目标日前10天~后5天」窄窗口，经 _barCount
    // 地板值后只取回最近的 ~320 根（约到 2025 年中），远够不到 2024-09-24，导致 get924Price
    // 永远取不到价、924涨跌字段长期空白。现按「目标日 → 今天」真实跨度申请足够根数
    // （腾讯优先，东财兜底），确保覆盖目标日；根数上限 800（腾讯对过大根数会返回空）。
    const spanDays = Math.ceil((Date.now() - d.getTime()) / 86400000) + 30; // 留 30 天冗余
    const count = Math.min(800, Math.max(320, Math.ceil(spanDays * 7 / 5) + 20));
    const start = this.fmtDate(this._addDays(d, -20));
    const end = this.fmtDate(new Date());
    let data = await this.getKline(code, start, end, count);
    // 根数不足未覆盖到目标日时，加大根数重试一次（沿用能覆盖更早日期的结果）
    if (data && data.length && data[0].date > date) {
      try {
        const more = await this.getKline(code, start, end, 1600);
        if (more && more.length && more[0].date < data[0].date) data = more;
      } catch (e) { /* 重试失败则沿用原数据 */ }
    }
    if (!data || !data.length) return null;
    // 精确匹配日期
    const exact = data.find(k => k.date === date);
    if (exact) return exact.close;
    // 若目标日非交易日，取最近的前一个交易日
    let prev = null;
    for (const k of data) {
      if (k.date <= date) prev = k;
    }
    return prev ? prev.close : null;
  },

  /** 获取924收盘价（2024-09-24） */
  async get924Price(code) {
    return this.getHistoryClose(code, '2024-09-24');
  },

  /**
   * 获取日K线（不复权）
   * @returns {Array<{date,open,close,high,low,volume}>}
   */
  // 把东财 klines 文本数组解析成统一结构
  _parseEastKline(kl) {
    const out = [];
    for (const line of kl) {
      // klines 每项：日期,开盘,收盘,最高,最低,成交量,成交额,振幅,...（顺序由 fields2 决定）
      const p = String(line).split(',');
      const close = parseFloat(p[2]);
      if (!p[0] || isNaN(close)) continue;
      out.push({
        date: p[0],
        open: parseFloat(p[1]),
        close,
        high: parseFloat(p[3]),
        low: parseFloat(p[4]),
        volume: parseFloat(p[5])
      });
    }
    return out;
  },

  // 腾讯历史日K线（免费、无需鉴权；响应带 Access-Control-Allow-Origin:*，
  // 浏览器简单 fetch 即可直连，无需 JSONP）。返回 data[code].day = [日期,开,收,高,低,量]。
  //
  // 【重要】实测：该接口在「带复权参数(qfq/bfq)」或「带显式日期区间」时常返回空数据，
  // 只有形如  param={code},day,,,{根数},   （日期区间留空、复权留空）才稳定返回，
  // 语义为「最近 N 个交易日」，不复权真实价 —— 正合计算今年高低价/年初价/924价之需。
  // 多节点轮换，任一成功即用。
  async _tencentKline(code, startDate, endDate, count) {
    const pure = this.pureCode(code);
    const c = String(code).toLowerCase();
    let market = 'sh';
    if (/^sz/.test(c)) market = 'sz';
    else if (/^bj/.test(c)) market = 'bj';
    else if (/^sh/.test(c)) market = 'sh';
    else if (/^[69]/.test(pure)) market = 'sh';
    else if (/^[48]/.test(pure)) market = 'bj';
    else market = 'sz';
    const sym = market + pure;
    // 根数需覆盖区间交易日数：两年约 480 根，320 会截断导致算不出年初价/924价
    const n = count || this._barCount(startDate, endDate);
    const nodes = [
      'https://web.ifzq.gtimg.cn/appstock/app/kline/kline',
      'https://proxy.finance.qq.com/ifzqgtimg/appstock/app/kline/kline'
    ];
    for (const base of nodes) {
      try {
        const url = `${base}?param=${sym},day,,,${n},`;
        const resp = await fetch(url, { cache: 'no-store' });
        if (!resp.ok) continue;
        const j = await resp.json();
        const node = j && j.data && j.data[sym];
        const arr = node && (node.day || node.bfqday || node.qfqday);
        if (!arr || !arr.length) continue;
        const out = [];
        for (const r of arr) {
          const date = r[0];
          const close = parseFloat(r[2]);
          if (!date || isNaN(close)) continue;
          out.push({ date, open: parseFloat(r[1]), close, high: parseFloat(r[3]), low: parseFloat(r[4]), volume: parseFloat(r[5]) });
        }
        if (out.length) return out;
      } catch (e) {
        console.debug('腾讯K线节点失败', base, code, e && e.message);
      }
    }
    return [];
  },

  /**
   * 获取日K线（不复权）。
   * 【数据源顺序】用户反馈东财在其网络下不可用（「东财失败」），而腾讯行情
   * （qt.gtimg.cn，本文件实时行情所用）可正常访问，且腾讯历史K线免费、CORS 开放。
   * 故改为：**腾讯优先**，东财仅作兜底。
   * @returns {Array<{date,open,close,high,low,volume}>}
   */
  async getKline(code, startDate, endDate, count) {
    const _ck = 'k:' + code + ':' + (startDate || '') + ':' + (endDate || '') + ':' + (count || '');
    return this._withCache(_ck, API_TTL.KLINE, () => this._getKlineRaw(code, startDate, endDate, count), v => !!(v && v.length));
  },

  async _getKlineRaw(code, startDate, endDate, count) {
    // 1) 腾讯历史日K线（免费、CORS 开放、浏览器直连）
    try {
      const bars = await this._tencentKline(code, startDate, endDate, count);
      if (bars && bars.length) return bars;
    } catch (e) {
      console.debug('腾讯K线失败，尝试东财兜底', code, e);
    }
    // 2) 兜底：东财日K线（klt=101 日线，fqt=0 不复权真实价；必须带 ut 否则返回空）
    const secid = this.toEastSecid(code);
    const beg = String(startDate || '').replace(/-/g, '');
    const end = String(endDate || '').replace(/-/g, '');
    const url = `https://push2his.eastmoney.com/api/qt/stock/kline/get?ut=fa5fd1943c7b386f172d6893dbfba10b&secid=${secid}` +
      `&fields1=f1,f2,f3,f4,f5,f6&fields2=f51,f52,f53,f54,f55,f56,f57,f58` +
      `&klt=101&fqt=0&beg=${beg}&end=${end}&lmt=1000`;
    try {
      const json = await this._eastGet(url);
      const kl = json && json.data && json.data.klines;
      if (kl && kl.length) {
        const out = this._parseEastKline(kl);
        if (out.length) return out;
      }
    } catch (e) {
      console.debug('东财K线亦失败', code, e);
    }
    return [];
  },

  // ============ 东方财富 补充数据（best-effort） ============

  /**
   * 获取资金流向（近一日主力净流入）
   * 东财 push2 接口，部分网络/地区可能受限
   * @returns {number|null} 主力净流入(元)
   */
  async getCapitalFlow(code) {
    const secid = this.toEastSecid(code);
    const url = `https://push2.eastmoney.com/api/qt/stock/fflow/daykline/get?secid=${secid}&lmt=1&klt=101&fields1=f1,f2,f3,f7&fields2=f51,f52,f53,f54,f55,f56,f57,f58`;
    try {
      const resp = await fetch(url, { cache: 'no-store' });
      const json = await resp.json();
      const kls = json.data && json.data.klines;
      if (kls && kls.length) {
        const last = kls[kls.length - 1].split(',');
        // f52:主力净流入
        return parseFloat(last[1]) || null;
      }
    } catch (e) {
      console.debug('资金流向获取失败', code);
    }
    return null;
  },

  /**
   * 获取财务指标（东财 F10 财务摘要）
   * @returns {{
   *   netProfit,        // 净利润(归母，元)
   *   kcfjcxjlr,        // 扣非净利润(元)
   *   revenue,          // 营业收入(元)
   *   profitYoY,        // 利润同比增长率(%)
   *   revenueYoY,       // 同比增长率(营收同比 %)
   *   hbGrowth,         // 环比增长率(净利润环比 %)
   *   kcfYoY,           // 扣非净利润同比增长率(%)
   *   revHb,            // 营收环比增长率(%)
   *   kcfHb,            // 扣非净利润环比增长率(%)
   *   contractLiab,     // 最新合同负债(元)
   *   shareholderCount, // 散户数量(本期股东人数)
   *   prevShareholderCount // 上期散户数量
   * }}
   */
  async getFinance(code) {
    const secucode = this.toSecucode(code);
    const result = {
      netProfit: null, kcfjcxjlr: null, revenue: null,
      profitYoY: null, revenueYoY: null, hbGrowth: null,
      kcfYoY: null, revHb: null, kcfHb: null,
      contractLiab: null,
      shareholderCount: null, prevShareholderCount: null
    };
    // 财务摘要（净利润/扣非/营收/各类增长率）
    try {
      const url = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_FINANCE_MAINFINADATA&columns=ALL&filter=(SECUCODE%3D%22${secucode}%22)&pageNumber=1&pageSize=1&sortColumns=REPORT_DATE&sortTypes=-1`;
      const resp = await fetch(url, { cache: 'no-store' });
      const json = await resp.json();
      const row = json.result && json.result.data && json.result.data[0];
      if (row) {
        result.netProfit = row.PARENTNETPROFIT != null ? parseFloat(row.PARENTNETPROFIT) : null;       // 净利润(元)
        result.kcfjcxjlr = row.KCFJCXSYJLR != null ? parseFloat(row.KCFJCXSYJLR) : null;               // 扣非净利润(元)
        result.revenue = row.TOTALOPERATEREVE != null ? parseFloat(row.TOTALOPERATEREVE) : null;       // 营业收入(元)
        result.profitYoY = row.PARENTNETPROFITTZ != null ? parseFloat(row.PARENTNETPROFITTZ) : null;   // 利润同比增长(%)
        result.revenueYoY = row.TOTALOPERATEREVETZ != null ? parseFloat(row.TOTALOPERATEREVETZ) : null;// 营收同比增长(%)
        result.hbGrowth = row.NETPROFITRPHBZC != null ? parseFloat(row.NETPROFITRPHBZC) : null;        // 净利润环比(%)
        result.kcfYoY = row.KCFJCXSYJLRTZ != null ? parseFloat(row.KCFJCXSYJLRTZ) : null;               // 扣非净利润同比增长(%)
        result.revHb = row.YYZSRGDHBZC != null ? parseFloat(row.YYZSRGDHBZC) : null;                    // 营收环比增长(%)
        result.kcfHb = row.KFJLRGDHBZC != null ? parseFloat(row.KFJLRGDHBZC) : null;                    // 扣非净利润环比增长(%)
      }
    } catch (e) {
      console.debug('财务摘要获取失败', code);
    }
    // 资产负债表（最新合同负债）
    try {
      const bsUrl = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_FINANCE_GBALANCE&columns=ALL&filter=(SECUCODE%3D%22${secucode}%22)&pageNumber=1&pageSize=1&sortColumns=REPORT_DATE&sortTypes=-1`;
      const bsResp = await fetch(bsUrl, { cache: 'no-store' });
      const bsJson = await bsResp.json();
      const bsRow = bsJson.result && bsJson.result.data && bsJson.result.data[0];
      if (bsRow && bsRow.CONTRACT_LIAB != null) {
        result.contractLiab = parseFloat(bsRow.CONTRACT_LIAB);   // 合同负债(元)
      }
    } catch (e) {
      console.debug('资产负债表获取失败', code);
    }
    // 股东人数（本期 + 上期）
    try {
      const holderUrl = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_EH_HOLDERNUM&columns=ALL&filter=(SECUCODE%3D%22${secucode}%22)&pageNumber=1&pageSize=2&sortColumns=END_DATE&sortTypes=-1`;
      const hResp = await fetch(holderUrl, { cache: 'no-store' });
      const hJson = await hResp.json();
      const rows = hJson.result && hJson.result.data;
      if (rows && rows.length) {
        result.shareholderCount = rows[0].HOLDER_TOTAL_NUM != null ? rows[0].HOLDER_TOTAL_NUM : (rows[0].HOLDER_NUM || null);
        if (rows.length > 1) {
          result.prevShareholderCount = rows[1].HOLDER_TOTAL_NUM != null ? rows[1].HOLDER_TOTAL_NUM : (rows[1].HOLDER_NUM || null);
        }
      }
    } catch (e) {
      console.debug('股东人数获取失败', code);
    }
    return result;
  },

  /**
   * 获取个股所属一级行业（东财 F10 公司概况，best-effort）。
   * @param {string} code sh600519
   * @returns {Promise<string|null>} 如「食品饮料」「银行」
   */
  async getIndustry(code) {
    const secucode = this.toSecucode(code);
    try {
      const url = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_ORG_BASICINFO&columns=ALL&filter=(SECUCODE%3D%22${secucode}%22)&pageNumber=1&pageSize=1`;
      const resp = await fetch(url, { cache: 'no-store' });
      const json = await resp.json();
      const row = json.result && json.result.data && json.result.data[0];
      if (row) {
        if (row.BOARD_NAME_1LEVEL) return row.BOARD_NAME_1LEVEL;
        if (row.SWINDUSTRY_NAME2) return row.SWINDUSTRY_NAME2;
        if (row.CSRC_INDUSTRY_NAME) {
          // CSRC 形如「制造业-酒、饮料和精制茶制造业」，取最后一个「-」之后的部分
          const parts = String(row.CSRC_INDUSTRY_NAME).split('-');
          return parts[parts.length - 1];
        }
      }
    } catch (e) {
      console.debug('获取行业失败', code);
    }
    return null;
  },

  /**
   * 获取个股所属行业（明细到最细层级，best-effort）。
   * 通过东财 F10 公司概况的板块三级行业链拼接：一级/二级/三级，如「电力设备 / 其他电源设备Ⅱ / 综合电力设备商」。
   * 用于反推业务结果表的「所属行业」列。fetch 失败自动降级 JSONP（绕过 CORS）。
   * @param {string} code sh600875 或 600875.SH
   * @returns {Promise<string|null>}
   */
  async getIndustryDetail(code) {
    const secucode = this.toSecucode(code);
    const url = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_ORG_BASICINFO&columns=ALL&filter=(SECUCODE%3D%22${secucode}%22)&pageNumber=1&pageSize=1`;
    let row = null;
    try {
      const resp = await fetch(url, { cache: 'no-store' });
      const json = await resp.json();
      row = json.result && json.result.data && json.result.data[0];
    } catch (e) {
      console.debug('获取细分行业失败(fetch)，尝试 JSONP 兜底', code);
    }
    if (!row) {
      try {
        const json = await this._eastJsonp(url, 9000);
        row = json && json.result && json.result.data && json.result.data[0];
      } catch (e) {
        console.debug('获取细分行业失败(JSONP)', code);
      }
    }
    if (row) {
      const chain = [row.BOARD_NAME_1LEVEL, row.BOARD_NAME_2LEVEL, row.BOARD_NAME_3LEVEL]
        .filter(v => v && String(v).trim());
      if (chain.length) return chain.join(' / ');
      if (row.CSRC_INDUSTRY_NAME) return String(row.CSRC_INDUSTRY_NAME).replace(/-/g, ' / ');
    }
    return null;
  },

  /**
   * 获取个股主营构成（东财 F10 主营构成，RPT_F10_FN_MAINOP）。
   * 取最新报告期的「按产品」(MAINOP_TYPE=2) 构成，按收入占比降序返回前若干主业。
   * @param {string} code sh600519
   * @returns {Promise<Array<{name:string, ratio:number}>|null>}
   *   如 [{ name: '茅台酒', ratio: 85.7 }, { name: '其他系列酒', ratio: 14.3 }]
   */
  /**
   * 把东财主营构成原始行解析为「按产品」营收占比构成（用于反推业务/语义营收占比相关度）。
   * @param {Array} rows RPT_F10_FN_MAINOP 原始行
   * @returns {Array<{name:string, ratio:number}>|null}
   */
  _parseMainBiz(rows) {
    if (!rows || !rows.length) return null;
    // 报告期倒序排列，取最新一期全部构成行
    const latest = rows[0].REPORT_DATE.slice(0, 10);
    const period = rows.filter(r => (r.REPORT_DATE || '').slice(0, 10) === latest);
    // 优先「按产品」(2)，其次「按行业」(1)
    let items = period.filter(r => String(r.MAINOP_TYPE) === '2');
    if (!items.length) items = period.filter(r => String(r.MAINOP_TYPE) === '1');
    if (!items.length) items = period;
    items.sort((a, b) => (b.MBI_RATIO || 0) - (a.MBI_RATIO || 0));
    const out = [];
    for (const it of items) {
      if (!it.ITEM_NAME) continue;
      let ratio = it.MBI_RATIO != null ? it.MBI_RATIO
                : (it.MBR_RATIO != null ? it.MBR_RATIO : null);
      if (ratio == null) continue;
      out.push({ name: String(it.ITEM_NAME), ratio: +ratio });
    }
    return out.length ? out : null;
  },

  async getMainBusiness(code) {
    const key = String(code || '').toLowerCase();
    // 0) 本地缓存 / 全市场索引（batch45：语义搜索批量取数会顺手填这两个，命中即零请求）
    const hit = this._mbCache.get(key);
    if (hit && Date.now() - hit.t < 6 * 60 * 60 * 1000) return hit.v;
    const idx = this._allMbIndex;
    if (idx && idx.size) {
      const v = this._mbFromIndex(idx, this._dcSecucode(key));
      if (v) { this._mbCache.set(key, { t: Date.now(), v }); return v; }
    }
    const secucode = this.toSecucode(code);
    const url = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_FN_MAINOP&columns=ALL&filter=(SECUCODE%3D%22${secucode}%22)&pageNumber=1&pageSize=60&sortColumns=REPORT_DATE&sortTypes=-1`;
    // 1) 优先 fetch（简单请求）
    try {
      const resp = await fetch(url, { cache: 'no-store' });
      const json = await resp.json();
      const rows = (json.result && json.result.data) || [];
      if (rows.length) { const v = this._parseMainBiz(rows); this._mbCache.set(key, { t: Date.now(), v }); return v; }
    } catch (e) {
      console.debug('获取主营构成失败(fetch)，尝试 JSONP 兜底', code);
    }
    // 2) JSONP 兜底（绕过浏览器 CORS 预检，datacenter-web 支持 cb 回调）
    try {
      const json = await this._eastJsonp(url, 9000);
      const rows = (json && json.result && json.result.data) || [];
      if (rows.length) { const v = this._parseMainBiz(rows); this._mbCache.set(key, { t: Date.now(), v }); return v; }
    } catch (e) {
      console.debug('获取主营构成失败(JSONP)', code);
    }
    this._mbCache.set(key, { t: Date.now(), v: null });
    return null;
  },

  /**
   * 获取某板块的成分股数量（单请求取 total，用于「热度」统计，避免逐页拉取）。
   * @param {string} bk 板块代码 BKxxxx
   * @returns {Promise<number>}
   */
  async getSectorStockCount(bk) {
    const code = this._normalizeBoardCode(bk);
    return this._withCache('sc:' + code, API_TTL.SECTOR, () => this._getSectorStockCountRaw(code), v => v != null);
  },

  async _getSectorStockCountRaw(bk) {
    try {
      const code = this._normalizeBoardCode(bk);
      // 指数板块：数据中心成分股数量（push2 fs=b:code 对指数返回 0）
      if (this._isIndexBoard(code)) {
        const codes = await this._getIndexConstituentCodes(code);
        return codes.length;
      }
      const url = `https://push2.eastmoney.com/api/qt/clist/get?pn=1&pz=1&po=1&np=1&fltt=2&invt=2&fid=f20&fs=b%3A${code}&fields=f12`;
      const json = await this._eastFetch(url);
      const total = json && json.data && json.data.total;
      return total != null ? total : 0;
    } catch (e) {
      return 0;
    }
  },

  /**
   * 反推业务：输入一只股票（代码或名称），反推出它的主营构成中各个业务/产品的
   * 营收占比（相关度），并对每个业务映射其所属东财板块、统计该板块成分股数量作为「热度」。
   *
   * 「热度」定义（按用户要求：业务在本业务名称股票中的热度）
   *   = 该业务对应东财板块的成分股数量（股票数越多 → 同业公司越多 / 竞争越充分）。
   *
   * @param {string} input 股票代码或名称，如 掌阅科技 / 603533 / sh603533
   * @returns {Promise<{ok,name,code,segments:[{name,ratio,relevance,heat,boardNames}],error}>}
   */
  async reverseBusiness(input) {
    const kw = String(input || '').trim();
    if (!kw) return { ok: false, error: '请输入股票代码或名称，如：掌阅科技 / 603533' };

    // 1) 解析股票代码（纯代码直用；名称走腾讯联想接口解析）
    let code = '', name = '';
    if (/^\d{4,8}$/.test(kw) || /^(sh|sz|bj)\d{4,8}$/i.test(kw)) {
      code = this.inferPrefix(kw);
    } else {
      try {
        const hints = await this.searchStocks(kw);
        const hit = hints.find(h => h.name === kw) || (hints.length ? hints[0] : null);
        if (hit) { code = hit.code; name = hit.name; }
      } catch (e) { /* ignore */ }
    }
    if (!code) return { ok: false, error: `未找到股票「${kw}」，请确认代码或名称（如 603533 / 掌阅科技）` };

    // 2) 拉取主营构成（已内置 fetch + JSONP 双兜底，浏览器 CORS 下也尽量可用）
    let mb = null;
    try { mb = await this.getMainBusiness(code); } catch (e) { mb = null; }
    if (!mb || !mb.length) {
      return { ok: false, error: `未能获取「${name || code}」的主营构成（东财 F10 暂无可用的主营构成数据，或网络被限制）` };
    }

    // 3) 先组装主营构成结果（业务名称已补全、营收占比即相关度），保证主结果一定返回
    const segments = mb.map(seg => {
      const ratio = Math.round(seg.ratio * 1000) / 10;
      return {
        name: this._expandSegName(code, seg.name, []),
        ratio,
        relevance: ratio,
        heat: 0,
        boardNames: []
      };
    });

    // 4) 热度与板块映射：尽力而为，任何失败都不影响主结果展示
    try {
      const allBoards = await this.getAllSectors();
      const topSegs = segments.slice(0, 8); // 仅前 8 项业务计算热度，控制请求数
      const heatArr = await mapLimit(topSegs, 3, async (seg) => {
        try {
          const boards = this._matchSegmentBoards(seg.name, allBoards);
          let heat = 0; const boardNames = []; const boardCodes = [];
          if (boards.length) {
            boards.slice(0, 3).forEach(b => { boardNames.push(b.name); boardCodes.push(b.bk); });
            try { heat = await this.getSectorStockCount(boards[0].bk); } catch (e) { heat = 0; }
          }
          // 用匹配到的板块名二次补全（如「衍生业务」→「衍生业务（短剧）」）
          return { heat, boardNames, boardCodes, expanded: this._expandSegName(code, seg.name, boardNames) };
        } catch (e) {
          return { heat: 0, boardNames: [], boardCodes: [], expanded: seg.name };
        }
      });
      topSegs.forEach((seg, i) => {
        const h = heatArr[i] || { heat: 0, boardNames: [], boardCodes: [], expanded: seg.name };
        seg.heat = h.heat;
        seg.boardNames = h.boardNames;
        seg.boardCodes = h.boardCodes;
        seg.name = h.expanded;
      });
    } catch (e) {
      console.warn('反推业务：热度统计失败，仅展示主营构成（营收占比）', e);
    }

    segments.sort((a, b) => (b.relevance - a.relevance) || (b.heat - a.heat));

    // 5) 计算「该股最火概念」：在个股主营构成所映射到的东财概念板块中，
    //    找出与个股日收益率联动最强（皮尔逊相关系数最高）的概念——即平时最能带动该股上涨的概念。
    //    失败则回退到旧口径（同业公司数最多的主营构成段）。
    let hotConcept = null;
    try {
      hotConcept = await this._computeHotConcept(code, segments);
    } catch (e) {
      console.warn('反推业务：最火概念(联动)计算失败，回退到同业公司数口径', e);
    }

    let hotBusiness = '';
    if (hotConcept && hotConcept.name) {
      hotBusiness = hotConcept.name;
    } else {
      const byHeat = [...segments].sort((a, b) => (b.heat - a.heat) || (b.relevance - a.relevance));
      if (byHeat[0]) hotBusiness = byHeat[0].heat > 0 ? byHeat[0].name : segments[0].name;
    }

    return { ok: true, name: name || code, code, segments, hotBusiness, hotConcept };
  },

  /**
   * 计算「该股最火概念」：在个股主营构成映射到的东财概念板块里，取与个股日收益率
   * 联动最强（相关系数最高）的概念。即：平时最能带动该股上涨的概念/题材。
   * @param {string} code 东财前缀代码，如 sh600519
   * @param {Array} segments 主营构成段（含 boardCodes 字段）
   * @returns {Promise<{bk,name,corr,heat,boardNames}|null>}
   */
  async _computeHotConcept(code, segments) {
    // 收集去重后的概念板块代码（限制数量，控制请求数）
    const bkSet = new Set();
    for (const s of segments) {
      for (const bk of (s.boardCodes || [])) if (bk) bkSet.add(bk);
    }
    const bks = [...bkSet].slice(0, 10);
    if (!bks.length) return null;

    // 个股近 ~200 个交易日的日收益率
    const stockBars = await this.getKline(code, this._daysAgo(220), this.fmtDate(new Date()), 220);
    if (!stockBars || stockBars.length < 40) return null;
    const stockRet = _returns(stockBars.map(b => b.close));

    // 各概念板块近 ~200 个交易日的日收益率 + 与个股的相关系数
    const rows = await mapLimit(bks, 3, async (bk) => {
      try {
        const bars = await this.getBoardReturns(bk);
        if (!bars || bars.length < 40) return null;
        const ret = _returns(bars.map(b => b.close));
        const n = Math.min(stockRet.length, ret.length);
        if (n < 30) return null;
        const corr = _pearson(stockRet.slice(-n), ret.slice(-n));
        if (isNaN(corr) || corr <= 0) return null; // 仅取正向联动（带动上涨）
        return { bk, corr };
      } catch (e) { return null; }
    });
    const valid = rows.filter(Boolean).sort((a, b) => b.corr - a.corr);
    if (!valid.length) return null;

    const best = valid[0];
    let name = best.bk, stockCount = 0;
    try {
      const all = await this.getAllSectors();
      const b = (all || []).find(x => x.bk === best.bk);
      if (b) name = b.name;
    } catch (e) { /* ignore */ }
    try { stockCount = await this.getSectorStockCount(best.bk); } catch (e) { stockCount = 0; }
    return {
      bk: best.bk,
      name,
      corr: Math.round(best.corr * 1000) / 10, // 联动强度(%)
      heat: stockCount,                         // 该概念板块成分股数
      boardNames: [name]
    };
  },

  /**
   * 获取概念板块指数日K线（用于计算与个股的联动强度）。
   * 板块 secid 格式为 90.BKxxxx，走 push2his 东财节点（已内置多节点兜底）。
   * @param {string} bk 板块代码，如 BK0896
   */
  async getBoardReturns(bk) {
    const secid = '90.' + String(bk).replace(/^BK/i, 'BK');
    const url = `https://push2his.eastmoney.com/api/qt/stock/kline/get?ut=fa5fd1943c7b386f172d6893dbfba10b` +
      `&secid=${secid}&fields1=f1,f2,f3,f4,f5,f6&fields2=f51,f52,f53,f54,f55,f56,f57,f58` +
      `&klt=101&fqt=0&beg=20240101&end=20500101&lmt=250`;
    const json = await this._eastGet(url);
    const kl = json && json.data && json.data.klines;
    if (!kl || !kl.length) return [];
    return this._parseEastKline(kl);
  },

  _daysAgo(n) {
    const d = new Date(Date.now() - n * 86400000);
    return this.fmtDate(d);
  },

  /**
   * 业务段名 → 板块映射的常见同义词扩展（段名抽词后，再补充这些同义词作为候选匹配词，
   * 提升「版权→知识产权」「数字阅读→出版」等不易直接字面值匹配的命中率）。
   */
  _SEG_SYNONYMS: {
    '版权': ['知识产权', '版权'],
    '数字阅读': ['在线阅读', '数字出版', '出版'],
    '短剧': ['短剧', '互动游戏', '影视'],
    '网络文学': ['网文', '文学', '出版'],
    '内容': ['内容', '传媒'],
    'AI': ['人工智能', 'AI'],
    '大模型': ['大模型', '人工智能'],
    '安全': ['安全', '网络安全']
  },

  /**
   * 主营构成段名「补全」映射：东财 F10 的部分段名过于笼统（如「衍生业务」「其他」），
   * 反推业务时直接展示会让用户看不出具体在做什么。这里把已知公司的笼统段名补全为
   * 具体业务名。键支持两种形式：
   *   - `${纯代码}|${段名}`：公司级精确补全（优先级最高，如 掌阅科技 的「衍生业务」）
   *   - `${段名}`：通用补全（谨慎使用，仅对含义明确的段名生效）
   * 命中不到且段名本身较笼统时，_expandSegName 会退而以「匹配到的板块名」补充说明。
   */
  _SEG_NAME_EXPAND: {
    '603533|衍生业务': '短剧及IP衍生品业务',
    '603533|数字阅读平台': '数字阅读平台',
    '603533|版权产品': '版权产品',
    '300364|短剧及IP衍生品业务': '短剧及IP衍生品业务',
    '300364|网络文学': '网络文学',
    '300364|IP衍生': 'IP衍生业务',
    '300413|芒果TV': '芒果TV互联网视频业务',
    '300413|新媒体互动': '新媒体互动业务',
    '603000|内容科技': '内容科技业务',
    '603000|移动互联网': '移动互联网业务',
    '688004|传媒安全': '传媒安全业务',
    '688228|AI内容安全': 'AI内容安全业务'
  },

  /** 笼统段名正则：命中且无法精确补全时，用匹配到的板块名补充说明 */
  _VAGUE_SEG: /^(衍生|其他|其他业务|商品销售|主营业务|主业|合计|小计|分部|业务|产品|贸易|经销|服务|销售|代理|运营|投资|其他收入|其他类|其他产品)$/,

  /**
   * 补全/丰富主营构成段名，便于用户一眼看懂这家公司「衍生业务」到底指什么。
   * @param {string} code sh603533
   * @param {string} segName 原始段名（如「衍生业务」）
   * @param {Array<string>} boardNames 该段匹配到的东财板块名（用于兜底补充说明）
   * @returns {string} 补全后的段名
   */
  _expandSegName(code, segName, boardNames) {
    const pure = this.pureCode(code);
    const exact = this._SEG_NAME_EXPAND[`${pure}|${segName}`] || this._SEG_NAME_EXPAND[segName];
    if (exact) return exact;
    if (this._VAGUE_SEG.test(String(segName || '').trim()) && boardNames && boardNames.length) {
      return `${segName}（${boardNames[0]}）`;
    }
    return segName;
  },

  /**
   * 把主营构成段名映射到东财板块（取名称最相关的前几个）。
   * 做法：从段名抽取关键词（清洗通用后缀 + 中文 2~3 字 n-gram + 英文整词），
   * 在所有板块名中做子串匹配，按 semanticNameScore 取最相关者。
   * @param {string} segName 主营构成段名
   * @param {Array} allBoards 全量板块
   * @returns {Array<{bk,name,type}>}
   */
  _matchSegmentBoards(segName, allBoards) {
    let clean = String(segName || '')
      .replace(/[（(].*?[)）]/g, '')
      .replace(/(业务|产品|收入|及其他|其他|分部|板块|类|系列|相关|服务|销售|生产|制造|经营|业务群|业务线|产品类|合计|小计|业务板块)\s*$/g, '')
      .replace(/(及|与|和|与及).*$/, '')
      .trim();
    const cands = new Set([clean, String(segName || '')]);
    const cn = clean.match(/[一-龥]+/g) || [];
    cn.forEach(run => {
      if (run.length <= 4) cands.add(run);
      for (let n = 2; n <= 3; n++) {
        for (let i = 0; i + n <= run.length; i++) cands.add(run.slice(i, i + n));
      }
      // 同义词扩展
      for (const k of Object.keys(this._SEG_SYNONYMS)) {
        if (run.includes(k)) (this._SEG_SYNONYMS[k] || []).forEach(s => cands.add(s));
      }
    });
    (clean.toLowerCase().match(/[a-z0-9]{2,}/g) || []).forEach(t => cands.add(t));

    const hits = [];
    for (const b of allBoards) {
      const bn = b.name.toLowerCase();
      let best = 0;
      for (const c of cands) {
        if (!c || c.length < 2) continue;
        const cl = c.toLowerCase();
        if (bn.includes(cl)) {
          const s = semanticNameScore(b.name, c);
          if (s > best) best = s;
        }
      }
      if (best > 0) hits.push({ b, score: best });
    }
    hits.sort((x, y) => y.score - x.score);
    return hits.slice(0, 3).map(x => x.b);
  },

  /**
   * 获取季报营收/扣非累计值序列，计算「今年最新报告期 vs 2024年同期」的增长率。
   * 用于「24营比」和「24扣比」字段。
   * @param {string} code sh600519
   * @returns {Promise<{q24Rev: number|null, q24Kcf: number|null}>}
   *   q24Rev：最新报告期营业收入 vs 2024年同期营业收入 的同比增长率(%)
   *   q24Kcf：最新报告期扣非净利润 vs 2024年同期扣非净利润 的同比增长率(%)
   */
  async getQuarterlyFinance(code) {
    const secucode = this.toSecucode(code);
    const result = { q24Rev: null, q24Kcf: null };
    try {
      // 取最近 12 期（覆盖2024全年至今），按报告期倒序
      const url = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_FINANCE_MAINFINADATA&columns=ALL&filter=(SECUCODE%3D%22${secucode}%22)&pageNumber=1&pageSize=12&sortColumns=REPORT_DATE&sortTypes=-1`;
      const resp = await fetch(url, { cache: 'no-store' });
      const json = await resp.json();
      const rows = (json.result && json.result.data) || [];
      if (!rows.length) return result;

      // 解析每一期的报告期与数值，key 形如 "2025-09-30"
      const parse = (r) => {
        const date = (r.REPORT_DATE || '').replace('T00:00:00', '').slice(0, 10);
        return {
          date,
          rev: r.TOTALOPERATEREVE != null ? parseFloat(r.TOTALOPERATEREVE) : null,
          kcf: r.KCFJCXSYJLR != null ? parseFloat(r.KCFJCXSYJLR) : null
        };
      };
      const periods = rows.map(parse).filter(p => p.date);

      // 最新报告期
      const latest = periods[0];
      if (!latest) return result;

      // 找到与最新报告期「同年同期」的 2024 期。同期的判断：取报告的 月份日（如 09-30/06-30/03-31/12-31）
      const md = latest.date.slice(5);            // "09-30"
      const key2024 = `2024-${md}`;               // "2024-09-30"
      const target2024 = periods.find(p => p.date === key2024);
      if (!target2024) return result;

      // 营收增长
      if (latest.rev != null && target2024.rev != null && +target2024.rev !== 0) {
        result.q24Rev = +(((latest.rev - target2024.rev) / target2024.rev) * 100).toFixed(2);
      }
      // 扣非净利润增长
      if (latest.kcf != null && target2024.kcf != null && +target2024.kcf !== 0) {
        result.q24Kcf = +(((latest.kcf - target2024.kcf) / target2024.kcf) * 100).toFixed(2);
      }
    } catch (e) {
      console.debug('季报营收/扣非获取失败', code, e);
    }
    return result;
  },

  /**
   * 获取当年年初第一个交易日的收盘价
   * （向上取本年第一个交易日，而非回退到上一年最后一个交易日）
   * @param {string} code sh600519
   * @param {string} year 年份，如 2026；缺省为当前年份
   * @returns {number|null}
   */
  async getYearStartPrice(code, year) {
    const y = year || new Date().getFullYear();
    const yearStart = new Date(`${y}-01-01`);
    const start = this._addDays(yearStart, -10);
    const end = this._addDays(yearStart, 30);
    const data = await this.getKline(code, this.fmtDate(start), this.fmtDate(end));
    if (!data || !data.length) return null;
    // 取本年(>= y-01-01)第一个交易日，K线按日期升序返回
    const prefix = `${y}-`;
    const first = data.find(k => k.date.startsWith(prefix));
    return first ? first.close : null;
  },

  /**
   * 获取某股票「今年」的最高价 / 最低价（不复权真实价）。
   * 拉取年初至今天的全部日K线，扫描 high/low 极值。
   * @param {string} code sh600519
   * @param {number} year 年份，缺省为当前年份
   * @returns {Promise<{high:number, low:number}|null>}
   */
  async getYearHighLow(code, year) {
    const y = year || new Date().getFullYear();
    try {
      const data = await this.getKline(code, `${y}-01-01`, this.fmtDate(new Date()));
      if (!data || !data.length) return null;
      let hi = -Infinity, lo = Infinity;
      for (const k of data) {
        if (k.high != null && !isNaN(k.high) && k.high > hi) hi = k.high;
        if (k.low != null && !isNaN(k.low) && k.low < lo) lo = k.low;
      }
      if (hi === -Infinity || lo === Infinity) return null;
      return { high: +hi.toFixed(2), low: +lo.toFixed(2) };
    } catch (e) {
      console.debug('今年高低价获取失败', code, e);
      return null;
    }
  },

  /**
   * 估算区间所需的 K 线根数。
   * 腾讯 fqkline 的第 5 个参数即返回根数，硬编码 320 在两年区间（约 480 个交易日）
   * 会被截断，导致取不到年初价/924价。这里按自然日折算交易日并留冗余。
   */
  _barCount(startDate, endDate) {
    try {
      const s = new Date(startDate), e = new Date(endDate);
      const days = Math.ceil((e - s) / 86400000) + 1;
      // 两年区间约 480 个交易日；根数过大时腾讯会直接返回空，故上限取 800
      return Math.min(800, Math.max(320, Math.ceil(days * 7 / 5) + 40));
    } catch (e) {
      return 640;
    }
  },

  /**
   * 一次请求取回「年初价 / 924价 / 今年最高价 / 今年最低价」四项历史价。
   *
   * 【为什么要合并】原先每只股票要分别调用 getYearStartPrice / get924Price /
   * getYearHighLow，即 3 次 K 线请求。热门板块点击后的成分股动辄上百只，
   * 串行请求量达数百至上千次，极易触发接口限流与浏览器超时，表现为
   * 「今年高价/距高价/今年低价/距低价/年涨跌/924涨跌」六个字段长期刷新不出数据
   * （其他页面股票数少、能跑完，所以看起来「都正常」）。
   * 改为一次拉取 2024-09-01 至今的全部日 K，一次性算出四项，请求量降为原来的 1/3。
   * @param {string} code sh600519
   * @returns {Promise<{yearStartPrice,price924,yearHighPrice,yearLowPrice,yearHighDate,yearLowDate}>} 取不到的项为 null
   */
  async getHistoryBundle(code) {
    if (!code) return {
      yearStartPrice: null, price924: null, yearHighPrice: null, yearLowPrice: null,
      yearHighDate: null, yearLowDate: null, weekAgoClose: null, monthAgoClose: null
    };
    return this._withCache('hb:' + code + ':' + this._todayStr(), API_TTL.KLINE,
      () => this._getHistoryBundleRaw(code),
      v => !!(v && (v.yearStartPrice != null || v.price924 != null)));
  },

  async _getHistoryBundleRaw(code) {
    const out = {
      yearStartPrice: null, price924: null, yearHighPrice: null, yearLowPrice: null,
      yearHighDate: null, yearLowDate: null,
      weekAgoClose: null, monthAgoClose: null
    };
    if (!code) return out;
    const y = new Date().getFullYear();
    const start = '2024-09-01';
    const end = this.fmtDate(new Date());
    const n = this._barCount(start, end);
    let data = [];
    try {
      data = await this.getKline(code, start, end, n);
    } catch (e) {
      data = [];
    }
    // 腾讯接口语义为「最近 N 个交易日」，若根数不足导致未覆盖到 924，则加大根数重试一次
    if (data.length && data[0].date > start) {
      try {
        const more = await this.getKline(code, start, end, 1600);
        if (more && more.length && more[0].date < data[0].date) data = more;
      } catch (e) { /* 重试失败则沿用原数据 */ }
    }
    if (!data || !data.length) return out;
    // 今年高低价 + 年初第一个交易日收盘价（K 线按日期升序，首个即年初首个交易日）
    const prefix = `${y}-`;
    let hi = -Infinity, lo = Infinity, first = null, hiDate = null, loDate = null;
    for (const k of data) {
      if (k.date && k.date.indexOf(prefix) === 0) {
        if (k.high != null && !isNaN(k.high) && k.high > hi) { hi = k.high; hiDate = k.date; }
        if (k.low != null && !isNaN(k.low) && k.low < lo) { lo = k.low; loDate = k.date; }
        if (!first) first = k;
      }
    }
    if (hi !== -Infinity) { out.yearHighPrice = +hi.toFixed(2); out.yearHighDate = hiDate; }
    if (lo !== Infinity) { out.yearLowPrice = +lo.toFixed(2); out.yearLowDate = loDate; }
    if (first) out.yearStartPrice = first.close;
    // 924 收盘价：优先精确匹配，非交易日则取之前最近一个交易日
    const exact = data.find(k => k.date === '2024-09-24');
    if (exact) {
      out.price924 = exact.close;
    } else {
      let prev = null;
      for (const k of data) { if (k.date && k.date <= '2024-09-24') prev = k; }
      if (prev) out.price924 = prev.close;
    }
    // 一周前 / 一月前收盘价（用于「一周涨跌 / 一月涨跌」）：按交易日回溯 5 / 20 根
    const back = (n) => {
      const i = data.length - 1 - n;
      if (i < 0) return null;
      const c = data[i].close;
      return (c != null && !isNaN(c) && c) ? c : null;
    };
    out.weekAgoClose = back(5);
    out.monthAgoClose = back(20);
    return out;
  },

  /** 转换 SECUCODE：sh600519 → 600519.SH，sz000001 → 000001.SZ，bj → .BJ */
  toSecucode(code) {
    const pure = this.pureCode(code);
    const c = String(code);
    if (/^sh/i.test(c)) return `${pure}.SH`;
    if (/^bj/i.test(c)) return `${pure}.BJ`;
    // 纯数字/未知前缀时按代码段判断市场：6/9 沪市，4/8/92 北交所，其余(0/3等)深市
    if (/^[48]/.test(pure) || /^92/.test(pure)) return `${pure}.BJ`;
    if (/^[69]/.test(pure)) return `${pure}.SH`;
    return `${pure}.SZ`;
  },

  // ============ 热门板块/股票 ============

  /**
   * 将东财 clist 返回的 diff 统一成数组。
   * 新版接口可能返回以序号为键的对象，旧版为数组，这里做兼容。
   */
  _diffArray(json) {
    const d = json && json.data && json.data.diff;
    if (!d) return [];
    if (Array.isArray(d)) return d;
    return Object.keys(d).map(k => d[k]);
  },

  /**
   * JSONP 请求（东财接口支持 cb 回调参数）。
   * 通过注入 <script> 加载数据，不受浏览器同源策略（CORS）限制，
   * 是静态站点（如 GitHub Pages）直连东财接口失败时最可靠的兜底方案。
   */
  _eastJsonp(url, timeout = 7000) {
    return new Promise((resolve, reject) => {
      const cbName = '__emcb_' + Math.random().toString(36).slice(2) + '_' + Date.now();
      let script = null;
      let settled = false;
      const cleanup = () => {
        try { delete window[cbName]; } catch (e) {}
        if (script && script.parentNode) script.parentNode.removeChild(script);
      };
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true; cleanup(); reject(new Error('jsonp timeout'));
      }, timeout);
      window[cbName] = (data) => {
        if (settled) return;
        settled = true; clearTimeout(timer); cleanup();
        if (data) resolve(data); else reject(new Error('jsonp empty'));
      };
      try {
        // 注意：不能用 URL.searchParams.set() 追加 cb —— 它会重新编码整个查询串，
        // 把 fs=m:90+t:2 中的 "+" 变成空格/ %2B，导致东财返回空数据。
        // 这里直接字符串拼接，完整保留原有参数编码。
        const src = url + (url.indexOf('?') >= 0 ? '&' : '?') + 'cb=' + cbName;
        script = document.createElement('script');
        script.charset = 'utf-8';
        script.onerror = () => {
          if (settled) return;
          settled = true; clearTimeout(timer); cleanup(); reject(new Error('jsonp error'));
        };
        script.src = src;
        document.head.appendChild(script);
      } catch (e) {
        if (settled) return;
        settled = true; clearTimeout(timer); cleanup(); reject(e);
      }
    });
  },

  /**
   * 统一的东财 GET：
   * 1) 优先 fetch —— 注意不携带任何自定义请求头，保持「简单请求」以避免触发 CORS 预检；
   * 2) 失败则降级 JSONP —— 完全绕过 CORS。
   * @returns {object|null}
   */
  /**
   * 东财请求的可选边缘加速路径：经 `${base}/proxy?url=<原URL>` 取 JSON。
   * 只有在设置了加速站点时才发起；未设置时立即返回 null，**完全不触碰原有链路**。
   * @returns {Promise<object|null>} 拿到有效 JSON 返回它；任一环节失败返回 null（调用方继续走原逻辑）
   */
  async _eastGetViaAccel(url) {
    const bases = this._accelBases();
    if (!bases.length) return null;
    if (this._accelOpen()) return null;          // 熔断中：立即跳过，不再白等超时
    let anyFail = false;
    for (const base of bases) {
      try {
        const buf = await this._fetchBytes(base + '/proxy?url=' + encodeURIComponent(url), this.ACCEL_TIMEOUT);
        const txt = new TextDecoder('utf-8').decode(buf);
        const j = JSON.parse(txt);
        if (j && j.data != null) { this._accelMarkOk(); return j; }
        anyFail = true;
      } catch (e) {
        anyFail = true;
        console.debug('[accel] 东财加速不可用，回退直连:', base, e && e.message);
      }
    }
    if (anyFail) this._accelMarkFail();
    return null;
  },

  async _eastGet(url) {
    let u = null;
    try { u = new URL(url); } catch (e) { u = null; }
    const isKline = !!(u && u.pathname.indexOf('/kline/') >= 0);

    // 0) 边缘加速（可选）：仅在设置了加速站点时启用。
    //    这是「锦上添花」路径——失败、超时、未配置都不改变后续行为，一律回落到原来的多节点直连。
    try {
      const acc = await this._eastGetViaAccel(url);
      if (acc) {
        if (isKline) { if (acc.data.klines && acc.data.klines.length) return acc; }
        else return acc;
      }
    } catch (e) { /* 加速链路异常：忽略，走原逻辑 */ }

    let hosts;
    if (u && u.hostname.indexOf('push2') === 0) {
      // K 线只有 push2his / push2delay 提供真实数据；push2 主节点对 kline 接口返回
      // data:{klines:[]} 这类「成功但空」的响应。若把 push2 排在最前，_eastGet 会把它当成成功
      // 直接短路返回，导致「今年高价/距高价/今年低价/距低价/年涨跌/924涨跌」永远取不到数据。
      // 故 K 线请求跳过 push2，且只在确有 klines 时才算成功（空数据继续尝试下一节点）。
      hosts = isKline
        ? ['push2his.eastmoney.com', 'push2delay.eastmoney.com']
        : ['push2.eastmoney.com', 'push2delay.eastmoney.com', 'push2his.eastmoney.com'];
    } else {
      hosts = [null];   // 非 push2 域名（如 datacenter-web）不做替换
    }

    // 请求东财（尤其 JSONP 兜底）偶发被接口限流/网络抖动，一次失败即放弃会导致
    // 热门板块刷新误报「刷新失败」。这里整体重试 2 次（共 3 次尝试），每次重试间隔退避，
    // 对抗一过性限流；任一次成功立即返回，重试不改变成功路径行为。
    const MAX_TRIES = 3;
    for (let attempt = 0; attempt < MAX_TRIES; attempt++) {
      if (attempt > 0) {
        await new Promise(r => setTimeout(r, attempt * 600)); // 退避 600ms / 1200ms
      }
      for (const host of hosts) {
        // 用字符串拼接而非 URL 序列化，避免 searchParams 重新编码把 "fs=m:90+t:2" 的 "+" 变成空格
        let target = url;
        if (host && u && u.hostname !== host) {
          target = u.protocol + '//' + host + u.pathname + (u.search || '');
        }
        // 1) 简单请求 fetch（不带任何自定义头，避免 CORS 预检）
        try {
          const resp = await fetch(target, { cache: 'no-store' });
          if (resp.ok) {
            const j = await resp.json();
            if (j && j.data != null) {
              if (isKline) { if (j.data.klines && j.data.klines.length) return j; }
              else return j;
            }
          }
        } catch (e) {
          console.debug('[stock-api] fetch 失败，改用 JSONP 兜底:', e && e.message);
        }
        // 2) JSONP：注入 <script> 加载，完全绕过 CORS
        try {
          const j = await this._eastJsonp(target, 9000);
          if (j && j.data != null) {
            if (isKline) { if (j.data.klines && j.data.klines.length) return j; }
            else return j;
          }
        } catch (e) {
          console.debug('[stock-api] JSONP 亦失败:', e && e.message);
        }
      }
    }
    return null;
  },

  // ============ 新浪行情源（免费、不限流；<script> 直载，天然绕开 CORS） ============
  /**
   * 加载新浪「JS 变量」型接口：响应体形如 `var XXX = {...};` 或 `var _list = ([...]);`。
   * 顶层 var 会挂到 window 上，因此用 <script> 标签加载即可——**天然不受 CORS 限制**，
   * 也不必消耗 Worker / JSONP 兜底链路。这才是「免费且几乎不限流」的根本原因：
   * newSinaHy.php / newFLJK.php 本质是新浪定时刷新的静态快照文件，命中 CDN，
   * 不像 push2 这类动态查询接口那样按 IP 做频率控制。
   * 读取后立即清理全局变量与 <script>，避免污染页面 / 变量串号。
   *
   * @param {string} url 目标地址
   * @param {string} varName 期望读到的全局变量名
   * @param {number} [timeout=8000]
   * @returns {Promise<object|Array>}
   */
  _sinaLoadVar(url, varName, timeout = 8000) {
    return new Promise((resolve, reject) => {
      if (typeof document === 'undefined') { reject(new Error('sina: no document')); return; }
      let script = null, settled = false;
      const cleanup = () => {
        try { delete window[varName]; } catch (e) { try { window[varName] = undefined; } catch (e2) {} }
        if (script && script.parentNode) script.parentNode.removeChild(script);
      };
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true; cleanup(); reject(new Error('sina timeout'));
      }, timeout);
      const done = () => {
        if (settled) return;
        settled = true; clearTimeout(timer);
        let v = null;
        try { v = window[varName]; } catch (e) { v = null; }
        cleanup();                                  // 先取值、后清理
        if (v && typeof v === 'object') resolve(v);
        else reject(new Error('sina empty'));
      };
      try {
        script = document.createElement('script');
        // 不设 charset：现代浏览器按「响应头 charset」解码（新浪板块接口为 GBK，由响应头声明），
        // 显式设 charset 反而会被忽略。解析层另做乱码自愈，双保险。
        script.onload = done;
        script.onerror = () => {
          if (settled) return;
          settled = true; clearTimeout(timer); cleanup(); reject(new Error('sina error'));
        };
        script.src = url;
        document.head.appendChild(script);
      } catch (e) {
        if (settled) return;
        settled = true; clearTimeout(timer); cleanup(); reject(e);
      }
    });
  },

  /** 新浪固定变量名接口的串行闸门：newSinaHy.php / newFLJK.php 的全局变量名是固定的，
   *  并发加载会互相覆盖，这里排队执行确保每次读到的是自己那次的结果。 */
  _sinaGate: null,
  _sinaSerial(fn) {
    const run = (this._sinaGate || Promise.resolve()).then(fn, fn);
    this._sinaGate = run.then(() => {}, () => {});
    return run;
  },

  /** 是否为新浪板块代码（行业 new_xxxx / 概念 gn_xxxx） */
  _isSinaBoard(bk) {
    return /^(new_|gn_)/i.test(String(bk || ''));
  },

  /**
   * 解析新浪板块快照（值为 13 段逗号分隔字符串）：
   *   0 板块代码 / 1 名称 / 2 成分股家数 / 3 均价 / 4 平均涨跌额 / 5 **平均涨跌幅(%)**
   *   6 成交量 / 7 成交额 / 8 领涨股代码 / 9 领涨股涨幅 / 10 领涨股价 / 11 领涨股涨跌额 / 12 领涨股名
   *
   * 编码自愈分两级，顺序很重要（先判整体、再逐条丢）：
   *   ① 若**过半**名称不含任何汉字/字母/数字（GBK 被按 UTF-8 解码的典型后果），
   *      判定整体乱码 → 直接返回 []，由竞速逻辑改走东财，绝不把乱码渲染给用户；
   *   ② 个别坏条目（名称空/乱码、涨跌幅非数）单独丢弃，不影响同批其它板块。
   *
   * @returns {Array<{bk,name,change}>} 按涨跌幅降序、截取 limit 条
   */
  _sinaBoardsFromMap(map, limit = 15, all = false) {
    const raw = [];
    if (map && typeof map === 'object') {
      for (const k of Object.keys(map)) {
        const parts = String(map[k] || '').split(',');
        if (parts.length < 6) continue;              // 结构不合法，直接不进候选
        raw.push({ key: k, parts });
      }
    }
    if (!raw.length) return [];
    // ① 整体编码自愈（必须在逐条过滤之前判，否则坏条目已被滤掉、判断形同虚设）
    const badName = raw.filter(r => !/[\u4e00-\u9fa5A-Za-z0-9]/.test((r.parts[1] || '').trim())).length;
    if (badName * 2 > raw.length) return [];
    // ② 逐条解析
    const list = [];
    for (const r of raw) {
      const p = r.parts;
      const name = (p[1] || '').trim();
      const change = parseFloat(p[5]);
      if (!name || !/[\u4e00-\u9fa5A-Za-z0-9]/.test(name)) continue;
      if (isNaN(change)) continue;
      list.push({
        bk: (p[0] || r.key).trim(), name, change,
        stockCount: parseInt(p[2], 10) || 0,
        leadCode: (p[8] || '').trim(),
        leadName: (p[12] || '').trim()
      });
    }
    if (!list.length) return [];
    // 全量模式：不做「涨幅榜」截断，按名称排序返回，供「选股板块」搜索使用。
    // 这是「免费永不限流」的关键——见 newSinaHy.php / newFLJK.php 的说明。
    if (all) {
      list.sort((a, b) => String(a.name).localeCompare(String(b.name), 'zh'));
      return list;
    }
    list.sort((a, b) => b.change - a.change);
    return list.slice(0, limit).map(b => ({ bk: b.bk, name: b.name, change: b.change }));
  },

  /** 新浪行业板块涨幅榜（<script> 直载静态快照） */
  async _sinaIndustryBoards(limit = 15) {
    const url = 'https://vip.stock.finance.sina.com.cn/q/view/newSinaHy.php';
    const map = await this._sinaSerial(() => this._sinaLoadVar(url, 'S_Finance_bankuai_sinaindustry', 8000));
    return this._sinaBoardsFromMap(map, limit);
  },

  /** 新浪概念板块涨幅榜（<script> 直载静态快照） */
  async _sinaConceptBoards(limit = 15) {
    const url = 'https://vip.stock.finance.sina.com.cn/q/view/newFLJK.php?param=class';
    const map = await this._sinaSerial(() => this._sinaLoadVar(url, 'S_Finance_bankuai_class', 8000));
    return this._sinaBoardsFromMap(map, limit);
  },

  /**
   * 新浪**全量**板块（行业 + 概念），供「选股板块」搜索使用（batch44）。
   *
   * 与上面两个「涨幅榜」方法的区别：不做 top-N 截断、返回全部条目。
   *
   * 🔴 为什么它是「完全免费、永不限流」的最优解：
   *   newSinaHy.php / newFLJK.php 本质是新浪**定时刷新的静态快照文件**（命中 CDN），
   *   不是按 IP 做频率控制的动态查询接口；且用 <script> 直载 → 无 CORS 预检、无跨域限制。
   *   一次请求拿到全量（约 49 行业 + 175 概念），替代东财「3 类 × 6 页 = 18 次请求」的分页拉取，
   *   请求数下降一个数量级，从根上规避限流。
   *
   * ⚠️ 两个接口的全局变量名固定，必须串行加载（_sinaSerial），否则并发会互相覆盖。
   *
   * @returns {Promise<{industries: Array, concepts: Array}>} 元素含 {bk,name,change,stockCount,leadCode,leadName}
   */
  async _sinaAllSectors() {
    const [hyMap, clsMap] = await this._sinaSerial(async () => {
      let a = null, b = null;
      try {
        a = await this._sinaLoadVar('https://vip.stock.finance.sina.com.cn/q/view/newSinaHy.php',
          'S_Finance_bankuai_sinaindustry', 9000);
      } catch (e) { /* 行业失败不影响概念 */ }
      try {
        b = await this._sinaLoadVar('https://vip.stock.finance.sina.com.cn/q/view/newFLJK.php?param=class',
          'S_Finance_bankuai_class', 9000);
      } catch (e) { /* 概念失败不影响行业 */ }
      return [a, b];
    });
    return {
      industries: this._sinaBoardsFromMap(hyMap, 0, true),
      concepts: this._sinaBoardsFromMap(clsMap, 0, true)
    };
  },

  /** 新浪个股涨幅榜（jsonp_v2，变量名唯一化 → 可并发，且响应为 \uXXXX 转义的纯 ASCII，无编码风险） */
  async _sinaStockRanking(limit = 15) {
    const varName = '_snt_rk_' + Math.random().toString(36).slice(2, 8);
    const url = 'https://vip.stock.finance.sina.com.cn/quotes_service/api/jsonp_v2.php/var%20'
      + varName + '=/Market_Center.getHQNodeData?page=1&num=' + limit
      + '&sort=changepercent&asc=0&node=hs_a&symbol=&_s_r_a=page';
    const arr = await this._sinaLoadVar(url, varName, 8000);
    const out = [];
    if (Array.isArray(arr)) {
      for (const it of arr) {
        if (!it || !it.symbol) continue;
        const change = parseFloat(it.changepercent);
        out.push({ name: it.name || '', code: String(it.symbol), change: isNaN(change) ? 0 : change });
      }
    }
    return out;
  },

  /**
   * 新浪板块成分股（node = 新浪板块代码，如 new_blhy / gn_hwqc）。
   * 走 jsonp_v2 且变量名唯一化，既无 CORS 限制，又能安全并发分页。
   * @returns {Promise<Array<{code,name,price,changePercent}>>} code 为带 sh/sz/bj 前缀格式
   */
  async _sinaSectorStocks(node, maxPages = 20) {
    const all = [];
    for (let page = 1; page <= maxPages; page++) {
      const varName = '_snt_ss_' + Math.random().toString(36).slice(2, 8);
      const url = 'https://vip.stock.finance.sina.com.cn/quotes_service/api/jsonp_v2.php/var%20'
        + varName + '=/Market_Center.getHQNodeData?page=' + page
        + '&num=100&sort=symbol&asc=1&node=' + encodeURIComponent(node)
        + '&symbol=&_s_r_a=page';
      let arr = null;
      try { arr = await this._sinaLoadVar(url, varName, 9000); } catch (e) { break; }
      if (!Array.isArray(arr) || !arr.length) break;
      for (const it of arr) {
        if (!it || !it.symbol) continue;
        const cap = parseFloat(it.mktcap);
        all.push({
          code: String(it.symbol),
          name: it.name || '',
          price: it.trade != null && it.trade !== '' ? parseFloat(it.trade) : null,
          changePercent: it.changepercent != null ? parseFloat(it.changepercent) : null,
          marketCap: isNaN(cap) ? null : cap * 10000   // 新浪 mktcap 单位为万元 → 元
        });
      }
      if (arr.length < 100) break;                 // 不足一页 → 已到末页
      await new Promise(r => setTimeout(r, 120));
    }
    return all;
  },

  /**
   * 双源竞速：并发请求多个数据源，返回**最先拿到的非空结果**。
   * 用于「新浪（免费不限流、<script> 直载）优先 + 东财兜底」：
   * 某源先返回「空数组」时不立即采用（继续等其它源），只有全部为空才返回 []。
   * 东财若因限流慢/失败，也不会拖累已就绪的新浪结果。
   * @param {Array<()=>Promise<Array>>} tasks
   * @returns {Promise<Array>}
   */
  _raceFirstValid(tasks) {
    return new Promise(resolve => {
      const list = Array.isArray(tasks) ? tasks : [];
      if (!list.length) { resolve([]); return; }
      let pending = list.length, settled = false;
      for (const t of list) {
        Promise.resolve().then(t).catch(() => null).then(v => {
          if (settled) return;
          if (v && v.length) { settled = true; resolve(v); return; }
          if (--pending === 0) { settled = true; resolve([]); }
        });
      }
    });
  },

  /**
   * 获取板块涨幅排行（新浪优先 + 东财兜底）
   * @returns {Array<{bk, name, change}>}
   */
  async getBoardRanking() {
    return this._withCache('br:industry15', API_TTL.SECTOR, () => this._getBoardRankingRaw(), v => !!(v && v.length));
  },

  async _getBoardRankingRaw() {
    return this._raceFirstValid([
      () => this._sinaIndustryBoards(15),
      () => this._eastIndustryBoards(15)
    ]);
  },

  /** 东财行业板块涨幅榜（fs=m:90+t:2），作为新浪的兜底源 */
  async _eastIndustryBoards() {
    const results = [];
    try {
      const url = `https://push2.eastmoney.com/api/qt/clist/get?pn=1&pz=15&po=1&np=1&fltt=2&invt=2&fid=f3&fs=m:90+t:2&fields=f2,f3,f12,f14`;
      const json = await this._eastGet(url);
      for (const item of this._diffArray(json)) {
        // bk=板块代码(f12)，供点击板块时拉取其成分股
        results.push({ bk: item.f12, name: item.f14, change: parseFloat(item.f3) });
      }
    } catch (e) {
      console.debug('板块排行获取失败', e);
    }
    return results;
  },

  /**
   * 获取振幅板块排行（东财）
   * 计算规则：对板块振幅（f7）突然拉升/放大进行排名，取概念板块按振幅降序。
   * @returns {Array<{bk, name, change}>} change 为振幅(%)
   */
  async getAmplitudeBoards() {
    return this._withCache('br:amp15', API_TTL.SECTOR, () => this._getAmplitudeBoardsRaw(), v => !!(v && v.length));
  },

  async _getAmplitudeBoardsRaw() {
    const results = [];
    try {
      // 概念板块 fs=m:90+t:3，按振幅(f7)降序取前 15
      const url = `https://push2.eastmoney.com/api/qt/clist/get?pn=1&pz=15&po=1&np=1&fltt=2&invt=2&fid=f7&fs=m:90+t:3&fields=f2,f3,f7,f12,f14`;
      const json = await this._eastGet(url);
      for (const item of this._diffArray(json)) {
        const amp = item.f7 != null ? parseFloat(item.f7) : parseFloat(item.f3);
        results.push({ bk: item.f12, name: item.f14, change: isNaN(amp) ? 0 : amp });
      }
    } catch (e) {
      console.debug('振幅板块获取失败', e);
    }
    return results;
  },

  /**
   * 获取盘前热点板块（概念板块，按涨幅排序）
   * 与「当日热门板块」（行业板块）互补：概念板块更偏题材/热点，
   * 适合作为盘前关注的热点方向。
   * @returns {Array<{bk, name, change}>}
   */
  async getPreMarketBoards() {
    return this._withCache('br:premarket15', API_TTL.SECTOR, () => this._getPreMarketBoardsRaw(), v => !!(v && v.length));
  },

  async _getPreMarketBoardsRaw() {
    // 新浪概念板块快照（<script> 直载）优先，东财兜底：两者竞速，先到且非空者胜出
    return this._raceFirstValid([
      () => this._sinaConceptBoards(15),
      () => this._eastPreMarketBoards(15)
    ]);
  },

  /** 东财概念板块涨幅榜（fs=m:90+t:3），作为新浪的兜底源 */
  async _eastPreMarketBoards() {
    const results = [];
    try {
      // 概念板块 fs=m:90+t:3，按涨幅降序取前 15
      const url = `https://push2.eastmoney.com/api/qt/clist/get?pn=1&pz=15&po=1&np=1&fltt=2&invt=2&fid=f3&fs=m:90+t:3&fields=f2,f3,f12,f14`;
      const json = await this._eastGet(url);
      for (const item of this._diffArray(json)) {
        results.push({ bk: item.f12, name: item.f14, change: parseFloat(item.f3) });
      }
    } catch (e) {
      console.debug('盘前热点板块获取失败', e);
    }
    return results;
  },

  /**
   * 获取全部 A 股列表（沪深主板 + 创业板 + 科创板），供「尾盘买入法 → 对 A 股全部股票筛选」使用。
   * 数据源：东财行情 clist，板块筛选 fs=m:0+t:6,m:0+t:80,m:1+t:2,m:1+t:23（全 A）。
   *
   * 提速三件套（batch29）：
   *   ① 名单静态化：优先读 GitHub Actions 生成的静态名单 data/stocks/all-a.json（一次 CDN 请求），
   *      其次读本机 localStorage 上次成功拉取的名单（7 天内）。拿到名单即可算出精确页数，
   *      不再「一页页试探到空页为止」。
   *   ② 并发分页：批内 6 个并发、批间 40ms 微间隔，取代原来的「串行 + 每页死等 150ms」。
   *   ③ 失败快速退出：连续两批全空（末页或网络异常）立即停止，避免 60 页空转。
   * 任一步拿不到数据都会自动降级到「无名单 + 实时分页」，返回结构与旧实现完全一致。
   *
   * @param {(done:number,total:number)=>void} [onProgress] 进度回调（已拉取只数 / 预估总数）
   * @returns {Promise<Array<{name, code, pureCode, price, changePercent, marketCap}>>}
   */
  async getAllAStocks(onProgress) {
    const _force = new URLSearchParams(location.search).get('allafilter') === '1';
    if (_force) { this._cache.delete('allA'); this._pending.delete('allA'); }
    return this._withCache('allA', API_TTL.SECTOR, () => this._getAllAStocksRaw(onProgress), v => !!(v && v.length));
  },

  /** 静态名单路径（由 scripts/fetch-all-a-stocks.mjs 生成后提交到仓库） */
  ALL_A_JSON: 'data/stocks/all-a.json',
  /** 本机名单缓存键；名单（代码+名称）变化极慢，缓存 7 天足够，避免每天重复 mode 探测 */
  ALL_A_LS_KEY: 'snt.allA.names.v1',
  ALL_A_LS_DAYS: 7,
  /** 名单规模不可能低于此值，用于拒绝残缺/异常文件，防止误用空名单把拉取带偏 */
  ALL_A_MIN_SIZE: 1000,

  _lsGetItem(k) {
    try { return (typeof localStorage !== 'undefined' && localStorage) ? localStorage.getItem(k) : null; }
    catch (e) { return null; }
  },
  _lsSetItem(k, v) {
    try { if (typeof localStorage !== 'undefined' && localStorage) localStorage.setItem(k, v); }
    catch (e) { /* 隐私模式 / 配额已满：忽略，名单拿不到会自动走实时分页，不影响功能 */ }
  },

  /** 归一化一条名单记录 → {code, pureCode, name} */
  _normANameItem(it) {
    if (!it) return null;
    const raw = String(it.pureCode || it.code || it.c || '').trim();
    const pure = raw.replace(/^(sh|sz)/i, '');
    if (!/^\d{6}$/.test(pure)) return null;
    const prefix = /^(6|9|4|8)/.test(pure) ? 'sh' : 'sz';
    return { code: prefix + pure, pureCode: pure, name: String(it.name || it.n || '') };
  },

  /** 读取静态名单 JSON；拿不到返回 null（文件未生成 / 404 / 内容残缺 / 网络异常） */
  async _fetchAllAStatic() {
    try {
      const r = await fetch(this.ALL_A_JSON, { cache: 'no-store' });
      if (!r || !r.ok) return null;
      const j = await r.json();
      const items = j && Array.isArray(j.items) ? j.items : null;
      if (!items || items.length < this.ALL_A_MIN_SIZE) return null;
      const out = [];
      for (const it of items) { const n = this._normANameItem(it); if (n) out.push(n); }
      return out.length >= this.ALL_A_MIN_SIZE ? out : null;
    } catch (e) { return null; }
  },

  _loadAllANames() {
    const raw = this._lsGetItem(this.ALL_A_LS_KEY);
    if (!raw) return null;
    try {
      const o = JSON.parse(raw);
      if (!o || !Array.isArray(o.list) || o.list.length < this.ALL_A_MIN_SIZE) return null;
      if (Date.now() - (o.t || 0) > this.ALL_A_LS_DAYS * 86400000) return null;
      const out = [];
      for (const it of o.list) { const n = this._normANameItem(it); if (n) out.push(n); }
      return out.length >= this.ALL_A_MIN_SIZE ? out : null;
    } catch (e) { return null; }
  },

  _saveAllANames(list) {
    if (!list || list.length < this.ALL_A_MIN_SIZE) return;
    // 只存代码+名称，不含行情：行情必须实时，存下来会过期误导筛选
    const slim = list.map(s => ({ code: s.code, pureCode: s.pureCode, name: s.name }))
      .filter(s => s.pureCode && s.name);
    if (slim.length < this.ALL_A_MIN_SIZE) return;
    // 名单更新了，会话级的名称索引要失效（否则 60 秒内用的还是旧字典）
    this._nameDictCache = null;
    try { this._lsSetItem(this.ALL_A_LS_KEY, JSON.stringify({ t: Date.now(), n: slim.length, list: slim })); }
    catch (e) { /* 序列化失败（超配额）时忽略 */ }
  },

  /** 名单来源优先级：静态 JSON（Actions 生成） > 本机缓存 > null */
  async _getAllANames() {
    const s = await this._fetchAllAStatic();
    if (s) return s;
    return this._loadAllANames();
  },

  _allAPageUrl(pn, pz) {
    return `https://push2.eastmoney.com/api/qt/clist/get?pn=${pn}&pz=${pz}&po=1&np=1&fltt=2&invt=2&fid=f12`
      + `&fs=m:0+t:6,m:0+t:80,m:1+t:2,m:1+t:23&fields=f2,f3,f12,f14,f20`;
  },

  /** 单页请求：带超时保护。_eastGet 内部失败会走 JSONP 兜底（默认 9s），
   *  并发场景下若不加超时，一批失败要串行等到 9 秒才返回。 */
  async _allAFetchPage(pn, pz, timeoutMs) {
    let json = null;
    try {
      json = await Promise.race([
        this._eastGet(this._allAPageUrl(pn, pz)),
        new Promise(r => setTimeout(() => r(null), timeoutMs || 9000))
      ]);
    } catch (e) { json = null; }
    return json || null;
  },

  /**
   * 拉取全 A 实时行情行。
   *
   * 关键优化「pz 自适应」：先用超大 pz 请求第 1 页，用**实际返回条数**反推服务端真正的
   * 每页上限，再据此计算总页数。这一步不额外花请求（第 1 页本来就要拉），却能：
   *   · 服务端支持大页时 → 25+ 次请求骤降到 1~3 次；
   *   · 服务端仍返回 100 条/页时 → 自动退回常规分页，行为与旧实现一致，无副作用。
   *
   * @returns {Promise<{rows:Array, total:(number|null)}>}
   */
  async _fetchAllALiveRows(onProgress, knownTotal) {
    const CONC = 6;        // 批内并发数：够快又不至于触发东财限流
    const GAP = 40;        // 批间微间隔(ms)
    const MAX_PAGES = 80;  // 无名单时的最大探测页数（连续两批空会提前退出）
    const PROBE_PZ = 6000; // 首页试探用的大 pz
    const rowMap = new Map();
    let total = knownTotal || null;
    let emptyBatches = 0;

    const ingest = (j) => {
      const diff = this._diffArray(j);
      if (total == null && j && j.data && j.data.total) total = j.data.total;
      for (const it of diff) {
        const pure = String(it.f12);
        if (!pure) continue;
        const prefix = /^(6|9|4|8)/.test(pure) ? 'sh' : 'sz';
        rowMap.set(pure, {
          code: prefix + pure,
          pureCode: pure,
          name: it.f14 || '',
          price: it.f2 != null ? parseFloat(it.f2) : null,
          changePercent: it.f3 != null ? parseFloat(it.f3) : null,
          marketCap: it.f20 != null ? parseFloat(it.f20) : null
        });
      }
      return diff.length;
    };

    // —— 第 1 页：大 pz 试探，拿服务端真实每页上限 ——
    const first = await this._allAFetchPage(1, PROBE_PZ, 12000);
    if (first) ingest(first);
    let pz = rowMap.size;                                  // 服务端实际生效的每页条数
    if (!Number.isFinite(pz) || pz < 20) pz = 100;          // 异常/过小 → 保守取 100
    if (typeof onProgress === 'function') onProgress(rowMap.size, total || rowMap.size);
    // 首页已取完（服务端支持超大页）或网络已失败
    if (rowMap.size > 0 && total != null && rowMap.size >= total) {
      return { rows: Array.from(rowMap.values()), total: total };
    }
    if (!rowMap.size) emptyBatches = 1;

    const pageCount = total != null ? Math.min(MAX_PAGES, Math.ceil(total / pz)) : MAX_PAGES;
    for (let start = 2; start <= pageCount; start += CONC) {
      const pages = [];
      for (let k = start; k < Math.min(start + CONC, pageCount + 1); k++) pages.push(k);
      // 用「首页实测到的 pz」而非试探值请求后续页：服务端按什么粒度分页就按什么粒度翻页，语义自洽
      const res = await Promise.all(pages.map(p => this._allAFetchPage(p, pz, 9000)));
      let got = 0;
      for (const j of res) if (j) got += ingest(j);
      if (typeof onProgress === 'function') onProgress(rowMap.size, total || rowMap.size);
      if (total != null && rowMap.size >= total) break;
      if (!got) {
        emptyBatches++;
        if (emptyBatches >= 2) break;   // 已到末页，或网络整体异常
      } else emptyBatches = 0;
      if (start + CONC <= pageCount) await new Promise(r => setTimeout(r, GAP));
    }

    // 完整性兜底：万一服务端接受了大 pz 却只部分返回（极罕见），会导致中间段漏拉。
    // 这里用保守的 100/页补拉一遍，靠 rowMap 去重补齐，仅在确实缺失时才会真正执行。
    if (total != null && rowMap.size < total && rowMap.size < total * 0.98) {
      const missPageCount = Math.min(MAX_PAGES, Math.ceil(total / 100));
      for (let start = 1; start <= missPageCount; start += CONC) {
        const pages = [];
        for (let k = start; k < Math.min(start + CONC, missPageCount + 1); k++) pages.push(k);
        const res = await Promise.all(pages.map(p => this._allAFetchPage(p, 100, 9000)));
        let got = 0;
        for (const j of res) if (j) got += ingest(j);
        if (typeof onProgress === 'function') onProgress(rowMap.size, total || rowMap.size);
        if (rowMap.size >= total) break;
        if (!got) break;
        if (start + CONC <= missPageCount) await new Promise(r => setTimeout(r, GAP));
      }
    }
    return { rows: Array.from(rowMap.values()), total: total };
  },

  async _getAllAStocksRaw(onProgress) {
    // ① 名单（可有可无）：拿到就能算出精确页数，省掉多余的翻页探测
    const names = await this._getAllANames();
    const nameMap = names ? new Map(names.map(n => [n.pureCode, n])) : null;

    // ② 实时行情：并发分页
    const { rows } = await this._fetchAllALiveRows(onProgress, nameMap ? nameMap.size : null);

    // ③ 组装：以实时接口为准（它才是当日真实可交易标的），名单仅用于补齐缺失名称
    const all = [];
    const seen = new Set();
    for (const row of rows) {
      if (!row || !row.pureCode || seen.has(row.pureCode)) continue;
      seen.add(row.pureCode);
      if (!row.name && nameMap) {
        const n = nameMap.get(row.pureCode);
        if (n && n.name) row.name = n.name;
      }
      all.push(row);
    }

    // ④ 回写本机名单缓存：下次进入即可「名单已知」，页数精确、少发请求
    if (all.length >= this.ALL_A_MIN_SIZE) this._saveAllANames(all);
    return all;
  },

  /**
   * 获取个股涨幅排行（热门股票）
   * @returns {Array<{name, code, change}>}
   */
  async getStockRanking() {
    return this._withCache('rank:top15', API_TTL.QUOTE, () => this._getStockRankingRaw(), v => !!(v && v.length));
  },

  async _getStockRankingRaw() {
    return this._raceFirstValid([
      () => this._sinaStockRanking(15),
      () => this._eastStockRanking(15)
    ]);
  },

  /** 东财个股涨幅榜（沪深A股），作为新浪的兜底源 */
  async _eastStockRanking() {
    const results = [];
    try {
      // 沪深A股，按涨幅降序
      const url = `https://push2.eastmoney.com/api/qt/clist/get?pn=1&pz=15&po=1&np=1&fltt=2&invt=2&fid=f3&fs=m:0+t:6,m:0+t:80,m:1+t:2,m:1+t:23&fields=f2,f3,f12,f14`;
      const json = await this._eastGet(url);
      for (const item of this._diffArray(json)) {
        const prefix = String(item.f12).startsWith('6') ? 'sh' : 'sz';
        results.push({
          name: item.f14,
          code: prefix + item.f12,
          change: parseFloat(item.f3)
        });
      }
    } catch (e) {
      console.debug('个股排行获取失败', e);
    }
    return results;
  },

  // ============ 新上市股票（batch43 全面换源） ============
  /**
   * 取「新上市股票」清单 —— 上市日期 + 代码 + 名称。
   *
   * 换源原因：该子版块原先完全依赖东财 `push2.eastmoney.com/api/qt/clist/get`。
   *   实测（线上站点同源环境真实浏览器）push2 / push2delay / push2his **三个域名一律
   *   `TypeError: Failed to fetch`** —— 不是偶发限流，而是浏览器侧完全连不通，
   *   所以点「刷新数据」必然失败。
   *
   * 现在改为两级源：
   *   ① 主：东财**数据中心**（datacenter-web）报表 `RPTA_APP_IPOAPPLY`。
   *      与 push2 是两套完全不同的通道（数据中心走离线报表，不做按 IP 频率控制），
   *      一次请求即可拿到全部上市日期（字段 LISTING_DATE / SECURITY_CODE / SECURITY_NAME_ABBR），
   *      浏览器实测 200 且带 CORS，可直连。
   *   ② 备：新浪「次新股」节点 `node=new_stock`（CORS 直连、免费不限流）+ 腾讯日K第一根
   *      （上市首日；上市日永不变更 → localStorage 永久缓存，正常只请求一次）。
   *
   * @param {number} [maxDays=400] 上市天数上限（超出视为老股，不进「新股/次新」口径）
   * @returns {Promise<Array<{name,code,pureCode,change,listingDate,listingDays,market}>>}
   */
  async _newListedCandidates(maxDays = 400) {
    // ① 主源：东财数据中心
    let list = [];
    try {
      const today = new Date(); today.setHours(0, 0, 0, 0);
      const ymd = this.fmtDate(today);
      const from = this.fmtDate(new Date(today.getTime() - maxDays * 86400000));
      const rows = await this._dcGet('RPTA_APP_IPOAPPLY',
        'SECURITY_CODE,SECURITY_NAME_ABBR,LISTING_DATE,MARKET_TYPE_NEW,TRADE_MARKET',
        { pageSize: 400, sortColumns: 'LISTING_DATE', sortTypes: -1,
          filter: `(LISTING_DATE<='${ymd}')(LISTING_DATE>='${from}')` });
      list = this._ipoRowsToStocks(rows, maxDays);
      if (list.length) console.debug(`[新上市股票] 数据中心命中 ${list.length} 只`);
    } catch (e) {
      console.debug('新上市股票：数据中心源不可用，改用新浪兜底', e && e.message);
    }

    // ② 兜底：新浪次新股节点 + 腾讯日K首根补齐上市日
    if (!list.length) {
      try {
        list = await this._sinaNewListedCandidates(maxDays);
        if (list.length) console.debug(`[新上市股票] 新浪兜底命中 ${list.length} 只`);
      } catch (e) {
        console.debug('新上市股票：新浪源亦不可用', e && e.message);
      }
    }
    return list;
  },

  /** 东财数据中心取数（报表通道，浏览器可直连；与 push2 行情域名是两套链路） */
  async _dcGet(reportName, columns, opts = {}) {
    const parts = [
      'reportName=' + encodeURIComponent(reportName),
      'columns=' + encodeURIComponent(columns),
      'pageSize=' + (opts.pageSize || 50),
      'pageNumber=' + (opts.pageNumber || 1),
      'source=WEB', 'client=WEB'
    ];
    if (opts.sortColumns) {
      parts.push('sortColumns=' + encodeURIComponent(opts.sortColumns));
      parts.push('sortTypes=' + (opts.sortTypes == null ? -1 : opts.sortTypes));
    }
    // filter 里的 ( ) ' 需原样传给东财，这里手工编码，避免 URLSearchParams 把整段重排
    if (opts.filter) parts.push('filter=' + encodeURIComponent(opts.filter));
    const url = 'https://datacenter-web.eastmoney.com/api/data/v1/get?' + parts.join('&');
    const j = await this._fetchJson(url, opts.timeoutMs || 12000);
    return (j && j.result && Array.isArray(j.result.data)) ? j.result.data : [];
  },

  // ==================================================================
  //  语义搜索取数层：全部走「东财数据中心报表通道」，零 push2 依赖
  // ==================================================================
  //
  // 为什么必须这么做（batch45 实测定位）：
  //   1) push2.eastmoney.com 在浏览器侧**间歇性限流**（batch44 实测：连测 5 次可用，用户又遇到全灭），
  //      而 batch44 已把板块清单主源切到新浪（仅 175 概念 + 49 行业）。新浪命名体系与东财不同，
  //      里面**没有「人工智能」「芯片」「算力」「低空经济」**这些板块 → 语义搜索的「概念→板块」直接落空，
  //      实测切断东财后 ai / 芯片 / 算力 / 低空经济 一律返回 0 条（低空经济还被错配成「低碳经济」）。
  //   2) searchapi.eastmoney.com 搜索建议接口**已下线**（fetch 与 JSONP 均失败）。
  //
  // 换成的新链路（全部 datacenter-web，实测 200 + CORS + 无限流）：
  //   查询词 --EAST_BOARD_LIST 本地匹配--> 东财板块名
  //          --RPT_F10_CORETHEME_BOARDTYPE 反查--> 该板块成分股（实测「人工智能」751 只）
  //          --RPT_F10_FN_MAINOP 批量 SECUCODE in (...)--> 最新一期「按产品」主营构成
  //          --> 按「命中主营段营收占比之和」降序 = 用户要的「相同业务/产品，按营收比例排序」
  //   批量拉主营构成是性能关键：in(80~100) 只一次请求（实测 100 只 / 229ms），
  //   而旧实现是**逐只**请求 160 次 —— 这正是旧版又慢又容易 0 结果的另一半原因。

  /** SECUCODE('600519.SH') → 带市场前缀代码('sh600519') */
  _dcPrefix(secucode) {
    const s = String(secucode || '').toUpperCase();
    if (s.endsWith('.SH')) return 'sh';
    if (s.endsWith('.SZ')) return 'sz';
    if (s.endsWith('.BJ')) return 'bj';
    return '';
  },

  /** 带市场前缀代码('sh600519') → SECUCODE('600519.SH') */
  _dcSecucode(code) {
    const m = String(code || '').toLowerCase().match(/^(sh|sz|bj)(\d{6})$/);
    return m ? m[2] + '.' + m[1].toUpperCase() : '';
  },

  /**
   * 本地把关键词匹配到东财业务板块名（**零网络请求**）。
   * 东财板块命名体系本身就承载了「业务/产品」语义（BK0800 人工智能 / BK0891 国产芯片 / BK1166 低空经济…），
   * 直接本地命中就能绕过已下线的搜索建议接口。
   * @param {string} kw 关键词
   * @param {number} limit 最多返回几个板块
   * @returns {Array<{name:string, code:string, score:number}>}
   */
  _dcMatchBoards(kw, limit = 8) {
    return this._matchBoardList(eastBoardIndex(), kw, limit);
  },

  /**
   * 板块名打分匹配（`_dcMatchBoards` 与「东财全量库」共用同一把尺子，保证打分口径一致）。
   * 打分：完全相同 1000 > 前缀 900- > 包含 700- > 被包含 500-；同分时短名优先（更精确）。
   * @param {Array<{name:string,code?:string,bk?:string}>} list 候选板块
   * @param {string} kw 关键词
   * @param {number} limit 最多返回条数
   * @returns {Array<{name:string,code:string,score:number}>}
   */
  _matchBoardList(list, kw, limit = 8) {
    const k = String(kw || '').trim().toLowerCase();
    if (k.length < 2) return [];
    const out = [];
    for (const b of (list || [])) {
      const n = String(b.name || '').toLowerCase();
      let score = 0;
      if (n === k) score = 1000;
      else if (n.startsWith(k)) score = 900 - Math.min(120, (n.length - k.length) * 10);
      else if (n.includes(k)) score = 700 - Math.min(120, (n.length - k.length) * 10);
      else if (k.includes(n) && n.length >= 2) score = 500 - Math.min(120, (k.length - n.length) * 10);
      if (score > 0) out.push({ name: b.name, code: b.code || b.bk, score });
    }
    out.sort((a, b) => (b.score - a.score) || (a.name.length - b.name.length));
    return out.slice(0, limit);
  },

  /**
   * 用数据中心报表按「板块名 / 板块代码」反查成分股（**完全不经过 push2**）。
   * 报表：RPT_F10_CORETHEME_BOARDTYPE（全市场 9.4 万行，pageSize 实测支持 5000）。
   * @param {string} boardOrCode 板块名（如「人工智能」）或板块代码（BK0800）
   * @returns {Promise<Array<{code,name,secucode,pureCode}>>} code 为带前缀格式
   */
  async _dcBoardStocks(boardOrCode, maxCodes = 2000) {
    const key = String(boardOrCode || '').trim();
    if (!key) return [];
    return this._withCache('dcb:' + key, 6 * 60 * 60 * 1000, async () => {
      const isCode = /^BK\d+$/i.test(key);
      const filter = isCode
        ? `(NEW_BOARD_CODE="${key.toUpperCase()}")`
        : `(BOARD_NAME="${key}")`;
      const COLS = 'SECUCODE,SECURITY_CODE,SECURITY_NAME_ABBR,NEW_BOARD_CODE,BOARD_NAME';
      const PS = 5000;
      const acc = new Map();
      for (let pn = 1; pn <= 3; pn++) {
        let rows = [];
        try {
          rows = await this._dcGet('RPT_F10_CORETHEME_BOARDTYPE', COLS, {
            filter, pageSize: PS, pageNumber: pn
          });
        } catch (e) { break; }
        if (!rows.length) break;
        for (const r of rows) {
          const sc = String(r.SECUCODE || '');
          const pre = this._dcPrefix(sc);
          const pure = String(r.SECURITY_CODE || '').trim();
          if (!pre || !/^\d{6}$/.test(pure)) continue;
          const code = pre + pure;
          if (!acc.has(code)) acc.set(code, { code, name: r.SECURITY_NAME_ABBR || pure, secucode: sc, pureCode: pure });
        }
        if (rows.length < PS) break;
        if (acc.size >= maxCodes) break;
      }
      return [...acc.values()].slice(0, maxCodes);
    }, v => !!(v && v.length));
  },

  // ==================================================================
  //  东财板块「全量库」（batch51）
  // ==================================================================
  //
  // 为什么需要它（实测定位）：
  //   选股页的「板块搜索」原先只在新浪静态快照（**仅 224 个板块**：49 行业 + 175 概念）里做
  //   `name.includes(kw)`。新浪的命名体系与东财**完全不同**：没有「新能源车」「算力」「低空经济」
  //   「半导体」，只有笼统的「新能源」「机器人概念」「锂电池」。
  //   于是用户输入「新能源车」→ 本地 0 命中 → 再落到**已下线的**东财搜索建议接口 → 最终 0 条结果，
  //   选股页一个板块都不显示，自然「没有成分股」。同类词（算力 / 低空经济 / 半导体 / 人形机器人…）
  //   全部一样，属**系统性**缺陷，而非个例。
  //
  // 解决：
  //   ① 本地内置词典 EAST_BOARD_LIST（946 个东财板块名 → BK，**零网络**）+ 打分匹配 → 覆盖绝大多数查询；
  //   ② 需要「全量」时（点「📚 加载全部板块」或词典零命中）再从 BOARDTYPE 报表聚合出全部 1031 个板块。
  //      该报表实测 94563 行 / 19 页（pageSize=5000），是**报表通道**（datacenter-web），
  //      与 push2 行情域名是两套链路：200 + CORS + 不限流，万级用户各自本地缓存即可，无单点限流。
  //      只缓存**聚合结果**（约 40KB 文本，3 天），不缓存 12MB 原始行。

  EAST_BOARDS_LS_KEY: 'snt.eastBoards',
  EAST_BOARDS_TTL: 3 * 24 * 60 * 60 * 1000,
  _eastBoards: null,
  _eastBoardsAt: 0,
  _eastBoardsPromise: null,

  _loadEastBoardsFromLS() {
    if (this._eastBoards && Date.now() - this._eastBoardsAt < this.EAST_BOARDS_TTL) return this._eastBoards;
    try {
      if (typeof localStorage !== 'undefined' && localStorage) {
        const raw = localStorage.getItem(this.EAST_BOARDS_LS_KEY);
        if (raw) {
          const o = JSON.parse(raw);
          if (o && o.d && Date.now() - (o.t || 0) < this.EAST_BOARDS_TTL) {
            const list = [];
            for (const line of String(o.d).split('\n')) {
              if (!line) continue;
              const seg = line.split('|');
              if (seg.length < 2) continue;
              list.push({ bk: seg[0], name: seg[1], count: +seg[2] || 0 });
            }
            if (list.length) { this._eastBoards = list; this._eastBoardsAt = o.t || 0; return list; }
          }
        }
      }
    } catch (e) { /* 解析失败 → 重新构建 */ }
    return null;
  },

  _saveEastBoardsToLS(list) {
    try {
      const d = list.map(b => b.bk + '|' + b.name + '|' + b.count).join('\n');
      localStorage.setItem(this.EAST_BOARDS_LS_KEY, JSON.stringify({ t: Date.now(), d }));
    } catch (e) { /* 隐私模式 / 超配额：仅影响下次是否重扫 */ }
  },

  /**
   * 东财板块全量库（板块名 → BK + 成分股数，实测 1031 个）。
   * 19 页 × pageSize=5000 一次拉全后在本地聚合；结果缓存 3 天（内存 + localStorage）。
   * @param {(done:number,total:number)=>void} [onProgress]
   * @returns {Promise<Array<{bk:string,name:string,count:number}>>}
   */
  async _dcAllBoards(onProgress) {
    const cached = this._loadEastBoardsFromLS();
    if (cached) return cached;
    if (this._eastBoardsPromise) return this._eastBoardsPromise;   // 并发收敛：只拉一次
    this._eastBoardsPromise = (async () => {
      const COLS = 'SECUCODE,NEW_BOARD_CODE,BOARD_NAME';
      const PS = 5000;
      const acc = new Map();
      const addRows = (rows) => {
        for (const r of rows) {
          const bk = String(r.NEW_BOARD_CODE || '').trim();
          const nm = String(r.BOARD_NAME || '').trim();
          if (!bk || !nm) continue;
          const e = acc.get(bk);
          if (e) e.count++;
          else acc.set(bk, { bk, name: nm, count: 1 });
        }
      };
      // 首页顺带拿 count → 页数（少一次往返）
      let first = [], pages = 20;
      try {
        const url = 'https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_CORETHEME_BOARDTYPE'
          + '&columns=' + encodeURIComponent(COLS) + '&pageSize=' + PS + '&pageNumber=1&source=WEB&client=WEB';
        const j = await this._fetchJson(url, 25000);
        first = (j && j.result && Array.isArray(j.result.data)) ? j.result.data : [];
        const cnt = j && j.result && j.result.count;
        if (cnt) pages = Math.min(30, Math.ceil(cnt / PS));
      } catch (e) { return []; }
      if (!first.length) return [];
      addRows(first);
      let done = 1;
      if (onProgress) onProgress(done, pages);
      const queue = [];
      for (let p = 2; p <= pages; p++) queue.push(p);
      const CONC = 4;
      const worker = async () => {
        for (;;) {
          const pn = queue.shift();
          if (pn === undefined) return;
          let rows = [];
          for (let attempt = 0; attempt < 3; attempt++) {
            try {
              rows = await this._dcGet('RPT_F10_CORETHEME_BOARDTYPE', COLS, { pageSize: PS, pageNumber: pn, timeoutMs: 25000 });
              break;
            } catch (e) { if (attempt < 2) await new Promise(r => setTimeout(r, 300 * (attempt + 1))); }
          }
          if (rows.length) addRows(rows);
          done++;
          if (onProgress) onProgress(done, pages);
        }
      };
      await Promise.all(Array.from({ length: CONC }, worker));
      const list = [...acc.values()].sort((a, b) => (b.count - a.count) || a.bk.localeCompare(b.bk));
      if (list.length) {
        this._eastBoards = list;
        this._eastBoardsAt = Date.now();
        this._saveEastBoardsToLS(list);
      }
      return list;
    })();
    try { return await this._eastBoardsPromise; }
    finally { this._eastBoardsPromise = null; }
  },

  /**
   * 板块搜索用的「东财板块名」候选集合：
   * 本地内置词典（946 个，**零网络**）+ 已缓存的全量库（1031 个，含成分股数），按 BK 去重。
   */
  _eastBoardsForSearch() {
    const map = new Map();
    for (const b of eastBoardIndex()) map.set(b.code, { bk: b.code, name: b.name, count: 0 });
    for (const b of (this._eastBoards || [])) map.set(b.bk, { bk: b.bk, name: b.name, count: b.count || 0 });
    return [...map.values()];
  },

  /**
   * 推断东财板块的展示分类。
   * 🔴 选股页把搜索结果分三组渲染（主行业概念 / 次行业概念 / 指数板块），
   * type 落空会让该条**完全不显示**，所以必须给出确定值。
   * BOARDTYPE 报表没有权威 type（实测 BOARD_TYPE 全为 null），因此按名称保守推断：
   * 申万行业名（含 Ⅱ/Ⅲ）与新浪行业名 → 行业；指数类命名 → 指数；其余 → 概念。
   * @param {string} name 板块名
   * @param {Set<string>} [industryNames] 已知行业名集合（来自新浪板块库的 type='行业'）
   * @returns {'行业'|'概念'|'指数'}
   */
  _boardTypeOf(name, industryNames) {
    const n = String(name || '').trim();
    if (!n) return '概念';
    if (industryNames && industryNames.has(n)) return '行业';
    if (/[ⅠⅡⅢ]$/.test(n)) return '行业';                     // 申万二级/三级（白酒Ⅱ / 保险Ⅲ）
    if (/_$/.test(n)) return '指数';                           // 上证50_ / HS300_ / 央视50_
    if (/^(上证|深证|沪深|中证|央视|深成|创业|科创|北证)/.test(n)) return '指数';
    return '概念';
  },

  /** 主营构成本地缓存（语义搜索/同类股票/反推业务共用，避免重复请求） */
  _mbCache: new Map(),   // code -> { t, v: [{name, ratio}] }

  /**
   * **批量**取多只股票最新一期「按产品」主营构成。
   * 关键：MAINOP 支持 `(SECUCODE in ("a","b",...))`，一次可带 80~100 只（实测 100 只 / 229ms），
   * 相比逐只请求（旧实现 160 次）请求数下降两个数量级，是「又快又不 0 结果」的核心。
   * @param {string[]} codes 带市场前缀的代码数组
   * @returns {Promise<Map<string, Array<{name:string,ratio:number}>>>} code → 主营构成段
   */
  async _dcMainBizBatch(codes) {
    const uniq = [...new Set((codes || []).map(c => String(c || '').toLowerCase())
      .filter(c => /^(sh|sz|bj)\d{6}$/.test(c)))];
    const map = new Map();
    if (!uniq.length) return map;
    const now = Date.now();
    const MB_TTL = 6 * 60 * 60 * 1000;
    // 先吃本地缓存，只把没缓存的送去请求
    const need = [];
    for (const c of uniq) {
      const hit = this._mbCache.get(c);
      if (hit && now - hit.t < MB_TTL) { if (hit.v && hit.v.length) map.set(c, hit.v); }
      else need.push(c);
    }
    if (!need.length) return map;
    const BATCH = 80;                        // 80 只/请求：实测平均 ~4.5 段/只，稳妥落在 500 行/页内
    const batches = [];
    for (let i = 0; i < need.length; i += BATCH) batches.push(need.slice(i, i + BATCH));
    const COLS = 'SECUCODE,SECURITY_CODE,ITEM_NAME,MBI_RATIO';
    const results = await this._mapLimit(batches, 6, async (group) => {
      const scl = group.map(c => '"' + this._dcSecucode(c) + '"').join(',');
      const filter = `(SECUCODE in (${scl}))(IS_NEW=1)(MAINOP_TYPE="2")`;
      const acc = new Map();
      for (let pn = 1; pn <= 6; pn++) {
        let rows = [];
        try {
          rows = await this._dcGet('RPT_F10_FN_MAINOP', COLS, {
            filter, pageSize: 500, pageNumber: pn,
            sortColumns: 'SECUCODE', sortTypes: 1
          });
        } catch (e) { break; }
        if (!rows.length) break;
        for (const r of rows) {
          const pre = this._dcPrefix(r.SECUCODE);
          const pure = String(r.SECURITY_CODE || '').trim();
          if (!pre || !/^\d{6}$/.test(pure)) continue;
          const code = pre + pure;
          const nm = String(r.ITEM_NAME || '').trim();
          const ratio = r.MBI_RATIO != null ? +r.MBI_RATIO : null;
          if (!nm || ratio == null) continue;
          if (!acc.has(code)) acc.set(code, []);
          acc.get(code).push({ name: nm, ratio });
        }
        if (rows.length < 500) break;
      }
      return acc;
    });
    for (const m of results) { if (m) for (const [k, v] of m) map.set(k, v); }
    // 写缓存（取到的与取不到的都记，避免反复打接口）
    const t = Date.now();
    for (const c of need) this._mbCache.set(c, { t, v: map.get(c) || null });
    return map;
  },

  // ---- 行业字段本地缓存（勾选弹窗批量补行业用）----
  _indCache: new Map(),   // code -> { t, v: '食品饮料' }

  /**
   * **批量**取多只股票的所属行业（东财 F10 公司概况 RPT_F10_ORG_BASICINFO）。
   * 关键：该报表与 MAINOP 一样支持 `(SECUCODE in (...))`（实测 200 只 / 166ms），
   * 把「选股勾选弹窗」原来**逐只** getIndustry 的上千次请求压到个位数 ——
   * 这是「一个 719 只成分股的板块（新能源车）也不打爆免费接口」的关键，万级用户下同样成立。
   * @param {string[]} codes 带市场前缀的代码数组
   * @returns {Promise<Map<string,string>>} code → 一级行业名
   */
  async _dcIndustryBatch(codes) {
    const uniq = [...new Set((codes || []).map(c => String(c || '').toLowerCase())
      .filter(c => /^(sh|sz|bj)\d{6}$/.test(c)))];
    const map = new Map();
    if (!uniq.length) return map;
    const now = Date.now();
    const TTL = 24 * 60 * 60 * 1000;
    const need = [];
    for (const c of uniq) {
      const hit = this._indCache.get(c);
      if (hit && now - hit.t < TTL) { if (hit.v) map.set(c, hit.v); }
      else need.push(c);
    }
    if (!need.length) return map;
    const BATCH = 80;                       // 与主营构成同口径：稳妥落在单页返回内
    const batches = [];
    for (let i = 0; i < need.length; i += BATCH) batches.push(need.slice(i, i + BATCH));
    const COLS = 'SECUCODE,SECURITY_CODE,BOARD_NAME_1LEVEL,BOARD_NAME_2LEVEL,SWINDUSTRY_NAME2,CSRC_INDUSTRY_NAME';
    const results = await this._mapLimit(batches, 6, async (group) => {
      const scl = group.map(c => '"' + this._dcSecucode(c) + '"').join(',');
      const filter = `(SECUCODE in (${scl}))`;
      const acc = new Map();
      for (let pn = 1; pn <= 6; pn++) {
        let rows = [];
        try {
          rows = await this._dcGet('RPT_F10_ORG_BASICINFO', COLS, { filter, pageSize: 500, pageNumber: pn });
        } catch (e) { break; }
        if (!rows.length) break;
        for (const r of rows) {
          const pre = this._dcPrefix(r.SECUCODE);
          const pure = String(r.SECURITY_CODE || '').trim();
          if (!pre || !/^\d{6}$/.test(pure)) continue;
          let nm = r.BOARD_NAME_1LEVEL || r.SWINDUSTRY_NAME2 || '';
          if (!nm && r.CSRC_INDUSTRY_NAME) {
            const parts = String(r.CSRC_INDUSTRY_NAME).split('-');
            nm = parts[parts.length - 1];
          }
          if (!nm) continue;
          acc.set(pre + pure, String(nm));
        }
        if (rows.length < 500) break;
      }
      return acc;
    });
    for (const m of results) { if (m) for (const [k, v] of m) map.set(k, v); }
    const t = Date.now();
    for (const c of need) this._indCache.set(c, { t, v: map.get(c) || null });
    return map;
  },

  /** 批量取行业（对外入口，供选股勾选弹窗一次性补全「行业」列） */
  async getIndustriesBatch(codes) {
    try { return await this._dcIndustryBatch(codes); } catch (e) { return new Map(); }
  },

  /** 批量取最新一期「按产品」主营构成（对外入口，供勾选弹窗补全「主业与主要产品」列） */
  async getMainBusinessBatch(codes) {
    try { return await this._dcMainBizBatch(codes); } catch (e) { return new Map(); }
  },

  // ---- 全市场主营构成索引（深度扫描用）----
  ALL_MB_LS_KEY: 'snt.allMainBiz',
  _allMbIndex: null,      // Map<secucode, Array<[name, ratioBp]>>
  _allMbAt: 0,
  ALL_MB_TTL: 3 * 24 * 60 * 60 * 1000,   // 3 天（季报期内足够新）

  _loadAllMbFromLS() {
    if (this._allMbIndex) return this._allMbIndex;
    try {
      if (typeof localStorage !== 'undefined' && localStorage) {
        const raw = localStorage.getItem(this.ALL_MB_LS_KEY);
        if (raw) {
          const o = JSON.parse(raw);
          if (o && o.d && Date.now() - (o.t || 0) < this.ALL_MB_TTL) {
            const m = new Map();
            for (const line of String(o.d).split('\n')) {
              if (!line) continue;
              const seg = line.split('|');
              const sc = seg[0];
              if (!sc) continue;
              const arr = [];
              for (let i = 1; i < seg.length; i++) {
                const j = seg[i].lastIndexOf(':');
                if (j <= 0) continue;
                arr.push([seg[i].slice(0, j), (+seg[i].slice(j + 1)) / 10000]);
              }
              if (arr.length) m.set(sc, arr);
            }
            if (m.size) { this._allMbIndex = m; this._allMbAt = o.t || 0; return m; }
          }
        }
      }
    } catch (e) { /* 解析失败 → 重新构建 */ }
    return null;
  },

  _saveAllMbToLS(m) {
    try {
      const lines = [];
      for (const [sc, arr] of m) {
        let s = sc;
        for (const [n, r] of arr) s += '|' + n + ':' + Math.round(r * 10000);
        lines.push(s);
      }
      localStorage.setItem(this.ALL_MB_LS_KEY, JSON.stringify({ t: Date.now(), d: lines.join('\n') }));
    } catch (e) { /* 隐私模式 / 容量超额：仅影响下次是否重扫 */ }
  },

  // ---- 全市场「行业归属」索引（batch53：深度扫描的第二召回通道）----
  //
  // 为什么需要（实测定位）：
  //   深度扫描原先**只**按「主营构成段名是否字面包含关键词」召回。而段名是各家公司自报的业务线名称，
  //   用词千差万别 —— 同一行业的公司命名不统一，召回率就随命名风格随机波动。
  //   实测「证券」：券商板块（证券Ⅱ / BK0473）共 **49 只**，其中**只有 21 只**的主营段名含「证券」，
  //   **28 只被丢掉**（57% 缺失），中国银河、国泰海通正在缺失名单里：
  //     中信证券 段名 = 证券投资业务 / 证券承销业务            → 含「证券」✓
  //     中国银河 段名 = 财富管理业务 / 投资交易业务 / 机构业务… → 不含 ✗
  //     国泰海通 段名 = 机构与交易 / 财富管理 / 投资管理…      → 不含 ✗
  //   而它们的**行业归属字段是 100% 覆盖且命名统一的**：
  //     49/49 都是 BOARD_NAME_1LEVEL=非银金融、BOARD_NAME_2LEVEL=证券Ⅱ、CSRC=金融业-资本市场服务。
  //   → 因此新增本索引：按「行业名」召回，与「段名」召回取并集。
  //
  // 成本：RPT_F10_ORG_BASICINFO 全市场约 5400 行，pageSize=5000 → **2 页**（对比主营构成索引 103 页）。
  IND_LS_KEY: 'snt.allIndustry',
  IND_TTL: 3 * 24 * 60 * 60 * 1000,
  _allIndIndex: null,
  _allIndAt: 0,
  _allIndPromise: null,

  _loadAllIndFromLS() {
    if (this._allIndIndex) return this._allIndIndex;
    try {
      if (typeof localStorage !== 'undefined' && localStorage) {
        const raw = localStorage.getItem(this.IND_LS_KEY);
        if (raw) {
          const o = JSON.parse(raw);
          if (o && o.d && Date.now() - (o.t || 0) < this.IND_TTL) {
            const m = new Map();
            for (const line of String(o.d).split('\n')) {
              if (!line) continue;
              const seg = line.split('|');
              const sc = seg[0];
              if (!sc) continue;
              m.set(sc, { name: seg[1] || '', l1: seg[2] || '', l2: seg[3] || '', csrc: seg[4] || '' });
            }
            if (m.size) { this._allIndIndex = m; this._allIndAt = o.t || 0; return m; }
          }
        }
      }
    } catch (e) { /* 解析失败 → 重新构建 */ }
    return null;
  },

  _saveAllIndToLS(m) {
    try {
      const lines = [];
      for (const [sc, v] of m) lines.push([sc, v.name, v.l1, v.l2, v.csrc].join('|'));
      localStorage.setItem(this.IND_LS_KEY, JSON.stringify({ t: Date.now(), d: lines.join('\n') }));
    } catch (e) { /* 隐私模式 / 配额：仅影响下次是否重扫 */ }
  },

  /**
   * 全市场「行业归属」索引：secucode → { name, l1, l2, csrc }。
   * 数据源 RPT_F10_ORG_BASICINFO（BOARD_NAME_1LEVEL / BOARD_NAME_2LEVEL / CSRC_INDUSTRY_NAME），
   * 一次 5000 条 × 2 页，本会话 + localStorage 3 天复用。
   * @returns {Promise<Map<string,{name:string,l1:string,l2:string,csrc:string}>>}
   */
  async _allMarketIndustryIndex() {
    const cached = this._loadAllIndFromLS();
    if (cached) return cached;
    if (this._allIndPromise) return this._allIndPromise;
    this._allIndPromise = (async () => {
      const COLS = 'SECUCODE,SECURITY_NAME_ABBR,BOARD_NAME_1LEVEL,BOARD_NAME_2LEVEL,CSRC_INDUSTRY_NAME';
      const PS = 5000;
      const idx = new Map();
      const addRows = (rows) => {
        for (const r of rows) {
          const sc = String(r.SECUCODE || '').toUpperCase();
          if (!/^\d{6}\.(SH|SZ|BJ)$/.test(sc)) continue;
          idx.set(sc, {
            name: r.SECURITY_NAME_ABBR || '',
            l1: String(r.BOARD_NAME_1LEVEL || '').trim(),
            l2: String(r.BOARD_NAME_2LEVEL || '').trim(),
            csrc: String(r.CSRC_INDUSTRY_NAME || '').trim()
          });
        }
      };
      let pages = 2;
      try {
        const j = await this._fetchJson(
          'https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_ORG_BASICINFO'
          + '&columns=' + encodeURIComponent(COLS)
          + '&pageSize=' + PS + '&pageNumber=1&source=WEB&client=WEB'
          + '&sortColumns=SECUCODE&sortTypes=1', 25000);
        const rows = (j && j.result && Array.isArray(j.result.data)) ? j.result.data : [];
        const cnt = j && j.result && j.result.count;
        if (cnt) pages = Math.min(4, Math.ceil(cnt / PS));
        addRows(rows);
      } catch (e) { /* 首页失败 → 交给上层走别的通道 */ }
      for (let p = 2; p <= pages; p++) {
        try {
          const rows = await this._dcGet('RPT_F10_ORG_BASICINFO', COLS, {
            pageSize: PS, pageNumber: p, sortColumns: 'SECUCODE', sortTypes: 1, timeoutMs: 25000
          });
          addRows(rows);
          if (!rows.length) break;
        } catch (e) { /* 单页失败不影响其它页 */ }
      }
      if (idx.size) {
        this._allIndIndex = idx;
        this._allIndAt = Date.now();
        this._saveAllIndToLS(idx);
      }
      return idx;
    })();
    try { return await this._allIndPromise; } finally { this._allIndPromise = null; }
  },

  /**
   * 全市场主营构成索引（深度扫描）：
   * 一次拉齐**全部 A 股**最新一期「按产品」主营构成，之后所有语义搜索都退化成纯本地匹配。
   * 成本实测：约 103 页 × 94KB ≈ 10MB、并发 8 下 ~3~6s（**一个会话只构建一次**，并持久化 3 天）。
   * 用于「同业务/同产品」一定要**扫全市场**的场景（板块库里没有对应板块时，如「复合铜箔」「HBM」）。
   * @param {(done:number,total:number)=>void} [onProgress]
   */
  async _allMarketMainBizIndex(onProgress) {
    const cached = this._loadAllMbFromLS();
    if (cached) return cached;
    const COLS = 'SECUCODE,SECURITY_CODE,ITEM_NAME,MBI_RATIO';
    const FILTER = '(IS_NEW=1)(MAINOP_TYPE="2")';
    const PS = 500;
    // 首页 + 总数：一次请求同时拿到 data 与 count（少一次往返）
    let first = [], pages = 120;
    try {
      const j = await this._fetchJson(
        'https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_F10_FN_MAINOP'
        + '&columns=' + encodeURIComponent(COLS)
        + '&filter=' + encodeURIComponent(FILTER)
        + '&pageSize=' + PS + '&pageNumber=1&source=WEB&client=WEB'
        + '&sortColumns=SECUCODE&sortTypes=1', 20000);
      first = (j && j.result && Array.isArray(j.result.data)) ? j.result.data : [];
      const cnt = j && j.result && j.result.count;
      // count 拿不到就按经验值兜底（实测全市场约 5.1 万行 / 500 = 103 页）
      if (cnt) pages = Math.min(200, Math.ceil(cnt / PS));
    } catch (e) { return new Map(); }
    if (!first.length) return new Map();
    const total = pages;
    const idx = new Map();
    const addRows = (rows) => {
      for (const r of rows) {
        const sc = String(r.SECUCODE || '').toUpperCase();
        const nm = String(r.ITEM_NAME || '').trim();
        const ratio = r.MBI_RATIO != null ? +r.MBI_RATIO : null;
        if (!sc || !nm || ratio == null) continue;
        if (!idx.has(sc)) idx.set(sc, []);
        idx.get(sc).push([nm, ratio]);
      }
    };
    addRows(first);
    let done = 1;
    if (onProgress) onProgress(done, total);
    const queue = [];
    for (let p = 2; p <= pages; p++) queue.push(p);
    const CONC = 10;
    const fetchPage = async (pn) => {
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          const rows = await this._dcGet('RPT_F10_FN_MAINOP', COLS, {
            filter: FILTER, pageSize: PS, pageNumber: pn, sortColumns: 'SECUCODE', sortTypes: 1,
            timeoutMs: 25000
          });
          return rows;
        } catch (e) { /* 失败退避后重试（数据中心偶发抽风/短时限流） */
          if (attempt < 2) await new Promise(r => setTimeout(r, 400 * (attempt + 1) + Math.random() * 400));
        }
      }
      return [];
    };
    const worker = async () => {
      for (;;) {
        const pn = queue.shift();
        if (pn === undefined) return;
        const rows = await fetchPage(pn);
        if (rows.length) addRows(rows);
        done++;
        if (onProgress) onProgress(done, total);
      }
    };
    await Promise.all(Array.from({ length: CONC }, worker));
    if (idx.size) {
      this._allMbIndex = idx;
      this._allMbAt = Date.now();
      this._saveAllMbToLS(idx);
    }
    return idx;
  },

  /** 把全市场索引里某只股票的主营构成转成 _parseMainBiz 的同构格式（{name,ratio}，ratio 为小数） */
  _mbFromIndex(idx, secucode) {
    const arr = idx.get(String(secucode || '').toUpperCase());
    if (!arr || !arr.length) return null;
    return arr.map(([name, ratio]) => ({ name, ratio }));
  },

  /** 把 RPTA_APP_IPOAPPLY 的报表行转成股票对象（剔除未上市/超期/非 6 位代码） */
  _ipoRowsToStocks(rows, maxDays) {
    const out = [];
    const today0 = new Date(); today0.setHours(0, 0, 0, 0);
    for (const r of (rows || [])) {
      const pure = String(r.SECURITY_CODE || '').trim();
      if (!/^\d{6}$/.test(pure)) continue;
      const raw = String(r.LISTING_DATE || '').slice(0, 10);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(raw)) continue;
      const d = new Date(raw + 'T00:00:00');
      if (isNaN(d.getTime())) continue;
      const days = Math.round((today0.getTime() - d.getTime()) / 86400000);
      if (days < 0 || days > maxDays) continue;   // 还没上市 / 已是老股
      out.push({
        name: r.SECURITY_NAME_ABBR || r.SECURITY_NAME || pure,
        code: this._marketPrefix(pure, r.MARKET_TYPE_NEW || r.TRADE_MARKET),
        pureCode: pure,
        change: 0,
        listingDate: raw,
        listingDays: days,
        market: r.MARKET_TYPE_NEW || ''
      });
    }
    return out;
  },

  /**
   * 按「板块 + 代码段」定市场前缀。
   * 注意：不能只靠 inferPrefix —— 北交所 920xxx 落在 `^9` 段，会被误判成沪市，
   * 而腾讯/新浪对北交所都要求 `bj` 前缀，前缀错了行情就取不到。
   */
  _marketPrefix(pure, marketName) {
    const p = String(pure || '').trim();
    const m = String(marketName || '');
    if (/北交所|北京证券/.test(m)) return 'bj' + p;
    if (/科创/.test(m) || /^68/.test(p)) return 'sh' + p;
    if (/^92/.test(p) || /^[48]/.test(p)) return 'bj' + p;
    return this.inferPrefix(p);
  },

  // ---- 上市日永久缓存：上市日期不会变，同一代码只需取一次 ----
  LISTING_LS_KEY: 'snt.listingDates',
  _listingDateCache: null,
  _listingDateStore() {
    if (this._listingDateCache) return this._listingDateCache;
    let m = {};
    try {
      if (typeof localStorage !== 'undefined' && localStorage) {
        m = JSON.parse(localStorage.getItem(this.LISTING_LS_KEY) || '{}') || {};
      }
    } catch (e) { m = {}; }
    this._listingDateCache = (m && typeof m === 'object') ? m : {};
    return this._listingDateCache;
  },
  _saveListingDates() {
    try {
      if (typeof localStorage !== 'undefined' && localStorage && this._listingDateCache) {
        localStorage.setItem(this.LISTING_LS_KEY, JSON.stringify(this._listingDateCache));
      }
    } catch (e) { /* 隐私模式 / 容量超额：仅影响下次是否重取，不影响正确性 */ }
  },

  /**
   * 取某代码的上市首日：腾讯日K接口从最新往回给，返回数组的**第一根就是最早一根**，
   * 对上市不足 320 个交易日的次新股即为上市首日。上市日永不变 → 写入 localStorage 永久缓存。
   * @returns {Promise<string>} 'YYYY-MM-DD'，取不到返回 ''
   */
  async _listingDateOf(code) {
    const c = String(code || '').toLowerCase();
    if (!/^(sh|sz|bj)\d{6}$/.test(c)) return '';
    const store = this._listingDateStore();
    if (store[c]) return store[c];
    // 直连优先，失败退 JSONP（腾讯支持 _var= 变量名，可走 <script> 直载）
    const url = `https://web.ifzq.gtimg.cn/appstock/app/fqkline/get?param=${c},day,,,320,qfq`;
    let j = null;
    try { j = await this._fetchJson(url, 8000); } catch (e) { /* 直连失败，试 script 直载 */ }
    if (!j) {
      try {
        if (typeof document !== 'undefined') {
          // 变量名必须每次唯一：并发补上市日时若共用同名，会互相覆盖串号
          const vn = '__txk_' + Math.random().toString(36).slice(2);
          j = await this._sinaLoadVar(url + '&_var=' + vn, vn);
        }
      } catch (e) { /* 两条路都不通 */ }
    }
    const node = j && j.data && j.data[c];
    const bars = (node && (node.qfqday || node.day)) || [];
    if (!bars.length) return '';
    const first = String((bars[0] && bars[0][0]) || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(first)) return '';
    store[c] = first;
    this._saveListingDates();
    return first;
  },

  /**
   * 新浪兜底：`node=new_stock`（次新股节点，CORS 直连、免费不限流，实测约 160 只）
   * 逐只补上市日（腾讯日K首根），并发 6，失败的不计入（避免渲染出「上市 NaN 天」）。
   */
  async _sinaNewListedCandidates(maxDays) {
    const url = (page) => 'https://vip.stock.finance.sina.com.cn/quotes_service/api/json_v2.php/'
      + `Market_Center.getHQNodeData?page=${page}&num=100&sort=symbol&asc=0&node=new_stock&symbol=&_s_r_a=page`;
    const rows = [];
    for (let page = 1; page <= 3; page++) {
      let arr = null;
      // 新浪偶发断连（实测同参数一次 200 / 一次 Failed to fetch），同一页重试一次
      for (let t = 0; t < 2 && !arr; t++) {
        try { arr = await this._fetchJson(url(page), 8000); } catch (e) { /* 重试 */ }
      }
      if (!Array.isArray(arr) || !arr.length) break;
      rows.push(...arr);
      if (arr.length < 100) break;
    }
    if (!rows.length) return [];
    const today0 = new Date(); today0.setHours(0, 0, 0, 0);
    const dates = await this._mapLimit(rows, 6, r => this._listingDateOf(r.symbol));
    const out = [];
    rows.forEach((r, i) => {
      const raw = dates[i];
      if (!raw) return;
      const d = new Date(raw + 'T00:00:00');
      if (isNaN(d.getTime())) return;
      const days = Math.round((today0.getTime() - d.getTime()) / 86400000);
      if (days < 0 || days > maxDays) return;
      out.push({
        name: r.name || r.code,
        code: this._marketPrefix(r.code, ''),
        pureCode: String(r.code || ''),
        change: parseFloat(r.changepercent) || 0,
        listingDate: raw,
        listingDays: days,
        market: ''
      });
    });
    return out;
  },

  /**
   * 获取新上市股票（按上市天数升序取前 50）。
   * 数据源：① 东财数据中心 RPTA_APP_IPOAPPLY（上市清单）② 新浪 node=new_stock + 腾讯日K（兜底）
   * 当日涨幅统一由腾讯批量行情补齐（一次请求 50 只）。
   * @returns {Promise<Array<{name,code,pureCode,change,listingDate,listingDays,market}>>}
   */
  async getNewListedStocks() {
    return this._withCache('newlisted', API_TTL.KLINE, () => this._getNewListedStocksRaw(), v => !!(v && v.length));
  },

  async _getNewListedStocksRaw() {
    const list = await this._newListedCandidates(400);
    if (!list.length) return [];

    // 上市天数升序（越新越靠前）；同天数按代码，保证结果稳定可复现
    list.sort((a, b) => (a.listingDays - b.listingDays) || String(a.code).localeCompare(String(b.code)));
    const top = list.slice(0, 50);

    // 当日涨幅：腾讯批量行情（一次请求即可覆盖 50 只；失败不影响清单本身）
    try {
      const quotes = await this.getQuotes(top.map(s => s.code));
      top.forEach(s => {
        const q = quotes && quotes[s.code];
        if (!q) return;
        if (q.changePercent != null && !isNaN(q.changePercent)) s.change = q.changePercent;
        if (q.name) s.name = q.name;
      });
    } catch (e) { /* 取不到涨幅就显示清单，不因此判定整轮失败 */ }

    top.forEach(s => { if (s.change == null || isNaN(s.change)) s.change = 0; });
    return top;
  },

  /**
   * 【旧实现，保留为最后兜底】东财行情中心 clist 的「新股/次新股」板块（push2 域名）。
   * 实测该域名在浏览器侧已完全连不通，正常情况下不会走到这里；
   * 保留是为了万一上游恢复时能自动接回原口径。
   */
  async _eastNewListedStocks() {
    const results = [];
    try {
      const url = `https://push2.eastmoney.com/api/qt/clist/get?pn=1&pz=1000&po=1&np=1&fltt=2&invt=2&fid=f26&fs=m:0+f:8,m:1+f:8&fields=f3,f12,f13,f14,f26`;
      const json = await this._eastGet(url);
      for (const item of this._diffArray(json)) {
        // f26：上市日期，形态可能是 "2024-01-15" / 20240115 / 时间戳
        let listDate = null;
        const raw = item.f26;
        if (raw != null && String(raw).trim() !== '') {
          const s = String(raw).trim();
          if (/^\d{13}$/.test(s)) listDate = new Date(parseInt(s));
          else if (/^\d{10}$/.test(s)) listDate = new Date(parseInt(s) * 1000);
          else if (/^\d{8}$/.test(s)) listDate = new Date(+s.slice(0, 4), +s.slice(4, 6) - 1, +s.slice(6, 8));
          else if (/^\d{4}[-/]\d{1,2}[-/]\d{1,2}/.test(s)) listDate = new Date(s.replace(/\//g, '-'));
        }
        let listingDays = null;
        if (listDate && !isNaN(listDate.getTime())) {
          listingDays = Math.floor((Date.now() - listDate.getTime()) / 86400000);
        }
        const m = String(item.f13);
        const prefix = m === '1' ? 'sh' : (m === '0' ? 'sz' : (String(item.f12).startsWith('6') ? 'sh' : 'sz'));
        results.push({
          name: item.f14,
          code: prefix + item.f12,
          pureCode: item.f12,
          change: parseFloat(item.f3),
          listingDate: listDate && !isNaN(listDate.getTime()) ? this.fmtDate(listDate) : '',
          listingDays
        });
      }
    } catch (e) {
      console.debug('新上市股票（东财旧源）获取失败', e);
    }
    const valid = results.filter(r => r.listingDays != null && !isNaN(r.listingDays) && r.listingDays >= 0);
    valid.sort((a, b) => a.listingDays - b.listingDays);
    return valid.slice(0, 50);
  },

  // ============ 连板股票（近 10 个交易日内涨停次数排行） ============
  /**
   * 获取「连板股票」排行：近 10 个交易日内涨停板最多的股票，按涨停次数降序取前 25。
   *
   * 数据源：东财涨停板池（push2ex.eastmoney.com/getTopicZTPool），单次即返回当日全市场涨停股，
   * 每只带 lbc（连板数）、zttj.days/ct（统计窗口天数 / 窗口内涨停次数）、hybk（所属行业）。
   * 交易日为倒序回扫：从今天起最多回扫 14 个自然日凑满 10 个交易日（跳过周末与无数据的节假日；
   * 「无数据」分两种——非交易日返回 tc=0，或当日尚未收盘/尚未开盘导致池子为空，均回扫跳过）。
   *
   * 计算口径（与需求一致）：
   *   统计窗口 = 近 10 个交易日（含当日）；
   *   主排序   = 窗口内涨停次数（zttj.ct 为准，缺失时回退 lbc）降序；
   *   次序     = 连板数（lbc）降序 → 当日涨幅降序 → 行业名 → 代码（保证结果稳定可复现）；
   *   取前 25 只。
   *
   * @returns {Promise<Array<{name,code,pureCode,market,change,boardCount,ztCount,boomCount,days,industry,firstLimitTime}>>}
   *          boardCount=连板数, ztCount=近10交易日涨停次数, boomCount=炸板次数
   */
  async getLimitUpStreak() {
    return this._withCache('ztpool:10d25', API_TTL.SECTOR, () => this._getLimitUpStreakRaw(), v => !!(v && v.length));
  },

  /**
   * 涨停池单日抓取（batch43 提速）：返回 { ok, tc, pool }；ok=false 表示该日无有效数据。
   *
   * 原实现是「先 fetch 直连 → 失败后再 JSONP」的串行兜底。而 push2ex 域名**不返回 CORS 响应头**，
   * 直连 fetch 必被浏览器拦下 —— 于是每个交易日都要白等一次失败往返；再叠加上游 3 次重试退避
   * 与「边缘加速被墙时每次等满 7 秒」，单日最坏十几秒，10 个交易日就是上百秒，
   * 「连板股票」刷新必然超时 → 用户看到「刷新失败（网络/接口限流）」。
   *
   * 现在改为三条路径**并发竞速**，谁先给出有效池子用谁：
   *   ① JSONP —— push2ex 支持 `cb=`，天然不受 CORS 限制，是最可能成功的一条；
   *   ② 直连 fetch —— 若上游将来补上 CORS 头，这条路最快；
   *   ③ 边缘加速 —— 已配置且未熔断时才真正发起（被墙时立即跳过，见 _accelOpen）。
   */
  async _fetchZtPool(dateStr) {
    const url = `https://push2ex.eastmoney.com/getTopicZTPool?ut=7eea3edcaed734bea9cbfc24409ed989&dpt=wz.ztzt&Pageindex=0&pagesize=300&sort=fbt%3Aasc&date=${dateStr}`;
    /** 把各路径的原始回包统一成 { ok, tc, pool }；结构不对返回 null（继续等其他路径） */
    const pick = (json) => {
      const pool = json && json.data && Array.isArray(json.data.pool) ? json.data.pool : null;
      if (!pool) return null;
      const tc = json.data.tc != null ? json.data.tc : pool.length;
      return { ok: pool.length > 0, tc: tc || 0, pool };
    };
    const tasks = [
      this._eastJsonp(url, 8000).then(pick).catch(() => null),
      this._fetchJson(url, 6000).then(pick).catch(() => null),
      this._eastGetViaAccel(url).then(pick).catch(() => null)
    ];
    // 注：非交易日/未开盘会返回 pool:[]，这也是**有效结果**（pick 会给出 ok:false），
    // 竞速到此即结束，不会再空等其他路径，也就不会把「空池」误当成「接口挂了」。
    const r = await this._raceFirstNonNull(tasks);
    return r || { ok: false, tc: 0, pool: [] };
  },

  async _getLimitUpStreakRaw() {
    // ① 生成候选交易日：从今日起最多回看 20 个自然日（跳过周末，不消耗接口请求）
    const cands = [];
    const base = new Date();
    for (let back = 0; back < 20; back++) {
      const d = new Date(base.getTime() - back * 86400000);
      const dow = d.getDay();
      if (dow === 0 || dow === 6) continue;
      cands.push(d.getFullYear().toString()
        + String(d.getMonth() + 1).padStart(2, '0')
        + String(d.getDate()).padStart(2, '0'));
    }

    // ② 并发回扫：4 路并行（原为串行，10 个交易日要等 10 个来回），凑满 10 个有效交易日即收工
    const collected = new Map();   // pureCode -> { i, it }，i 越小日期越新
    const dates = [];
    const CONC = 4;
    let cursor = 0, inflight = 0;
    const worker = async () => {
      for (;;) {
        // 已凑满 10 个（含正在飞的）即收工 —— 把在飞请求也计入，
        // 否则 4 个 worker 会在同一拍都通过检查，实际多抓 3 天（实测 10 → 13 次请求）
        if (dates.length + inflight >= 10) return;
        const i = cursor++;
        if (i >= cands.length) return;
        const s = cands[i];
        inflight++;
        // 单日失败（网络抖动/限流/被 mock 抛错）绝不能中断整轮回扫，跳过该日继续
        let r = null;
        try { r = await this._fetchZtPool(s); }
        catch (e) { console.debug('涨停池单日抓取异常，跳过', s, e && e.message); }
        inflight--;
        if (!r || !r.ok) continue;                 // 非交易日 / 未开盘 → 不计入窗口，继续回扫
        dates.push({ date: s, tc: r.tc });
        for (const it of r.pool) {
          const pure = String(it.c || '').trim();
          if (!pure) continue;
          // 同一只股可能连续多日涨停：只保留**日期最新**的一条
          // （并发抓取下完成顺序不确定，必须按候选序号比较，不能靠「后写覆盖」）
          const prev = collected.get(pure);
          if (!prev || i < prev.i) collected.set(pure, { i: i, it: it });
        }
      }
    };
    await Promise.all(Array.from({ length: CONC }, worker));
    if (!dates.length) return [];

    const rows = [];
    for (const entry of collected.values()) {
      const it = entry.it;
      // zttj.ct = 统计窗口内涨停次数（东财口径为近 N 日，days 即窗口天数）；缺失则回退连板数
      const zttj = it.zttj || {};
      const ct = (zttj.ct != null && !isNaN(Number(zttj.ct))) ? Number(zttj.ct) : null;
      const lbc = (it.lbc != null && !isNaN(Number(it.lbc))) ? Number(it.lbc) : 1;
      const ztCount = ct != null ? ct : lbc;
      const pure = String(it.c || '').trim();
      const m = String(it.m);
      const prefix = m === '1' ? 'sh' : (m === '0' ? 'sz' : (pure.startsWith('6') ? 'sh' : 'sz'));
      rows.push({
        name: it.n || '',
        code: prefix + pure,
        pureCode: pure,
        market: m,
        change: it.zdp != null ? parseFloat(it.zdp) : null,
        boardCount: lbc,                 // 连板数
        ztCount: ztCount,                // 近 10 交易日涨停次数（主排序键）
        boomCount: it.zbc != null ? Number(it.zbc) : 0,   // 炸板次数
        days: zttj.days != null ? Number(zttj.days) : null,
        industry: it.hybk || '',
        firstLimitTime: it.fbt != null ? String(it.fbt) : ''
      });
    }
    // ③ 排序：涨停次数降序 → 连板数降序 → 当日涨幅降序 → 行业 → 代码（稳定）
    rows.sort((a, b) =>
      (b.ztCount - a.ztCount) ||
      (b.boardCount - a.boardCount) ||
      ((b.change || 0) - (a.change || 0)) ||
      String(a.industry).localeCompare(String(b.industry), 'zh') ||
      String(a.code).localeCompare(String(b.code)));
    return rows.slice(0, 25);
  },

  // ============ 同类股票（同主营业务/产品的 A 股公司） ============
  /**
   * 找出 A 股中与「种子股票」主营业务/产品相同的同类公司。
   *
   * 口径与「AI 语义搜索」的营收占比相关度完全一致：
   *   1) 先拉取种子股票（如 sh600519）的主营构成（东财 F10 按产品/按行业）；
   *   2) 取其主营段名作为「产品核心词」匹配词（剔除运营/通用词）；
   *   3) 扫描候选池（种子股票所属行业/概念板块成分股 + 全市场名称命中），逐只拉主营构成；
   *   4) 段名命中核心词的营收占比之和（min(ratio,1) 累加、封顶 100%）即为「相关度」，
   *      同时给出「命中主营业务占比之和」用于排序；
   *   5) 过滤：相关度 < minRatio 阈值的剔除；结果按主营业务占比降序；
   *   6) 行情（现价/涨跌幅/总市值）来自腾讯免费接口。
   *
   * @param {object} opts
   * @param {string} opts.code        种子股票代码（600519 / sh600519 均可）
   * @param {number} [opts.minRatio]  主营占比阈值(%)，低于该值的公司不纳入结果，默认 0
   * @param {string} [opts.sort]      'ratio'（按主营业务占比降序，默认）
   * @param {number} [opts.limit]     候选池上限（控制请求量），默认 200
   * @returns {Promise<object>} { ok, seed:{code,name}, segments:[{name,ratio}], stocks:[...] }
   */
  async getSimilarByBusiness({ code, minRatio = 0, sort = 'ratio', limit = 200 } = {}) {
    const empty = { ok: false, error: '请输入有效的股票代码/名称', seed: null, segments: [], stocks: [] };
    const parsed = this.parseStockInput ? this.parseStockInput(String(code || '')) : [];
    let seedPure = (parsed && parsed.length && parsed[0].code) ? parsed[0].code : '';
    if (!seedPure && parsed && parsed.length && this.resolveStockNames) {
      // 输入的是纯名称：走统一的「名称 → 代码」反查补出代码，让用户不必先查代码
      try { await this.resolveStockNames(parsed.slice(0, 1)); } catch (e) { /* 反查失败就走原来的提示 */ }
      seedPure = (parsed[0] && parsed[0].code) ? parsed[0].code : '';
    }
    const full = seedPure || (this.inferPrefix ? this.inferPrefix(String(code || '')) : String(code || ''));
    if (!full || !/^(sh|sz|bj)\d{4,8}$/i.test(full)) return empty;
    try {
      // 1) 种子股票主营构成
      const seedBiz = await this.getMainBusiness(full);
      if (!seedBiz || !seedBiz.length) {
        return { ok: false, error: `未获取到 ${full.toUpperCase()} 的主营构成（可能刚上市/停牌/数据缺失）`, seed: null, segments: [], stocks: [] };
      }
      // 候选池召回用：全部主营段名（提升广度，便于找回更多潜在同类公司）
      const allCore = [...new Set(
        seedBiz.map(s => String(s.name || '').trim().toLowerCase())
          .map(n => n.replace(/[（(].*?[)）]/g, '').trim())
          .filter(n => n.length >= 2)
      )];
      // 匹配词：仅取「排名前 2 的业务 + 主要产品」（seedBiz 已按营收占比降序，前两段即 top2）
      const coreArr = [...new Set(
        seedBiz.slice(0, 2)
          .map(s => String(s.name || '').trim().toLowerCase())
          .map(n => n.replace(/[（(].*?[)）]/g, '').trim())
          .filter(n => n.length >= 2)
      )];
      if (!coreArr.length) {
        return { ok: false, error: '该股票主营构成前两段无有效产品名，无法匹配同类公司', seed: null, segments: [], stocks: [] };
      }

      // 2) 候选池：种子所属行业/概念板块成分股；再叠加全市场名称含关键词的兜底
      const candidate = new Map();
      const seedInfo = { code: full, name: '' };
      try {
        const qt = await this.getQuote(full);
        if (qt && qt.name) seedInfo.name = qt.name;
      } catch (e) { /* 忽略 */ }

      // 2a) 用主营段名反查板块（东财搜索建议），取成分股作为候选
      const boards = [];
      for (const seg of allCore.slice(0, 8)) {
        try {
          const bs = await this.resolveBoardViaSuggest(seg);
          if (bs && bs.length) bs.slice(0, 2).forEach(b => boards.push({ bk: b.bk || b.code, name: b.name }));
        } catch (e) { /* 忽略 */ }
        if (boards.length >= 12) break;
      }
      // 2b) 行业板块（东财行业归类）也纳入，提升召回
      try {
        const indName = await this.getIndustry(full);   // 返回行业名字符串
        if (indName) {
          const ibs = await this.resolveBoardViaSuggest(indName);
          if (ibs && ibs.length) ibs.slice(0, 2).forEach(b => boards.push({ bk: b.bk || b.code, name: b.name }));
        }
      } catch (e) { /* 忽略 */ }

      const uniqBoards = [...new Map(boards.map(b => [b.bk, b])).values()];
      for (const b of uniqBoards) {
        try {
          const list = await this.getSectorStocksMeta(b.bk, 6);
          for (const s of list) if (!candidate.has(s.code)) candidate.set(s.code, s);
        } catch (e) { /* 忽略 */ }
        if (candidate.size >= limit) break;
      }
      // 2c) 兜底：全量板块名含主营词的成分股（召回有限但能补足）
      if (candidate.size < 40) {
        try {
          const all = await this.getAllSectors();
          const extra = all.filter(x => allCore.some(k => x.name.toLowerCase().includes(k))).slice(0, 6);
          for (const b of extra) {
            try {
              const list = await this.getSectorStocksMeta(b.bk, 4);
              for (const s of list) if (!candidate.has(s.code)) candidate.set(s.code, s);
            } catch (e) { /* 忽略 */ }
          }
        } catch (e) { /* 忽略 */ }
      }
      // 种子本身也纳入（便于展示基准）
      candidate.set(full, { code: full, name: seedInfo.name || full });

      let codes = [...candidate.keys()].slice(0, limit);

      // 3) 逐只拉主营构成，按收入占比相关度打分
      const scored = await mapLimit(codes, 6, async (c) => {
        const info = candidate.get(c) || { code: c, name: c };
        let mb = null;
        try { mb = await this.getMainBusiness(c); } catch (e) { mb = null; }
        if (!mb || !mb.length) return null;
        // 与语义搜索同口径：段名必含核心词，命中段营收占比之和 = 相关度
        const { relevance, matched } = revenueRelevance(mb, coreArr, []);
        if (!matched.length) return null;
        return { info, relevance, matched };
      });

      // 4) 过滤阈值 + 归一
      const threshold = Number(minRatio) || 0;
      // 过滤：去除 301/300 开头、北交所(8/4/92 开头或 bj 前缀)、ST（名称以 ST/*ST 开头）
      const isExcluded = (code, name) => {
        const pure = String(code || '').replace(/^(sh|sz|bj)/i, '');
        const digits = /^\d{4,8}$/.test(pure) ? pure : String(code || '');
        if (/^30[01]/.test(digits)) return true;        // 去除 301 / 300 开头（创业板）
        if (/^(8|4|92)/.test(digits)) return true;       // 去除北交所
        const nm = String(name || '').toUpperCase();
        if (/^(\*?ST)/.test(nm)) return true;            // 去除 ST / *ST
        return false;
      };
      const passed = (scored || []).filter(x => {
        if (!x || x.relevance <= 0 || x.relevance < threshold) return false;
        if (isExcluded(x.info.code, x.info.name)) return false;
        return true;
      });
      const codes2 = passed.map(x => x.info.code);
      let quotes = {};
      try { quotes = await this.getQuotes(codes2); } catch (e) { quotes = {}; }
      let stocks = passed.map(x => {
        const q = quotes[x.info.code] || {};
        const mkt = q.totalMarketCap != null ? q.totalMarketCap : (x.info.marketCap || null);
        return {
          code: x.info.code,
          name: q.name || x.info.name || x.info.code,
          price: q.price != null ? q.price : null,
          changePercent: q.changePercent != null ? q.changePercent : null,
          marketCap: mkt,
          relevance: x.relevance,                       // 相关度（命中主营占比之和 %，与 AI 语义同口径）
          bizRatio: x.relevance,                        // 主营业务占比排序值
          matchedSegments: x.matched || [],
          hitBusiness: (x.matched || []).map(m => m.name + ' ' + m.ratio + '%').join(' · ')
        };
      });
      // 排序：默认按主营业务占比降序
      if (sort === 'ratio') stocks.sort((a, b) => (b.bizRatio || 0) - (a.bizRatio || 0));
      else stocks.sort((a, b) => (b.relevance || 0) - (a.relevance || 0));

      return { ok: true, seed: seedInfo, segments: seedBiz, stocks };
    } catch (e) {
      return { ok: false, error: '同类股票计算失败：' + (e && e.message ? e.message : e), seed: null, segments: [], stocks: [] };
    }
  },

  // ============ 概念/行业板块选股 ============

  /**
   * 东财接口多节点轮询：单个节点对连续请求限流敏感，
   * 通过多个同源数据节点（push2 / push2delay / push2his 等）轮询降级，
   * 任一节点成功即返回，全部失败返回 null。全程免费（东财公开接口）。
   * @param {string} url 完整 url，host 会被自动替换到各节点
   */
  async _eastFetch(url) {
    // 多节点列表：优先主节点，其次延迟节点（独立服务器，通常不同时被限流）
    const hosts = [
      'push2.eastmoney.com',
      'push2delay.eastmoney.com',
      'push2his.eastmoney.com'
    ];
    let u;
    try { u = new URL(url); } catch (e) { return null; }
    // 打乱节点顺序的起始偏移，避免多用户同时命中同一节点
    const start = Math.floor(Math.random() * hosts.length);
    // 1) 各节点尝试「简单」fetch：
    //    注意不要携带任何自定义请求头（如 User-Agent）——自定义头会把请求变成
    //    「非简单请求」，浏览器会先发 CORS 预检 OPTIONS，而东财不支持预检，
    //    导致请求直接失败。这也是此前「获取失败（网络限制）」的主要诱因之一。
    for (let h = 0; h < hosts.length; h++) {
      u.hostname = hosts[(start + h) % hosts.length];
      try {
        const resp = await fetch(u.href, { cache: 'no-store' });
        if (resp.ok) {
          const json = await resp.json();
          if (json && json.data !== undefined) return json;
        }
      } catch (e) { /* 切下一个节点 */ }
      await new Promise(r => setTimeout(r, 250));
    }
    // 2) 全部失败 → JSONP 兜底（<script> 注入，绕过 CORS 预检与响应头限制）
    u.hostname = hosts[0];
    try {
      const json = await this._eastJsonp(u.href, 6000);
      if (json && json.data !== undefined) return json;
    } catch (e) { /* 忽略，返回 null */ }
    return null;
  },

  /**
   * 分页拉取某类板块列表（概念 m:90+t:3 / 行业 m:90+t:2）
   * 东财单页上限 100 条。因 _eastFetch 已多节点轮询降级，
   * 此处保持合理页间间隔避免过度请求，支持加载完整板块列表。
   * @param {string} fs 板块筛选条件
   * @param {number} maxPages 最多加载几页，默认 6（概念约 6 页、行业约 5 页）
   * @returns {Array<{bk, name, change}>}
   */
  async _loadSectors(fs, maxPages = 6) {
    const all = [];
    for (let pn = 1; pn <= maxPages; pn++) {
      const url = `https://push2.eastmoney.com/api/qt/clist/get?pn=${pn}&pz=100&po=1&np=1&fltt=2&invt=2&fid=f3&fs=${encodeURIComponent(fs)}&fields=f12,f14,f3`;
      const json = await this._eastFetch(url);
      const diff = this._diffArray(json);
      all.push(...diff);
      const total = json && json.data && json.data.total;
      if (!diff.length || all.length >= total) break;
      // 页间等待，降低单节点请求频率
      await new Promise(r => setTimeout(r, 500));
    }
    return all.map(b => ({ bk: b.f12, name: b.f14, change: b.f3 != null ? parseFloat(b.f3) : null }));
  },

  /** 板块缓存（避免重复加载） */
  _sectorCache: null,
  /** 板块缓存过期时间戳 */
  _sectorCacheAt: 0,

  /**
   * 获取板块列表（概念+行业+指数，去重）。
   *
   * 🔴 batch44 换源：主源由「东财 push2 分页」改为「**新浪静态快照**」。
   *   原因：push2 是动态查询接口，浏览器侧**会间歇性限流**（实测同一 URL 连测 5 次有通有不通），
   *   一旦限流，选股板块的**所有搜索全部失效**（提示「板块数据加载失败（可能是网络或行情源限流）」）；
   *   且旧实现要分 3 类 × 6 页 = 18 次请求，本身也更容易触发限流。
   *   新浪 newSinaHy.php / newFLJK.php 是定时刷新的**静态快照文件**（命中 CDN），
   *   用 <script> 直载、免 CORS、**一次拿全量**（约 49 行业 + 175 概念），请求数降一个数量级。
   *   东财降级为「后台异步补充」，成功则合并（补上指数板块等），失败/限流静默跳过、绝不阻塞搜索。
   *
   * 🔴 batch51：loadAll（「📚 加载全部板块」）时另并入**东财板块全量库**（1031 个，报表通道聚合，
   *   缓存 3 天），补足新浪未收录的板块；两者用不同缓存键，避免「先加载过 224 个」把全量请求短路掉。
   *
   * 结果缓存 2 小时避免重复请求。
   * @param {boolean} loadAll true 时额外并入东财全量板块库（19 页一次性拉取，仅在用户显式要求时）
   * @returns {Promise<Array<{bk, name, type, change}>>} type: '概念'|'行业'|'指数'
   */
  async getAllSectors(loadAll = false) {
    // 复用既有 _sectorCache（2 小时，覆盖在 _getAllSectorsRaw 内），外层再加并发去重，
    // 避免多个面板同时挂载时并发触发板块请求。
    // 两种模式用不同缓存键：loadAll 的结果里含东财全量库，不能被只含新浪的旧缓存顶掉。
    return this._withCache(loadAll ? 'sectors:allFull' : 'sectors:all', 2 * 60 * 60 * 1000,
      () => this._getAllSectorsRaw(loadAll), v => !!(v && v.length));
  },

  async _getAllSectorsRaw(loadAll = false) {
    const now = Date.now();
    const cacheTtl = 2 * 60 * 60 * 1000; // 2 小时
    // loadAll 需要并入东财全量库，因此只含新浪的旧缓存不能短路它（_withEast 标记是否已并入）
    if (this._sectorCache && this._sectorCache._full >= 1 && now - this._sectorCacheAt < cacheTtl
        && (!loadAll || this._sectorCache._withEast)) {
      return this._sectorCache.data;
    }

    const all = [];
    const seen = new Set();
    const pushSector = (s, type) => {
      const bk = String((s && s.bk) || '');
      if (!bk || seen.has(bk)) return;
      seen.add(bk);
      all.push({
        bk, name: s.name, type,
        change: s.change != null ? s.change : null,
        stockCount: s.stockCount || 0
      });
    };

    // ===== ① 主源：新浪静态快照（免费、不限流、<script> 直载、一次拿全量）=====
    let sinaFail = false;
    try {
      const { industries, concepts } = await this._sinaAllSectors();
      // 概念优先（搜索场景以概念为主），行业其次
      concepts.forEach(s => pushSector(s, '概念'));
      industries.forEach(s => pushSector(s, '行业'));
    } catch (e) {
      sinaFail = true;
      console.debug('[stock-api] 新浪板块快照加载失败', e && e.message);
    }

    // 写缓存（新浪结果**立即可用**，不等东财；缓存按引用持有 all，后台补充会自动并入）
    this._sectorCache = { data: all, _full: 1, _withEast: false };
    this._sectorCacheAt = now;

    // ===== ② 兜底/增强：东财 push2（免费公开但偶发限流）=====
    if (sinaFail || all.length < 50) {
      // 新浪不可用或结果过少：**同步**等东财（此时没有更稳的源，只能等）
      try {
        const east = await this._loadEastAllSectors();
        east.forEach(s => pushSector(s, s.type));
      } catch (e) { /* 两源都不可用 → 返回已有内容（可能为空，由调用方提示） */ }
    } else {
      // 新浪可用：东财改为**后台异步补充**，绝不阻塞搜索（成功则把指数板块等并入同一数组）
      this._enrichSectorsFromEast(all, seen);
    }

    // ===== ③ batch51：东财板块全量库（1031 个，报表通道聚合，缓存 3 天）=====
    //  仅在 loadAll（「📚 加载全部板块」）时同步并入：它是 19 页 / 约 12MB 的一次性拉取，
    //  不适合每次搜索都做。日常搜索由「本地 946 词典 + 新浪 224」覆盖，零额外流量。
    //  这一步补足新浪命名体系里没有的板块（新能源车 / 算力 / 低空经济 / 半导体…）。
    if (loadAll) {
      try {
        const boards = await this._dcAllBoards();
        if (boards.length) {
          const industryNames = new Set(all.filter(s => s.type === '行业').map(s => s.name));
          for (const b of boards) {
            if (!b.bk || seen.has(b.bk)) continue;
            seen.add(b.bk);
            all.push({
              bk: b.bk, name: b.name,
              type: this._boardTypeOf(b.name, industryNames),
              change: null, stockCount: b.count || 0
            });
          }
          this._sectorCache._withEast = true;
        }
      } catch (e) { /* 拉不到就维持新浪结果，不影响任何现有功能 */ }
    }

    return all;
  },

  /**
   * 拉取东财全量板块（概念 m:90+t:3 / 行业 m:90+t:2 / 指数 m:90+t:5）。
   * 三类**并发**请求，各自失败不互相影响，缩短总耗时。
   * @returns {Promise<Array<{bk,name,change,type}>>}
   */
  async _loadEastAllSectors() {
    const groups = [['m:90+t:3', '概念'], ['m:90+t:2', '行业'], ['m:90+t:5', '指数']];
    const maxPg = 6; // 概念约6页、行业约5页、指数约6页，足够覆盖全部板块
    const result = await Promise.all(groups.map(async ([fs, type]) => {
      try {
        const list = await this._loadSectors(fs, maxPg);
        return list.map(s => ({ ...s, type }));
      } catch (e) {
        console.debug('[stock-api] 东财' + type + '板块加载失败', e && e.message);
        return [];
      }
    }));
    return result.reduce((acc, cur) => acc.concat(cur), []);
  },

  /**
   * 东财板块**后台异步增强**：把东财独有的板块（指数板块、新浪未收录的概念）合并进 `all`。
   * 东财限流/失败时静默跳过——这是「东财挂了也不影响搜索」的关键。
   * 合并的是同一个数组引用，因此 `_sectorCache.data` 与已返回给调用方的数组都会同步看到新板块。
   */
  _eastEnrichPromise: null,
  _enrichSectorsFromEast(all, seen) {
    this._eastEnrichPromise = (this._eastEnrichPromise || Promise.resolve()).then(async () => {
      try {
        const east = await this._loadEastAllSectors();
        let added = 0;
        for (const s of east) {
          const bk = String((s && s.bk) || '');
          if (!bk || seen.has(bk)) continue;
          seen.add(bk);
          all.push({ bk, name: s.name, type: s.type, change: s.change != null ? s.change : null });
          added++;
        }
        if (added) console.debug('[stock-api] 东财板块后台补充 ' + added + ' 个（未阻塞搜索）');
      } catch (e) { /* 静默：东财不可用不影响新浪结果 */ }
    }).then(() => {}, () => {});
    return this._eastEnrichPromise;
  },


  /**
   * 按关键词搜索板块（本地过滤，中文匹配名称）
   * @param {string} keyword
   * @returns {Promise<Array<{bk, name, type, change}>>}
   */
  /**
   * 归一化板块代码：东财返回的板块代码可能带 secid 前缀
   * （如指数 "1.000097"、概念 "90.BK1303"），成分股查询 fs=b:<code>
   * 统一用冒号后的纯代码，避免 "1.000097" 这类带前缀代码查不到成分股。
   */
  _normalizeBoardCode(bk) {
    if (!bk) return bk;
    const s = String(bk);
    if (s.indexOf('.') >= 0) return s.split('.').pop();
    return s;
  },

  /**
   * 归一化**股票**代码为带市场前缀的小写格式（'600519' / 'sh600519' / '600519.SH' 均可）。
   * 语义搜索的候选池来自数据中心报表（SECUCODE 形式），而行情接口要 sh/sz/bj 前缀，
   * 统一在这里转换，避免后续每一处各自判断市场。
   * @returns {string} 'sh600519'，非法输入返回 ''
   */
  _normalizeCode(code) {
    const s = String(code || '').trim();
    if (!s) return '';
    const m = s.match(/^(\d{6})\.(SH|SZ|BJ)$/i);
    if (m) return m[2].toLowerCase() + m[1];
    const c = this.inferPrefix(s);
    return /^(sh|sz|bj)\d{6}$/.test(c) ? c : '';
  },

  // 东财「搜索建议」熔断器（batch44）
  // 🔴 实测背景：searchapi.eastmoney.com 该接口**已失效**（fetch 与 JSONP 均失败），
  //    而原实现每次搜索都 await 它、超时 9 秒 —— 用户搜一次要转 9 秒才出结果，
  //    是「选股板块所有搜索都用不了」的**直接主因**（比板块列表限流更致命）。
  // 方案：缩短超时到 2.5s + 连续失败即熔断 5 分钟，期间直接跳过（零开销）；
  //       且 searchSectors 只在「本地无命中」时才调用它，本地命中时搜索是纯本地的、零网络。
  _suggestBreaker: { fails: 0, openUntil: 0 },
  SUGGEST_FAIL_THRESHOLD: 2,
  SUGGEST_COOLDOWN: 5 * 60 * 1000,
  SUGGEST_TIMEOUT: 2500,

  /** 搜索建议链路当前是否处于熔断（应直接跳过） */
  _suggestOpen() {
    return Date.now() < (this._suggestBreaker && this._suggestBreaker.openUntil || 0);
  },
  /** 记录一次搜索建议失败，达阈值则打开熔断 */
  _suggestMarkFail() {
    const b = this._suggestBreaker;
    b.fails = (b.fails || 0) + 1;
    if (b.fails >= this.SUGGEST_FAIL_THRESHOLD) b.openUntil = Date.now() + this.SUGGEST_COOLDOWN;
  },
  /** 搜索建议链路恢复可用 */
  _suggestMarkOk() {
    this._suggestBreaker = { fails: 0, openUntil: 0 };
  },

  /**
   * 通过东财「搜索建议」API 直接解析关键词→板块（JSONP，绕过浏览器 CORS）。
   * 该接口覆盖概念/行业/指数（含「高端装备」「人工智能」这类平时归类在指数下的板块）。
   *
   * ⚠️ batch44 起：该接口**实测已失效**（2026-09-22 线上同源实测 fetch 与 JSONP 均 FAILED）。
   *    因此它只作为「本地全量无命中」时的可选补充，并带熔断保护；
   *    选股板块搜索的主路径已改为「新浪全量板块 + 本地过滤」，不再依赖本接口。
   * @returns {Promise<Array<{bk,code,name,type,secid,change}>>}
   */
  async resolveBoardViaSuggest(keyword) {
    const kw = (keyword || '').trim();
    if (!kw) return [];
    if (this._suggestOpen()) return [];          // 熔断中：立即跳过，不再白等超时
    const token = 'D43BF7224A6D6F3AEA560038B6A1D52C';
    const url = `https://searchapi.eastmoney.com/api/suggest/get?input=${encodeURIComponent(kw)}&type=14&token=${token}`;
    try {
      const j = await this._eastJsonp(url, this.SUGGEST_TIMEOUT);
      const table = j && j.QuotationCodeTable;
      if (!table) throw new Error('suggest: payload 结构不符（接口可能已下线）');
      this._suggestMarkOk();
      const arr = table.Data || [];
      const out = [];
      for (const x of arr) {
        const cls = x.Classify;
        const st = String(x.SecurityType);
        // 仅保留板块类：BK(概念/行业) / Index(板块指数) / 中证指数(24)
        const isBoard = cls === 'BK' || cls === 'Index' || cls === '24' ||
                        st === '9' || st === '5' || st === '11' || st === '2' || st === '3';
        if (!isBoard) continue;
        let type = '概念';
        if (st === '5' || cls === 'Index') type = '指数';
        else if (st === '11' || cls === '24') type = '指数';
        else if (st === '2' || st === '3') type = '行业';
        out.push({ bk: x.Code, code: x.Code, name: x.Name, type, secid: x.QuoteID, change: null });
      }
      return out;
    } catch (e) {
      this._suggestMarkFail();
      console.debug('[stock-api] 搜索建议不可用（已熔断，回退本地过滤）', e && e.message);
      return [];
    }
  },

  /**
   * 按关键词搜索板块（本地全量过滤 + 东财板块词典 + 东财搜索建议兜底）。
   *
   * 🔴 batch44 行为调整（性能关键）：
   *   - 板块全量已由**新浪静态快照**提供（约 224 个概念/行业，本地即可精确分类），
   *     因此**本地命中时直接返回，完全不发网络请求** → 搜索瞬间完成。
   *   - 东财搜索建议（实测已失效）只在「本地零命中」时才试一次，且带熔断，
   *     不再让每次搜索都白等 9 秒。
   *
   * 🔴 batch51 补漏（这是「选股页输入『新能源车』没有成分股」的根因）：
   *   新浪板块库只有 **224 个**且命名体系与东财**完全不同** —— 里面没有「新能源车」，
   *   只有笼统的「新能源」；「算力」「低空经济」「半导体」更是完全没有。
   *   只按「新浪名 includes 关键词」过滤，这类词必然 0 命中，再落到已下线的搜索建议接口 → 最终 0 结果。
   *   因此这里**并入东财板块词典**（本地 946 个，零网络）+ 已缓存的东财全量库（1031 个）：
   *     · 命中词典 → 零额外网络，结果立即可用（「新能源车」→ BK0900）；
   *     · 都没命中 → 才拉一次东财全量库（19 页 / 一次，聚合结果缓存 3 天）。
   *   东财条目的 type 由 _boardTypeOf 推断，避免落进 UI 三个分组的死角而不显示。
   * @param {string} keyword
   * @returns {Promise<Array<{bk,code,name,type,secid,change}>>}
   */
  async searchSectors(keyword) {
    const kw = (keyword || '').trim().toLowerCase();
    if (!kw) return [];
    // 1) 本地过滤（新浪全量的概念/行业/指数列表，含正确 行业/概念 分类）
    const all = await this.getAllSectors();
    const local = all.filter(s => s.name.toLowerCase().includes(kw)).map(s => ({ ...s, code: s.bk }));
    const localNames = new Set(local.map(s => s.name));
    const industryNames = new Set(all.filter(s => s.type === '行业').map(s => s.name));

    // 1b) 🔴 batch51：并入东财板块词典（本地 946，零网络）。新浪库里已有的同名板块不重复列出。
    const eastHits = this._eastBoardHitsFor(kw, industryNames, localNames);

    // 2) 东财搜索建议：**仅当本地零命中**时才试（避免为「补充」白等网络往返）；
    //    熔断中直接跳过。本地全量已覆盖主要概念/行业，绝大多数搜索走不到这里。
    let suggest = [];
    if (!local.length && !eastHits.length) {
      try { suggest = await this.resolveBoardViaSuggest(keyword); } catch (e) { /* 忽略 */ }
    }
    // 2b) 仍零命中 → 拉一次「东财板块全量库」（19 页，聚合结果缓存 3 天）再匹配一次，
    //     保证词典未收录的新板块也能搜到。日常搜索走词典，零额外流量。
    if (!local.length && !eastHits.length && !suggest.length) {
      try {
        const full = await this._dcAllBoards();
        if (full.length) {
          for (const b of this._matchBoardList(full, kw, 30)) {
            if (localNames.has(b.name)) continue;
            eastHits.push({
              bk: b.code, code: b.code, name: b.name,
              type: this._boardTypeOf(b.name, industryNames), change: null, fromEast: true
            });
          }
        }
      } catch (e) { /* 拉不到就维持 0 结果，不影响其它路径 */ }
    }

    // 合并去重（以归一化代码为准，同名板块以新浪版优先 —— 它带准确的 行业/概念 分类与实时涨跌幅）
    const seen = new Set();
    const seenName = new Set();
    const merge = [];
    const pushItem = (it) => {
      const key = this._normalizeBoardCode(it.bk || it.code || '');
      const nm = String(it.name || '').trim();
      if (!key || seen.has(key)) return;
      if (nm && seenName.has(nm)) return;
      seen.add(key);
      if (nm) seenName.add(nm);
      merge.push({
        bk: it.bk || it.code, code: it.bk || it.code, name: it.name, type: it.type,
        secid: it.secid, change: it.change != null ? it.change : null, fromEast: !!it.fromEast
      });
    };
    local.forEach(pushItem);
    eastHits.forEach(pushItem);
    suggest.forEach(pushItem);
    // 排序：完全同名 > 以关键词开头 > 仅包含关键词；同档新浪已有板块优先（分类与成分股链路已验证），
    //       最后按名称长度（更精确者优先）。
    merge.sort((a, b) => {
      const an = a.name.toLowerCase(), bn = b.name.toLowerCase();
      const as = an === kw ? 3 : (an.startsWith(kw) ? 2 : 1);
      const bs = bn === kw ? 3 : (bn.startsWith(kw) ? 2 : 1);
      if (as !== bs) return bs - as;
      const af = a.fromEast ? 1 : 0, bf = b.fromEast ? 1 : 0;
      if (af !== bf) return af - bf;
      return an.length - bn.length;
    });
    return merge.slice(0, 30);
  },

  /**
   * 把关键词匹配到「东财板块词典 + 已缓存全量库」，转成 searchSectors 的结果项形状。
   * @param {string} kw 已小写化的关键词
   * @param {Set<string>} industryNames 已知行业名（用于推断 type）
   * @param {Set<string>} skipNames 需要跳过的名称（新浪库已返回的同名板块）
   */
  _eastBoardHitsFor(kw, industryNames, skipNames) {
    const out = [];
    for (const b of this._matchBoardList(this._eastBoardsForSearch(), kw, 30)) {
      if (skipNames && skipNames.has(b.name)) continue;
      out.push({
        bk: b.code, code: b.code, name: b.name,
        type: this._boardTypeOf(b.name, industryNames), change: null, fromEast: true
      });
    }
    return out;
  },

  // ==================================================================
  //  板块成分股「多源容错」链路（batch53）
  // ==================================================================
  //
  // 为什么重做（实测定位，2026-09-23）：
  //   旧实现的最后一档兜底是**东财 push2**（`clist/get?fs=b:<code>`）。实测它有两个致命问题：
  //     ① **会限流**，并且在浏览器侧已直接 `Failed to fetch`（同源实测 fetch 返回
  //        "Failed to fetch"，连 HTTP 状态都没有）—— 这正是用户要「换掉东财这种有限制接口」的原因；
  //     ② 它是**唯一**处理「既不是新浪板块、也不是 6 位指数、也不是 BKxxxx」的代码的分支，
  //        而「交集筛选」生成的板块代码恰好是 `INTERSECT_<时间戳>` → 必然落到这里 → 必然返回 0 →
  //        用户看到「未获取到该板块成分股」。
  //
  // 新链路（**已彻底移除 push2**，只保留不限流/免第三方的来源）：
  //   0) `INTERSECT_*` 虚拟板块 → 立即短路（无公开接口，由上层复用已保存的成分股 / 重算交集）
  //   1) 新浪板块（gn_/new_）→ 新浪成分股接口（`<script>` 直载，天然无 CORS 限制）
  //   2) 6 位指数 → 东财数据中心「指数成分」报表
  //   3) 东财 BK 板块 → 东财数据中心「板块成分」报表（一次拿全，**不限流**，与 push2 是两套链路）
  //   4) **本站 CDN 静态快照**（`data/board-members.json`）→ 零第三方 API、零限流、零配额，
  //      随站点发布、被 CDN 边缘缓存 —— 这是「能承载一万用户」的那条免费链路
  //   5) **新浪按板块名**兜底（`Market_Center.getHQNodeData`，非东财 / 免费 / CORS 开放 / 不限流）
  //
  // 每一档都会把结果记进 `_sectorDiag`，由 `lastSectorDiag()` 给出**精确诊断**，
  // 不再让用户只看到一句无信息量的「未获取到该板块成分股」。

  BOARD_SNAPSHOT_URL: 'data/board-members.json',
  BOARD_SNAPSHOT_RETRY: 5 * 60 * 1000,   // 快照拉取失败后的静默期（避免反复 404 噪声）
  _boardSnap: null,
  _boardSnapAt: 0,
  _boardSnapPromise: null,
  _boardSnapFailedAt: 0,
  _boardSnapStats: null,                 // { boards, members } 便于自检/展示
  _sectorDiag: null,                     // 最近一次板块成分股取数的逐源诊断

  /** 交集筛选产生的虚拟板块代码（前端生成，没有对应公开接口） */
  _isVirtualBoard(bk) {
    return /^INTERSECT_/i.test(String(bk || ''));
  },

  /** 对外：该板块代码是否为「交集筛选虚拟板块」（供 UI 给出准确提示） */
  isVirtualBoard(bk) {
    return this._isVirtualBoard(bk);
  },

  /**
   * 载入本站 CDN 上的「板块 → 成分股」静态快照（零第三方 API）。
   * 一次拉取后常驻内存（站点每次发版数据都会更新，页面刷新即重新取）。
   * 失败进入 5 分钟静默期：既避免反复 404 噪声，也不影响报表主路径。
   * @returns {Promise<{v:number,t:number,boards:Object}|null>}
   */
  async _loadBoardSnapshot() {
    if (this._boardSnap) return this._boardSnap;
    if (this._boardSnapPromise) return this._boardSnapPromise;          // 并发收敛
    if (Date.now() - this._boardSnapFailedAt < this.BOARD_SNAPSHOT_RETRY) return null;
    this._boardSnapPromise = (async () => {
      try {
        const r = await fetch(this.BOARD_SNAPSHOT_URL, { cache: 'force-cache' });
        if (!r.ok) throw new Error('HTTP ' + r.status);
        const j = await r.json();
        if (!j || !j.boards || typeof j.boards !== 'object') throw new Error('payload 结构不符');
        this._boardSnap = j;
        this._boardSnapAt = Date.now();
        let members = 0;
        for (const k of Object.keys(j.boards)) members += String(j.boards[k][1] || '').split(',').filter(Boolean).length;
        this._boardSnapStats = { boards: Object.keys(j.boards).length, members };
        return j;
      } catch (e) {
        this._boardSnapFailedAt = Date.now();
        console.debug('[stock-api] 板块静态快照不可用：', e && e.message);
        return null;
      } finally { this._boardSnapPromise = null; }
    })();
    return this._boardSnapPromise;
  },

  /**
   * 从静态快照取成分股。**按板块代码（BKxxxx）精确命中**；代码未命中时再用**板块名**兜底。
   * @param {string} code 归一化后的板块代码（BKxxxx）
   * @param {string} [name] 板块名（可选，用于代码未命中时按名匹配）
   * @returns {Promise<Array<{code,name,pureCode}>>} code 为带市场前缀格式；未命中返回 []
   */
  async _snapshotBoardStocks(code, name) {
    const snap = await this._loadBoardSnapshot();
    if (!snap) return [];
    let entry = snap.boards[String(code || '').toUpperCase()];
    if (!entry && name) {
      const want = String(name).trim();
      for (const k of Object.keys(snap.boards)) {
        if (String(snap.boards[k][0] || '').trim() === want) { entry = snap.boards[k]; break; }
      }
    }
    if (!entry) return [];
    const codes = String(entry[1] || '').split(',').filter(Boolean);
    const out = [];
    for (const pure of codes) {
      // 注意：inferPrefix 返回的是**带前缀的完整代码**（'sh600030'），不是纯前缀 ——
      // 早期误写成 `pre + pure` 会得到 'sh600030600030'，导致快照档的代码全部非法、
      // 腾讯行情查不到、表格只剩下代码没有名称。（batch53 单测 A4 抓到的真实 bug）
      const full = this.inferPrefix(pure);
      if (!/^(sh|sz|bj)\d{6}$/.test(full)) continue;
      // 名称留空，由 _attachQuotes 用腾讯行情补齐（拿不到时回退纯代码）——
      // 绝不能拿 entry[0]（那是**板块名**，如「证券Ⅱ」），否则整个板块的成员都会显示成板块名。
      out.push({ code: full, name: '', pureCode: pure });
    }
    return out;
  },

  /**
   * 用**新浪**「板块节点」接口按板块名取成分股（非东财 / 免费 / CORS 开放 / 不限流）。
   * 做法：把板块名与已缓存的**新浪全量板块库**做**完全同名**匹配 → 拿到新浪节点码（gn_/new_）
   *       → 复用已有的 `_sinaSectorStocks` 分页取全。
   * 只做精确同名匹配：模糊匹配会把「证券Ⅱ」这类东财专名错配到含义不同的新浪板块上，
   * 宁可返回空、由上一档的静态快照负责，也不给用户错数据。
   * @param {string} name 板块名（东财口径）
   * @param {number} [maxPages] 最多翻页
   */
  async _sinaStocksByBoardName(name, maxPages = 20) {
    const want = String(name || '').trim();
    if (!want) return [];
    let node = '';
    try {
      const all = await this.getAllSectors();
      const hit = (all || []).find(s => String(s.name || '').trim() === want && this._isSinaBoard(s.bk));
      if (hit) node = hit.bk;
    } catch (e) { /* 板块库拿不到 → 本档放弃 */ }
    if (!node) return [];
    try {
      return (await this._sinaSectorStocks(node, maxPages)) || [];
    } catch (e) { return []; }
  },

  /**
   * 最近一次板块成分股取数的**逐源诊断**（给用户看的一句话）。
   * 例：「BLOCK 报表 49 只（东财数据中心）；已用该源」/「全部来源均未取到：报表 超时；快照 HTTP 404；新浪 无同名板块」
   * @returns {string}
   */
  lastSectorDiag() {
    const d = this._sectorDiag;
    if (!d) return '';
    return `${d.bk}${d.name ? '「' + d.name + '」' : ''} → ` + d.tried.map(t => `${t.src} ${t.note}`).join('；');
  },

  /**
   * 获取某板块的全部成分股（多源容错；见上方链路说明）
   * @param {string} bk 板块代码，如 BK0896 / gn_gf / 000097 / INTERSECT_xxx
   * @param {string} [name] 板块名（可选；仅用于末档「按名兜底」，提升命中率）
   * @returns {Promise<Array<{code, name, price, changePercent}>>} code 为带前缀格式
   */
  async getSectorStocks(bk, name) {
    const _bk = this._normalizeBoardCode(bk);
    return this._withCache('ss:' + _bk, API_TTL.SECTOR,
      () => this._getSectorStocksRaw(_bk, name), v => !!(v && v.length));
  },

  /**
   * 给「只有代码 + 名称」的板块成分股补上现价/涨跌幅/总市值。
   * 东财数据中心报表（BOARDTYPE）只给成分股名单、不含量价，而勾选弹窗与字段表要有涨跌幅列，
   * 因此用**腾讯批量行情**补齐整版（getQuotes 内部已按 QUOTE_CHUNK=200 切片并发，
   * 所以这里可以直接把整个板块传进去，不受腾讯单次 URL 长度上限影响）。
   * 行情拿不到时保持 null，由表格显示「—」，绝不因为行情失败丢掉成分股本身。
   * @param {Array<{code:string,name?:string}>} list
   * @returns {Promise<Array<{code,name,price,changePercent,marketCap}>>}
   */
  async _attachQuotes(list) {
    const out = (list || []).map(s => ({
      code: s.code, name: s.name || s.pureCode || '',
      price: null, changePercent: null, marketCap: null
    }));
    if (!out.length) return out;
    let quotes = {};
    try { quotes = await this.getQuotes(out.map(s => s.code).filter(Boolean)); } catch (e) { quotes = {}; }
    for (const s of out) {
      const q = quotes[s.code];
      if (!q) continue;
      if (!s.name && q.name) s.name = q.name;
      if (q.price != null) s.price = q.price;
      if (q.changePercent != null) s.changePercent = q.changePercent;
      if (q.totalMarketCap != null) s.marketCap = q.totalMarketCap * 1e8;
    }
    return out;
  },

  /**
   * 板块成分股取数的**多源容错实现**（batch53 重写；push2 已彻底移除）。
   * 逐档尝试并记录诊断，任一滴返回非空即用；全部落空返回 []（诊断留在 `_sectorDiag`）。
   */
  async _getSectorStocksRaw(bk, name) {
    const code = this._normalizeBoardCode(bk);
    const tried = [];
    this._sectorDiag = { bk: code, name: name || '', tried };

    // 0) 交集筛选生成的虚拟板块：没有对应公开接口，立即短路。
    //    （上层会复用已保存的成分股 / 用源板块重新计算交集，见 app.js loadSectorStocks）
    if (this._isVirtualBoard(code)) {
      tried.push({ src: '交集板块', note: '虚拟代码，无对应接口（请用源板块重算）' });
      return [];
    }

    // 1) 新浪板块（行业 new_xxxx / 概念 gn_xxxx）：新浪成分股接口（<script> 直载，天然无 CORS 限制）
    if (this._isSinaBoard(code)) {
      try {
        const list = await this._sinaSectorStocks(code);
        tried.push({ src: '新浪', note: list.length ? `${list.length} 只` : '0 只' });
        if (list.length) return list;
      } catch (e) { tried.push({ src: '新浪', note: '异常 ' + (e && e.message || e) }); }
    }

    // 2) 指数板块（6 位数字）：东财数据中心「指数成分」报表
    if (this._isIndexBoard(code)) {
      try {
        const cs = await this._getIndexConstituents(code);
        tried.push({ src: '指数报表', note: cs.length ? `${cs.length} 只` : '0 只' });
        if (cs.length) {
          return cs.map(s => ({ code: s.code, name: s.name, price: s.price, changePercent: s.changePercent }));
        }
      } catch (e) { tried.push({ src: '指数报表', note: '异常 ' + (e && e.message || e) }); }
    }

    // 3) 东财 BK 板块：数据中心「板块成分」报表（BOARDTYPE，一次拿全 719 只这种量级）。
    //    实测该通道 200 + CORS + **不限流**，与 push2 是两套完全不同的链路；1 次请求 + 1 次批量行情。
    if (/^BK\d+$/i.test(code)) {
      try {
        const dc = await this._dcBoardStocks(code, 5000);
        tried.push({ src: '东财报表', note: dc.length ? `${dc.length} 只` : '0 只' });
        if (dc.length) return this._attachQuotes(dc);
      } catch (e) { tried.push({ src: '东财报表', note: '异常 ' + (e && e.message || e) }); }
    }

    // 4) 本站 CDN 静态快照（data/board-members.json）：**零第三方 API、零限流、零配额**。
    //    随站点发布并被 CDN 边缘缓存 —— 一万用户各自拉一份也只是边缘命中，这是最抗量的那条路。
    //    放在报表之后：报表永远是最新的，快照只负责「报表取不到时不至于没数据」。
    try {
      const snap = await this._snapshotBoardStocks(code, name);
      tried.push({ src: '本站快照', note: snap.length ? `${snap.length} 只` : '未收录' });
      if (snap.length) return this._attachQuotes(snap);
    } catch (e) { tried.push({ src: '本站快照', note: '异常 ' + (e && e.message || e) }); }

    // 5) 新浪「按板块名」兜底（非东财 / 免费 / CORS 开放 / 不限流）。
    //    只做完全同名匹配，避免把「证券Ⅱ」错配到含义不同的新浪板块上。
    if (name) {
      try {
        const byName = await this._sinaStocksByBoardName(name);
        tried.push({ src: '新浪按名', note: byName.length ? `${byName.length} 只` : '无同名板块' });
        if (byName.length) return byName;
      } catch (e) { tried.push({ src: '新浪按名', note: '异常 ' + (e && e.message || e) }); }
    }

    return [];
  },

  /**
   * 获取某板块成分股（含总市值，用于语义搜索的"核心/龙头"排序）
   * @param {string} bk 板块代码，如 BK0896
   * @param {number} maxPages 最多翻几页（默认 15，单页 100 条）
   * @param {string} [name] 板块名（可选；仅用于末档「按名兜底」）
   * @returns {Promise<Array<{code,name,price,changePercent,marketCap}>>}
   */
  async getSectorStocksMeta(bk, maxPages = 15, name) {
    const _bk = this._normalizeBoardCode(bk);
    return this._withCache('ssm:' + _bk + ':' + maxPages, API_TTL.SECTOR,
      () => this._getSectorStocksMetaRaw(_bk, maxPages, name), v => !!(v && v.length));
  },

  async _getSectorStocksMetaRaw(bk, maxPages = 15, name) {
    const code = this._normalizeBoardCode(bk);
    // 交集筛选生成的虚拟板块：无公开接口，短路（语义搜索重算时由源板块负责）
    if (this._isVirtualBoard(code)) return [];
    // 新浪板块：同源走新浪成分股（含总市值），保证语义搜索的「核心/龙头」排序可用
    if (this._isSinaBoard(code)) {
      const list = await this._sinaSectorStocks(code, maxPages);
      if (list.length) return list;
    }
    // 指数板块：复用指数成分股完整信息（含总市值），与 getSectorStocks 同源
    if (this._isIndexBoard(code)) {
      const idx = await this._getIndexConstituents(code);
      if (idx.length) return idx;
    }
    // 🔴 batch53：BK 板块优先数据中心报表（一次拿全）。**已移除 push2 兜底**——
    //   该接口限流且在浏览器侧已直接 Failed to fetch，留着只会让「编辑板块后重算」静默变 0 条。
    if (/^BK\d+$/i.test(code)) {
      const dc = await this._attachQuotes(await this._dcBoardStocks(code, 5000));
      if (dc.length) return dc;
    }
    // 兜底：本站 CDN 静态快照（零第三方 API）→ 新浪按名（非东财 / 免费 / CORS）
    const snap = await this._snapshotBoardStocks(code, name);
    if (snap.length) return this._attachQuotes(snap);
    const byName = await this._sinaStocksByBoardName(name, maxPages);
    if (byName.length) return byName;
    return [];
  },

  /**
   * 判断板块代码是否为「指数板块」（纯 6 位数字，如 000097 / 931071）。
   * 概念/行业板块代码为 BKxxxx（字母开头），可用 push2 fs=b:BKxxxx 直接拉成分股；
   * 指数板块必须用东财数据中心 RPT_INDEX_COMPONENT 取成分股代码，再用行情接口补全名称/价格。
   */
  _isIndexBoard(bk) {
    const c = this._normalizeBoardCode(bk);
    return /^\d{6}$/.test(c || '');
  },

  /**
   * 通过东财数据中心获取指数成分股代码清单（RPT_INDEX_COMPONENT，按 INDEX_CODE 过滤）。
   * 该接口无 CORS 头，浏览器端 fetch 失败时用 JSONP(cb) 兜底；字段仅含 SECURITY_CODE（无名称）。
   * @param {string} indexCode 指数代码，如 000097 / 931071
   * @returns {Promise<string[]>} 6 位股票代码数组
   */
  async _getIndexConstituentCodes(indexCode) {
    const codes = [];
    for (let pn = 1; pn <= 10; pn++) {
      const url = `https://datacenter-web.eastmoney.com/api/data/v1/get?reportName=RPT_INDEX_COMPONENT&columns=SECURITY_CODE&filter=(INDEX_CODE%3D%22${indexCode}%22)&pageNumber=${pn}&pageSize=100&source=WEB&client=WEB`;
      let json = null;
      try {
        const resp = await fetch(url, { cache: 'no-store' });
        json = await resp.json();
      } catch (e) { /* fetch 被 CORS 拦截，走 JSONP 兜底 */ }
      if (!json) {
        try { json = await this._eastJsonp(url, 9000); } catch (e) { /* 忽略 */ }
      }
      const data = (json && json.result && json.result.data) || [];
      if (!Array.isArray(data) || !data.length) break;
      for (const it of data) { if (it.SECURITY_CODE) codes.push(String(it.SECURITY_CODE)); }
      if (data.length < 100) break;
      await new Promise(r => setTimeout(r, 200));
    }
    return codes;
  },

  /**
   * 批量获取股票行情（名称/最新价/涨跌幅/总市值），补全指数成分股的展示字段。
   * 走 push2 qt/ulist.np/get（与板块成分股同源，_eastFetch 自带 JSONP 兜底）。
   * @param {string[]} codes 6 位股票代码
   * @returns {Promise<Object>} key=secid(市场.代码)，value={name,price,changePercent,marketCap}
   */
  async _batchQuote(codes) {
    if (!codes.length) return {};
    const toSecid = (c) => (/^[69]/.test(c) ? '1.' : '0.') + c;
    const secids = codes.map(toSecid).join(',');
    // 注意：qt/ulist.np/get 与 clist 同款字段编号（f12=代码, f14=名称, f2=价格, f3=涨跌幅, f20=总市值）
    const url = `https://push2.eastmoney.com/api/qt/ulist.np/get?fltt=2&invt=2&fields=f12,f14,f2,f3,f20&secids=${secids}`;
    const json = await this._eastFetch(url);
    const diff = (json && json.data && json.data.diff) || [];
    const map = {};
    const list = Array.isArray(diff) ? diff : Object.values(diff);
    for (const it of list) {
      if (!it) continue;
      const pure = String(it.f12 || '').replace(/\.\w+$/, '');
      if (!pure) continue;
      map[toSecid(pure)] = {
        name: it.f14 || '',
        price: it.f2 != null ? parseFloat(it.f2) : null,
        changePercent: it.f3 != null ? parseFloat(it.f3) : null,
        marketCap: it.f20 != null ? parseFloat(it.f20) : null
      };
    }
    return map;
  },

  /**
   * 获取指数板块成分股完整信息（代码/名称/价格/涨跌幅/总市值）。
   * 组合 RPT_INDEX_COMPONENT（代码清单）+ push2 批量行情（名称/价格）。
   * @param {string} indexCode 指数代码
   * @returns {Promise<Array<{code,name,price,changePercent,marketCap}>>}
   */
  async _getIndexConstituents(indexCode) {
    const codes = await this._getIndexConstituentCodes(indexCode);
    const quote = await this._batchQuote(codes);
    const out = [];
    for (const c of codes) {
      const secid = (/^[69]/.test(c) ? '1.' : '0.') + c;
      const q = quote[secid] || {};
      out.push({
        code: (/^[69]/.test(c) ? 'sh' : 'sz') + c,
        name: q.name || '',
        price: q.price != null ? q.price : null,
        changePercent: q.changePercent != null ? q.changePercent : null,
        marketCap: q.marketCap != null ? q.marketCap : null
      });
    }
    return out;
  },

  /**
   * AI 语义选股：把自然语言描述解析为"概念 + 修饰"，交叉匹配板块成分股，
   * 返回可直接展示的股票列表。纯前端、免费、无需后端 / API Key。
   *
   * 示例：「主营为ai安全的核心上市公司」
   *   → 识别概念 [人工智能, 安全]
   *   → 取「同时属于 AI 板块 与 安全板块」的公司（概念交集）
   *   → 修饰"核心" → 按总市值降序取前 20 家（代表性核心标的）
   *
   * @param {string} rawQuery 用户自然语言
   * @returns {Promise<{ok,query,concepts,modifiers,method,boards,stocks,error}>}
   */
  /**
   * 营收占比相关度 语义选股引擎（统一入口）。
   * 核心算法：相关度 = 命中语义描述的主营业务/产品段之「营收占比」之和（%）。
   *
   * batch45 重构：候选池与取数全部改走**东财数据中心报表**，零 push2 依赖。
   *   查询词 --EAST_BOARD_LIST 本地匹配--> 东财板块名
   *          --BOARDTYPE 报表反查--> 板块成分股
   *          --MAINOP 报表批量 SECUCODE in(...)--> 最新一期「按产品」主营构成
   *          --> 命中段营收占比之和降序
   * 两条检索档位：
   *   - 'boards'（默认，快）：板块级候选池（上百~上千只）+ 批量主营构成，约 1~3s；
   *   - 'deep'（深度）：当板块级召回不足（< DO_NOT_FOUND_MIN）或用户显式要求时，
   *     启用**全市场主营构成索引**纯本地匹配（一次构建、会话内 + 3 天本地缓存复用）。
   *
   * @param {object} p
   *  - query, matchers{buildMatchers 结果}, modifiers, seedCodes, productKey, productDesc, productStocks, explicitBoards, forceDeep
   */
  async _revenueSearch({ query, matchers, modifiers, seedCodes = [], productKey = '', productDesc = '', productStocks = [], explicitBoards = null, forceDeep = false, onProgress = null }) {
    // 0) 段名匹配词：核心词必含、领域词仅加权（避免「火电发电设备」误命中火电运营商）
    const DOMAIN_LIST = [...DOMAIN_MODIFIERS];
    let coreArr = (matchers.segHints || []).map(s => String(s).toLowerCase())
      .filter(t => !DOMAIN_MODIFIERS.has(t))
      .filter(t => !(t.length <= 4 && DOMAIN_LIST.some(d => t.includes(d))));
    if (!coreArr.length) coreArr = (matchers.segHints || []).map(s => String(s).toLowerCase());
    const domainArr = (matchers.domain || []).map(s => String(s).toLowerCase());
    if (!coreArr.length) {
      return {
        ok: false, query, concepts: (matchers.concepts || []), modifiers,
        error: '未能从描述里提取到可匹配的业务/产品词，请更具体些，如「谐波减速器」「国产芯片」「储能」'
      };
    }
    const roleMap = {};
    productStocks.forEach(s => { roleMap[s.code] = s.role || ''; });

    // 1) 把「概念 + 查询词」本地匹配到东财板块名（零网络）
    //  - 有概念命中：用概念的 canonical + hints 各自匹配板块名（hints 本身就是东财板块名，命中率高）
    //  - 通用兜底：用「完整查询词」优先匹配（整词优先，绝不拆词曲解），再退化为抽取词
    let boardHits = [];           // [{name, code, score}]
    const boardSeen = new Set();
    const pushBoards = (arr) => {
      for (const b of arr) {
        if (!b || !b.code || boardSeen.has(b.code)) continue;
        boardSeen.add(b.code);
        boardHits.push(b);
      }
    };
    if (explicitBoards && explicitBoards.length) {
      pushBoards(explicitBoards.map(b => ({
        name: b.name || b.bk, code: /^BK\d+$/i.test(String(b.bk || b.code || '')) ? String(b.bk || b.code).toUpperCase() : '', score: 1000
      })).filter(b => b.code));
      // 显式板块也可能是新浪代码（老数据），保留原始 bk 交给下游兜底
      for (const b of explicitBoards) {
        const raw = String(b.bk || b.code || '');
        if (raw && !/^BK\d+$/i.test(raw) && !boardSeen.has('raw:' + raw)) {
          boardSeen.add('raw:' + raw);
          boardHits.push({ name: b.name || raw, code: raw, raw: true, score: 900 });
        }
      }
    } else {
      const CAP_PER = 4;
      for (const canon of (matchers.concepts || [])) {
        const c = SEMANTIC_CONCEPTS.find(x => x.canonical === canon);
        const keys = [canon].concat((c && c.hints) || []);
        const one = [];
        const seen = new Set();
        for (const k of keys) {
          for (const b of this._dcMatchBoards(k, CAP_PER)) {
            if (seen.has(b.code)) continue;
            seen.add(b.code);
            one.push(b);
          }
          if (one.length >= CAP_PER) break;
        }
        pushBoards(one.slice(0, CAP_PER));
      }
      // 通用词兜底（完全没有概念命中时）
      if (!boardHits.length) {
        const fullQ = String(query || '').trim();
        const tries = [];
        if (fullQ) tries.push(fullQ);
        // 产品库命中 → 产品名本身就是东财板块名时直接命中（如「复合铜箔」→ 产品「复合集流体」→ 板块「复合集流体」）
        if (productKey) tries.push(productKey);
        // 产品 → 板块别名（如「发电设备」→「电力设备」）
        const aliasKey = BOARD_NAME_ALIASES[fullQ.toLowerCase()] || BOARD_NAME_ALIASES[stripCategorySuffix(fullQ.toLowerCase())] || [];
        aliasKey.forEach(a => tries.push(a));
        // 抽取词（已剔除通用类别词碎片）
        (matchers.generic || []).forEach(g => tries.push(g));
        const seen = new Set();
        const one = [];
        for (const t of tries) {
          for (const b of this._dcMatchBoards(t, 6)) {
            if (seen.has(b.code)) continue;
            seen.add(b.code);
            one.push(b);
          }
          if (one.length >= 8) break;
        }
        pushBoards(one.slice(0, 8));
      }
    }
    boardHits.sort((a, b) => b.score - a.score);
    boardHits = boardHits.slice(0, 10);

    // 2) 候选池：并发反查各板块成分股（数据中心报表，不经 push2）
    //    batch53：同时记录**每个候选来自哪块板块、该板块名与查询词的匹配质量**。
    //    这是新增「板块成员」召回通道的数据基础（见下方 3c）。
    const stockInfo = new Map();   // code → { code, name }
    const stockBoard = new Map();  // code → { name, score }（最强的那块板块）
    const lists = await this._mapLimit(boardHits, 6, async (b) => {
      try {
        if (b.raw) {
          const l = await this.getSectorStocksMeta(b.code, 6, b.name);
          return { b, codes: (l || []).map(s => ({ code: this._normalizeCode(s.code), name: s.name || '' })) };
        }
        const l = await this._dcBoardStocks(b.code, 2000);
        return { b, codes: (l || []).map(s => ({ code: s.code, name: s.name })) };
      } catch (e) { return { b, codes: [] }; }
    });
    for (const r of lists) {
      for (const s of ((r && r.codes) || [])) {
        if (!s.code || !/^(sh|sz|bj)\d{6}$/.test(s.code)) continue;
        if (!stockInfo.has(s.code)) stockInfo.set(s.code, s);
        const prev = stockBoard.get(s.code);
        if (!prev || (r.b && r.b.score > prev.score)) {
          stockBoard.set(s.code, { name: (r.b && r.b.name) || '', score: (r.b && r.b.score) || 0 });
        }
      }
    }
    // 产品库种子强制纳入（用户期望的生产厂商必须出现）
    seedCodes.forEach(c => { const cc = this._normalizeCode(c); if (cc && !stockInfo.has(cc)) stockInfo.set(cc, { code: cc, name: '' }); });

    // 3) 先用「板块级候选池」做一轮：批量取主营构成 → 按命中营收占比打分
    //    注意 mbMap 只增不减，后面若升级为全市场扫描，直接在上面叠加即可，不重复请求。
    const mbMap = await this._dcMainBizBatch([...stockInfo.keys()]);
    const bizOf = async (code) => mbMap.get(code) || (await this.getMainBusiness(code));
    const scoreAll = async (core) => {
      const arr = [];
      for (const [code, info] of stockInfo) {
        const rr = revenueRelevance(await bizOf(code), core, domainArr);
        if (rr.relevance > 0) arr.push({ info, relevance: rr.relevance, raw: rr.raw, matched: rr.matched, kind: 'segment' });
      }
      return arr;
    };
    const scoreWithFallback = async () => {
      let s = await scoreAll(coreArr);
      // batch60：组词/产品级严格匹配一无所获 → 用碎片泛词兜底重试（宁可召回放宽，也绝不返回 0 结果）。
      // 兜底后 coreArr 会被替换成碎片词——重算与展示都沿用替换后的实际匹配词。
      // 【关键约束】组词查询（compound 非空）**禁用碎片兜底**——用户的「特种电缆」是整词，
      //   绝不允许退化成「特种」「电缆」碎片分别命中（否则 特种装备 / 电缆料 这类错误结果都算进来）。
      //   组词整词 0 命中就返回 0（配合全市场深度扫描，已保证对全市场主营构成做过整词匹配）。
      const canBroaden = !(matchers.compound && matchers.compound.length);
      if (!s.length && canBroaden && (matchers.broadSegHints || []).length) {
        const broad = matchers.broadSegHints.map(t => String(t).toLowerCase());
        const retry = await scoreAll(broad);
        if (retry.length) { coreArr = broad; return retry; }
      }
      return s;
    };

    let scored = await scoreWithFallback();
    let usedDeep = false;

    // 3b) 召回不足（或用户点了「全市场深度扫描」）→ 升级为**全市场主营构成索引**再算一遍。
    //     阈值 8：板块级只能凑出个位数结果时，基本可以断定「这个业务/产品还有更多公司没被板块库覆盖」。
    //     索引为一次性成本（约 100+ 页），本会话 + localStorage（3 天）复用，之后同类搜索均为毫秒级。
    if (forceDeep || scored.length < 8) {
      const idx = await this._allMarketMainBizIndex(onProgress);
      if (idx && idx.size) {
        usedDeep = true;
        for (const [sc, arr] of idx) {
          const pre = this._dcPrefix(sc);
          const pure = sc.split('.')[0];
          if (!pre || !/^\d{6}$/.test(pure)) continue;
          const code = pre + pure;
          if (!stockInfo.has(code)) stockInfo.set(code, { code, name: '' });
          if (!mbMap.has(code)) mbMap.set(code, arr.map(([name, ratio]) => ({ name, ratio })));
        }
        const deepScored = await scoreWithFallback();
        // 全市场结果必然覆盖板块级结果（是超集）→ 直接用更全的那一份
        if (deepScored.length >= scored.length) scored = deepScored;
      }
    }

    // 3c) 🔴 batch53 新增：**板块归属 / 行业归属** 召回通道（与「主营段名」通道取并集）。
    //
    //     为什么必须加（实测定位，这就是「输入证券却看不到银河证券 / 国泰证券」的根因）：
    //       段名是各家公司**自报的业务线名称**，用词千差万别 —— 同一行业的公司命名并不统一，
    //       于是召回率只取决于「这家公司恰好怎么给分段起名」，完全随机。
    //       实测「证券」：券商板块（证券Ⅱ / BK0473）共 **49 只**，
    //         其中**只有 21 只**的主营段名含「证券」→ **28 只被静默丢掉（57% 缺失）**：
    //           中信证券 = 证券投资业务 / 证券承销业务            → 含「证券」✓
    //           中国银河 = 财富管理业务 / 投资交易业务 / 机构业务…  → 不含 ✗（被丢）
    //           国泰海通 = 机构与交易 / 财富管理 / 投资管理…        → 不含 ✗（被丢）
    //       而它们的**板块/行业归属是统一且 100% 覆盖的**（49/49 = 非银金融 / 证券Ⅱ / 金融业-资本市场服务）。
    //
    //     门槛（防止过度扩张，宁可少召回也不给噪声）：
    //       · 板块通道：只采信板块名与查询词匹配分 ≥ 700 的板块（完全相同/前缀/包含），
    //         不采信「被包含」档（查询「谐波减速器」会被「减速器」板块以 500 分捞进来）；
    //       · 行业通道：仅深度模式构建（成本 2 页），且只认「行业名以核心词开头或完全相等」。
    //     两者产出的条目 `relevance = 0`（**不伪造营收占比**），仅在 UI 上标注命中来源，
    //     排序时自然排在「段名命中」之后。
    const BOARD_MEMBER_MIN_SCORE = 700;
    const IND_MAX_EXTRA = 400;
    const channelHits = new Map();     // code → { kind, via }
    for (const [code, b] of stockBoard) {
      if (b && b.score >= BOARD_MEMBER_MIN_SCORE) channelHits.set(code, { kind: 'board', via: b.name });
    }
    if (usedDeep && coreArr.length) {
      try {
        const indIdx = await this._allMarketIndustryIndex();
        let extra = 0;
        for (const [sc, ind] of indIdx) {
          if (extra >= IND_MAX_EXTRA) break;
          const pre = this._dcPrefix(sc);
          const pure = sc.split('.')[0];
          if (!pre || !/^\d{6}$/.test(pure)) continue;
          const code = pre + pure;
          if (channelHits.has(code) && channelHits.get(code).kind === 'board') continue;
          const names = [ind.l2, ind.l1, ind.csrc].filter(Boolean).map(s => s.toLowerCase());
          const hitName = names.find(n => coreArr.some(t => t.length >= 2 && (n === t || n.startsWith(t))));
          if (!hitName) continue;
          if (!stockInfo.has(code)) { stockInfo.set(code, { code, name: ind.name || '' }); extra++; }
          if (!channelHits.has(code)) channelHits.set(code, { kind: 'industry', via: ind.l2 || ind.l1 || ind.csrc });
        }
      } catch (e) { /* 行业索引拿不到 → 只保留板块通道 */ }
    }
    // 把「通道命中但段名未命中」的补进来（段名已命中的保持原样，不重复）
    const scoredCodes = new Set(scored.map(x => x.info.code));
    let chanAdded = 0;
    for (const [code, ch] of channelHits) {
      if (scoredCodes.has(code)) continue;
      const info = stockInfo.get(code);
      if (!info) continue;
      scored.push({ info, relevance: 0, raw: 0, matched: [], kind: ch.kind, via: ch.via });
      chanAdded++;
    }

    // 4) 补齐行情（腾讯批量；**含产品库种子**，保证种子公司也带名称），组装结果
    const seedNorm = seedCodes.map(c => this._normalizeCode(c)).filter(Boolean);
    const quoteCodes = [...new Set([...scored.map(x => x.info.code), ...seedNorm])];
    let quotes = {};
    try { quotes = await this.getQuotes(quoteCodes.slice(0, 800)); } catch (e) { quotes = {}; }
    const buildStock = (x) => {
      const q = quotes[x.info.code] || {};
      const mkt = q.totalMarketCap != null ? q.totalMarketCap * 1e8 : (x.info.marketCap || null);
      return {
        code: x.info.code,
        name: q.name || x.info.name || x.info.code,
        price: q.price != null ? q.price : null,
        changePercent: q.changePercent != null ? q.changePercent : null,
        marketCap: mkt,
        role: '',
        concepts: (matchers.concepts || []).slice(),
        matchedSegments: x.matched,
        relevance: x.relevance,
        rawRelevance: x.raw,
        // batch53：命中来源。'segment' 主营段名命中（相关度 = 段营收占比之和）；
        //          'board' 板块成员命中（相关度 0，不伪造比例）；'industry' 行业归属命中。
        matchKind: x.kind || 'segment',
        matchVia: x.via || ''
      };
    };
    let stocks = scored.map(buildStock);
    // 产品库兜底：种子公司在主营构成里未列明细（相关度=0）时，按产业链角色评分保底补入
    if (productKey) {
      const have = new Set(stocks.map(s => s.code));
      for (const code of seedNorm) {
        if (have.has(code)) continue;
        const rr = revenueRelevance(await bizOf(code), coreArr, domainArr);
        const st = buildStock({ info: { code, name: '' }, relevance: rr.relevance, raw: rr.raw, matched: rr.matched, kind: 'product' });
        const roleScore = scoreRoleRelevance(roleMap[code] || '');
        st.relevance = st.relevance > 0 ? st.relevance : roleScore;
        st.matchedSegments = st.matchedSegments || [];
        st.concepts = (matchers.concepts || []).slice();
        st.matchKind = 'product';
        stocks.push(st);
      }
    }
    // 排序：**按命中主营段营收占比降序** = 用户要的「按所占营收比例排序」。
    // 用未封顶的 rawRelevance 排序：否则多家都是 100% 时会退化成按总市值排，丢掉「占比更高者优先」的语义。
    // 相关度 0 的「板块成员 / 行业归属」自然排在末尾（同档内按总市值降序，龙头在前）。
    const sortKey = (s) => Math.max(s.rawRelevance || 0, s.relevance || 0);
    stocks.sort((a, b) => (sortKey(b) - sortKey(a)) || ((b.marketCap || 0) - (a.marketCap || 0)));
    const TOPN = 20;
    if (modifiers.includes('核心')) stocks = stocks.slice(0, TOPN);
    else if (modifiers.includes('小市值')) {
      stocks = [...stocks].sort((a, b) => (a.marketCap || 0) - (b.marketCap || 0)).slice(0, TOPN)
        .sort((a, b) => (sortKey(b) - sortKey(a)) || ((b.marketCap || 0) - (a.marketCap || 0)));
    }
    const segCount = stocks.filter(s => s.matchKind === 'segment').length;
    return {
      ok: true, query,
      concepts: matchers.concepts || [],
      modifiers,
      method: productKey ? 'product' : (usedDeep ? 'deep' : (explicitBoards && explicitBoards.length ? 'boards' : 'revenue')),
      productKey, productDesc,
      // batch60：返回**实际生效**的段名匹配词（组词整词或兜底碎片），编辑概念/板块后「重算」沿用同一口径
      matchers: coreArr.slice(),
      boards: boardHits.map(b => ({ bk: b.code, name: b.name })),
      stocks,
      scan: {
        pool: stockInfo.size, deep: usedDeep, matched: stocks.length,
        segment: segCount, channel: stocks.length - segCount, channelAdded: chanAdded
      }
    };
  },

  async semanticSearch(rawQuery, opts = {}) {
    const query = String(rawQuery || '').trim();
    if (!query) return { ok: false, error: '请输入描述，如：生产薄膜铌酸锂的企业 / 主营为ai安全的核心上市公司 / ai短剧审核' };
    const ql = query.toLowerCase();
    const modifiers = parseSemanticModifiers(query);
    const matchers = buildMatchers(query);

    // 命中已知产品库：作为候选种子 + 段名匹配补充，最终仍由主营构成营收占比计算相关度
    let seedCodes = [], productKey = '', productDesc = '', productStocks = [];
    const product = matchProduct(ql);
    if (product) {
      seedCodes = product.stocks.map(s => s.code);
      productStocks = product.stocks;
      productKey = product.key;
      productDesc = product.desc;
      // 产品级：段名匹配词**只取产品族本身**（见 productCoreTerms 注释），
      // 避免被所属概念的泛词（传感器/电机/丝杠…）带偏成「同赛道」而不是「同产品」。
      // 同时把概念泛词存进 broadSegHints —— 产品级严格匹配若一无所获，用它兜底重试。
      const strictCore = productCoreTerms(query, product);
      matchers.broadSegHints = (matchers.segHints || []).slice();
      matchers.segHints = strictCore;
      matchers.productCore = strictCore;
      if (!matchers.concepts.length) matchers.concepts.push(product.key);
    }

    if (!matchers.concepts.length && !matchers.generic.length) {
      return {
        ok: false, query, concepts: [], modifiers,
        error: '未识别到可检索的业务/产品词，请更具体些，如：谐波减速器 / 国产芯片 / 储能 / 人工智能'
      };
    }
    // batch60：组词处理 —— ① 把组词整词放进「识别概念」首位（识别和命中都带上这个组词）；
    // ② 纯组词查询（没命中概念本体、也没命中产品库，如「特种电缆」）强制走全市场主营构成扫描，
    //    保证对**全市场的主营业务和产品**进行扫描，不漏掉板块库覆盖不到的公司。
    const hasCompound = !!(matchers.compound && matchers.compound.length);
    const hadConceptHit = matchers.concepts.length > 0;
    if (hasCompound) matchers.concepts = [...matchers.compound, ...matchers.concepts];
    try {
      return await this._revenueSearch({
        query, matchers, modifiers, seedCodes, productKey, productDesc, productStocks,
        forceDeep: !!opts.deep || (hasCompound && !hadConceptHit && !product),
        onProgress: opts.onProgress || null
      });
    } catch (e) {
      return { ok: false, query, concepts: matchers.concepts, modifiers, error: 'AI语义筛选失败：' + (e && e.message ? e.message : e) };
    }
  },

  /**
   * 把一个"概念"自然语言解析为其对应的东方财富板块列表。
   * 用于「语义结果编辑」后，根据用户修改后的概念重建命中板块。
   *   - 命中已知概念本体（SEMANTIC_CONCEPTS）：按其 hints 匹配板块并按相关度排序取前 12；
   *   - 未命中本体：按板块名模糊匹配取前 12。
   * @param {string} concept
   * @returns {Promise<Array<{bk,name}>>}
   */
  async resolveConceptToBoards(concept) {
    const c = String(concept || '').trim();
    if (!c) return [];
    const cl = c.toLowerCase();
    const found = SEMANTIC_CONCEPTS.find(x =>
      x.canonical.toLowerCase() === cl ||
      x.aliases.some(a => a.length >= 2 && a.toLowerCase() === cl) ||
      x.aliases.some(a => a.length >= 2 && cl.includes(a.toLowerCase())) ||
      x.hints.some(h => h.length >= 2 && cl.includes(h.toLowerCase()))
    );
    const all = await this.getAllSectors();
    // batch45：优先用「东财板块名词典」本地匹配（零网络、且不依赖 push2 / 新浪板块是否含该概念）
    const keys = found ? [found.canonical].concat(found.hints || []) : [c];
    const out = new Map();
    for (const k of keys) {
      for (const b of this._dcMatchBoards(k, 4)) if (!out.has(b.code)) out.set(b.code, { bk: b.code, name: b.name });
      if (out.size >= 12) break;
    }
    if (out.size) return [...out.values()].slice(0, 12);
    // 兜底：词典没命中时退回全量板块名模糊匹配（兼容新浪板块命名）
    if (found) {
      return all
        .filter(b => found.hints.some(h => b.name.toLowerCase().includes(h.toLowerCase())))
        .sort((a, b) => semanticNameScore(b.name, found.canonical) - semanticNameScore(a.name, found.canonical))
        .slice(0, 12)
        .map(b => ({ bk: b.bk, name: b.name }));
    }
    return all
      .filter(b => b.name.toLowerCase().includes(cl))
      .slice(0, 12)
      .map(b => ({ bk: b.bk, name: b.name }));
  },

  /**
   * 按关键词搜「东财板块名」（本地词典，**零网络请求**）。
   * 供语义结果的「命中板块」增删使用——不依赖 push2、也不依赖新浪板块是否收录该主题。
   * @returns {Array<{bk:string, name:string}>}
   */
  searchBoardNames(kw, limit = 12) {
    return this._dcMatchBoards(kw, limit).map(b => ({ bk: b.code, name: b.name }));
  },

  /**
   * 语义结果「重算引擎」：根据当前板块列表 + 修饰词，重新计算符合语义的上市公司。
   * 这是概念/板块增删改之后的核心逻辑：
   *   - 多板块取成分股「交集」= 同时归属这些板块的公司（主业同时符合多个主题）；
   *   - 单板块直接取该板块全部成分股；
   *   - 修饰词：核心/龙头 → 按总市值降序取前 20；小市值 → 升序取前 20；
   *   - 最后补齐腾讯实时行情（现价/涨跌幅/总市值）。
   * @param {{boards:Array<{bk,name}>, modifiers?:string[], concepts?:string[]}} params
   * @returns {Promise<{ok,stocks,method,boards}>}
   */
  async recomputeSemanticStocks({ boards, modifiers = [], concepts = [], matchers = [], productKey = '', productDesc = '' }) {
    if (!boards || !boards.length) return { ok: true, stocks: [], method: 'empty', boards: [] };
    // 优先使用上一次搜索的业务意图(matchers，即营收占比相关度的匹配词)；
    // 否则由 concepts 重建 matchers，保证「编辑概念/板块后重算」仍按主营构成营收占比计算相关度。
    let m;
    if (matchers && matchers.length) {
      m = { concepts: (concepts || []).slice(), segHints: matchers.slice(), generic: [], boardHints: [] };
    } else {
      m = buildMatchers((concepts || []).join(' '));
    }
    try {
      return await this._revenueSearch({
        query: (concepts || []).join('+'),
        matchers: m,
        modifiers,
        seedCodes: [],
        productKey,
        productDesc,
        productStocks: [],
        explicitBoards: boards.map(b => ({ bk: b.bk, name: b.name }))
      });
    } catch (e) {
      return { ok: false, stocks: [], method: 'error', boards: boards.slice(), error: '重算失败：' + (e && e.message ? e.message : e) };
    }
  },

  // ============ 工具方法 ============

  _addDays(date, n) {
    const d = new Date(date);
    d.setDate(d.getDate() + n);
    return d;
  },

  fmtDate(d) {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  },

  // ============ 火热话题 / 全球信息 ============

  /**
   * 抓取「火热话题」：按用户指定排序从 10 个金融软件分别拉取 Top10 影响股市的新闻。
   * 经 Cloudflare Worker 代理（东方财富走 /news，其余走 /proxy?url=）绕过跨域，逐源并行容错。
   * 每条自动用 HotTopics.classify 打 7 类标签（财经/政治政策/经济/军事/科技/社会热点/百强企业）。
   * @returns {Promise<{ok:boolean, error?:string, sources:Array, merged:Array}>}
   */
  async fetchHotTopics(proxyUrl) {
    const base = (proxyUrl || '').trim().replace(/\/+$/, '');
    if (!base) return { ok: false, error: '未配置新闻代理地址', sources: [], merged: [] };
    return this._withCache('hot:' + base, API_TTL.NEWS,
      () => this._fetchHotTopicsRaw(base), v => !!(v && v.ok !== false));
  },

  async _fetchHotTopicsRaw(base) {
    const srcList = (typeof HotTopics !== 'undefined' && HotTopics.SOURCE_ORDER) || [];
    const sources = srcList.map(s => ({ ...s, items: [], loading: true, error: null }));
    const today = this._todayStr();
    await Promise.all(sources.map(async (s) => {
      try {
        let items = [];
        if (s.parse === 'news_eastmoney') {
          // 主：Worker 专用 /news（东方财富 7x24）；失败则回退抓东财 HTML 列表页
          try {
            const j = await this._proxyJson(`${base}/news?page=1&size=20`);
            const list = (j.data && j.data.list) || [];
            items = list.slice(0, 10).map(it => this._mkItem(
              [it.title, it.summary].filter(Boolean).join('：').slice(0, 90),
              this._normTime(it.showTime), it.uniqueUrl || ''
            )).filter(it => it.text);
          } catch (e) { /* 走下面的 HTML 兜底 */ }
          if (!items.length) {
            const html = await this._proxyText(`${base}/proxy?url=${encodeURIComponent(s.endpoint || s.fallback || 'https://finance.eastmoney.com/')}`);
            items = this._extractFromHtml(html, s.key, s.base).slice(0, 10);
          }
        } else {
          const txt = await this._proxyText(`${base}/proxy?url=${encodeURIComponent(s.endpoint)}`);
          items = this._parseHotSource(s.parse, s.key, txt).slice(0, 10);
        }
        s.items = items;
        if (!items.length) s.error = '解析为空（源页面结构变化或非新闻页）';
      } catch (e) {
        s.error = this._friendlyFetchError(e);
      } finally {
        s.loading = false;
      }
    }));
    const merged = [];
    for (const s of sources) for (const it of s.items) merged.push({ ...it, source: s.name, color: s.color, sourceRank: s.rank });
    merged.sort((a, b) => (b.time || '').localeCompare(a.time || ''));
    return { ok: true, date: today, sources, merged: merged.slice(0, 20) };
  },

  /** 经代理取文本（12s 超时，非 2xx 直接抛错） */
  async _proxyText(url) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 12000);
    try {
      const resp = await fetch(url, { signal: ctrl.signal, cache: 'no-store' });
      if (!resp.ok) throw new Error('HTTP ' + resp.status);
      return await resp.text();
    } finally {
      clearTimeout(timer);
    }
  },

  /** 经代理取 JSON */
  async _proxyJson(url) {
    const txt = await this._proxyText(url);
    try { return JSON.parse(txt); } catch (e) { throw new Error('返回非 JSON'); }
  },

  /** 把网络层异常翻译成用户能看懂的原因 */
  _friendlyFetchError(e) {
    const m = (e && e.message) || String(e || '');
    if (/AbortError|aborted|timeout|timed out/i.test(m)) return '代理超时（源站响应过慢）';
    if (/Failed to fetch|NetworkError|Network request failed|fetch failed|Load failed|ERR_/i.test(m)) return '代理不可达（域名被拦截或网络异常）';
    return m || '抓取失败';
  },

  /** 统一构造带分类标签的条目（标题经共享规则净化，垃圾/乱码直接丢弃） */
  _mkItem(text, time, url) {
    const clean = (typeof HotTopics !== 'undefined' && HotTopics.cleanTitle)
      ? HotTopics.cleanTitle(text)
      : (text || '').toString().replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().slice(0, 90);
    const cat = (typeof HotTopics !== 'undefined' && HotTopics.classify) ? HotTopics.classify(clean) : '财经';
    return { text: clean, time: this._normTime(time), url: url || '', cat };
  },

  /** 按 parse 类型解析不同金融软件的返回结构，统一为 [{text,time,url,cat}] */
  _parseHotSource(parse, key, txt) {
    const out = [];
    const push = (text, time, url) => {
      const it = this._mkItem(text, time, url);
      if (it.text) out.push(it);
    };
    let j = null;
    try { j = JSON.parse(txt); } catch (e) { j = null; }

    if (parse === 'json_toutiao' && j) {
      const arr = (j.data || []);
      for (const it of arr) {
        let u = it.Url || '';
        if (u && !/^https?:/i.test(u)) u = 'https://www.toutiao.com/' + u.replace(/^\//, '');
        push(it.Title || it.title, '', u);
      }
    } else if (parse === 'json_wscn' && j) {
      /* 请求T：源站 api-prod.wallstreetcn.com 已下线（连接超时），改用 api-one + channel=global-channel。
       * ① uri 实测已是完整 https://wallstreetcn.com/livenews/<id>，旧代码又在前面拼了一次域名 → 双重前缀，已修；
       * ② content 是 HTML 富文本，仅当 content_text / title 都缺失时才兜底，需先去掉标签。 */
      const arr = (j.data && j.data.items) || [];
      for (const it of arr) {
        let u = String(it.uri || '').trim();
        if (u && !/^https?:/i.test(u)) {
          u = (u.indexOf('//') === 0) ? ('https:' + u) : ('https://wallstreetcn.com/' + u.replace(/^\//, ''));
        }
        const txt = it.content_text || it.title || String(it.content || '').replace(/<[^>]*>/g, '');
        push(txt, it.display_time, u || 'https://wallstreetcn.com/');
      }
    } else if (parse === 'json_sina' && j) {
      // 请求R：新浪财经 7x24 实时新闻（zhibo feed）→ result.data.feed.list[]，字段 rich_text / create_time / docurl
      let arr = (j.result && j.result.data && j.result.data.feed && j.result.data.feed.list)
        || (j.data && j.data.feed && j.data.feed.list)
        || (j.data && j.data.list) || (j.result && j.result.list)
        || (Array.isArray(j) ? j : []);
      if (!Array.isArray(arr)) arr = [];
      for (const it of arr) push(it.rich_text || it.content || it.title || it.text,
        it.create_time || it.time || it.ctime,
        it.docurl || it.url || 'https://finance.sina.com.cn/7x24/');
    } else if (parse === 'json_jin10' && j) {
      // 请求R：金十数据实时快讯 → data[]（或 data.items[]），字段 time / data.content / data.title / id
      let arr = Array.isArray(j) ? j : (Array.isArray(j.data) ? j.data : ((j.data && j.data.items) || []));
      if (!Array.isArray(arr)) arr = [];
      for (const it of arr) push((it.data && (it.data.content || it.data.title)) || it.content || it.title,
        it.time || it.ctime,
        it.id ? ('https://flash.jin10.com/detail/' + it.id) : 'https://flash.jin10.com/');
    } else if (parse === 'json_gelonghui' && j) {
      const arr = (j.result && j.result.data) || (j.data && j.data) || [];
      for (const it of arr) push(it.content || it.title || it.text, it.created_at || it.time, 'https://www.gelonghui.com/');
    } else if (parse && parse.indexOf('html_') === 0 && txt) {
      // HTML 兜底：抽取页面中的标题级文本
      return this._extractFromHtml(txt, key);
    } else if (j) {
      const arr = j.data || j.result || j.list || j.items || (j.data && j.data.list) || [];
      if (Array.isArray(arr)) {
        for (const it of arr) {
          if (typeof it === 'string') push(it);
          else push(it.title || it.text || it.content || it.summary || it.subject || it.digest || it.intro,
                    it.time || it.ctime || it.showTime || it.created_at,
                    it.url || it.link || it.uri);
        }
      }
    }
    return out.filter((v, i, a) => a.findIndex(x => x.text === v.text) === i);
  },

  /** 从 HTML 抽取候选标题（经 Worker /proxy 返回的 HTML 文本） */
  _extractFromHtml(html, key, baseOverride) {
    const out = [];
    const base = baseOverride
      || (typeof HotTopics !== 'undefined' && HotTopics.SOURCE_BY_KEY[key] && HotTopics.SOURCE_BY_KEY[key].base)
      || '';
    try {
      const doc = new DOMParser().parseFromString(html, 'text/html');
      // 去掉脚本/样式，避免抓到 JS 模板残留（如 ${title}）
      doc.querySelectorAll('script, style, noscript').forEach(el => el.remove());
      const seen = new Set();
      const candidates = [];
      const normUrl = (u) => {
        u = (u || '').trim();
        if (!u || /^javascript:/i.test(u) || u.charAt(0) === '#') return '';
        if (/^https?:/i.test(u)) return u;
        if (u.indexOf('//') === 0) return 'https:' + u;
        if (u.charAt(0) === '/' && base) return base + u;
        return base ? (base + '/' + u.replace(/^\//, '')) : u;
      };
      doc.querySelectorAll('a').forEach(a => {
        const t = (a.textContent || '').replace(/\s+/g, ' ').trim();
        if (t.length >= 6 && t.length <= 120) candidates.push({ t, url: normUrl(a.getAttribute('href') || '') });
      });
      doc.querySelectorAll('.title, .news-title, .headline, .item-title, h2, h3').forEach(el => {
        const t = (el.textContent || '').replace(/\s+/g, ' ').trim();
        if (t.length >= 6 && t.length <= 120) {
          const a = el.closest('a');
          candidates.push({ t, url: a ? normUrl(a.getAttribute('href') || '') : '' });
        }
      });
      for (const c of candidates) {
        const item = this._mkItem(c.t, '', c.url);
        if (!item.text || seen.has(item.text)) continue;
        seen.add(item.text);
        out.push(item);
        if (out.length >= 10) break;
      }
    } catch (e) { /* ignore */ }
    return out;
  },

  /** 归一化时间：unix 秒/毫秒 → 'YYYY-MM-DD HH:mm'，其它原样截取 */
  _normTime(t) {
    if (t == null) return '';
    t = String(t).trim();
    if (/^\d{10}$/.test(t)) return new Date(+t * 1000).toISOString().slice(0, 16).replace('T', ' ');
    if (/^\d{13}$/.test(t)) return new Date(+t).toISOString().slice(0, 16).replace('T', ' ');
    return t.replace('T', ' ').slice(0, 16);
  },

  _todayStr() {
    const d = new Date();
    const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, '0'), day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  },

};
